#  v23.3 — новое меню. Главное — выбор роли: «🙋 Я пассажир», «🚕 Я водитель»,
#    «📞 Я диспетчер». У пассажира — заказ, «Поехать вместе», мои заказы, брони,
#    тарифы. У водителя вместо «Мой профиль» — «Тарифы». У диспетчера —
#    «Выложить заказ», «Открытые заказы», «Закрытые заказы»; в карточке —
#    сколько выложено и выполнено. «🏠 Главное меню» везде; старые кнопки
#    «🔙 Главное меню» и «🚗 Я водитель» в чатах продолжают работать.
#    Ссылка с сайта ?start=new — сразу оформление заказа, без выбора роли
#
#  v23.2 — роль диспетчера: «📣 Я диспетчер» в главном меню. Диспетчер
#    регистрируется с контактом, админ подтверждает; абонемента нет, брать
#    заказы диспетчер не может. Свой заказ — на дату или «срочно», откуда,
#    куда, класс, люди, км, стоимость поездки и сколько на руки водителю
#    (разница — комиссия), платные дороги в цене или отдельно, комментарий.
#    Публикуется сразу, без модерации: водителям в Telegram и MAX и в оба
#    канала, с пометкой «Заказ от диспетчера». Водитель с абонементом жмёт
#    «Взять» — это отклик; диспетчер выбирает одного, остальным — «взят
#    другим водителем». Водитель и диспетчер получают контакты друг друга.
#    Диспетчер может изменить, снять, отметить выполненным; админ — изменить
#    и снять любой. /order показывает, ушёл ли заказ в канал Telegram,
#    в канал MAX и сколько карточек получили водители на каждой площадке
