import asyncio, contextvars, json, re, html, logging, os, secrets, sys, time, hashlib, hmac
import urllib.parse, urllib.request
from types import SimpleNamespace
# Bothost может собрать бота своим шаблоном, без requirements.txt: в нём нет
# asyncpg и geopy, и бот падал на старте. Чего нет — ставим сами при запуске.
try:
    import asyncpg, geopy                                   # noqa: F401
except ImportError:
    import subprocess
    subprocess.check_call([sys.executable, "-m", "pip", "install", "--no-cache-dir", "asyncpg", "geopy"])
import aiohttp
import urllib3
import asyncpg
from datetime import datetime, timedelta, timezone

