BOT_TOKEN       = os.getenv("BOT_TOKEN")
YANDEX_GEO_KEY  = os.getenv("YANDEX_GEOCODER_KEY")
GROUP_CHAT_ID   = int(os.getenv("GROUP_CHAT_ID") or "0")
ADMIN_IDS       = [int(x) for x in os.getenv("ADMIN_IDS", "").split(",") if x]
MAX_TOKEN       = os.getenv("MAX_TOKEN", "")
# Секрет вебхука MAX. Адрес вебхука публичный, и без проверки любой
# мог прислать поддельное сообщение от имени любого пользователя MAX —
# например, взять заказ от имени водителя и получить телефон пассажира.
# MAX присылает секрет в заголовке X-Max-Bot-Api-Secret. Не задан — выводим
# из токена: постоянный между перезапусками и не требует настройки.
MAX_WEBHOOK_SECRET = (os.getenv("MAX_WEBHOOK_SECRET")
                      or hashlib.sha256(("mtrans:" + MAX_TOKEN).encode()).hexdigest()[:48])
MAX_WEBHOOK_URL = os.getenv("MAX_WEBHOOK_URL", "")
MAX_BOT_NICK    = os.getenv("MAX_BOT_NICK", "se14309564_bot")
# Канал заказов в MAX (max.ru/channel_intercitytrans) — номер чата: по ссылке
# MAX его не отдаёт, он пришёл в событии из канала. Бот должен быть
# в канале администратором. 0 — в MAX не публикуем.
MAX_CHANNEL     = int(os.getenv("MAX_CHANNEL") or "-78837642621145")

# Яндекс Метрика: заявка с сайта засчитывается целью для Директа, только
# когда админ её опубликовал или отдал водителю по ссылке, — за фейки,
# которые админ удалил, реклама не платит. Токен — OAuth с доступом
# к Метрике. Без токена сайт засчитывает заявку сам, как раньше.
METRIKA_TOKEN   = os.getenv("METRIKA_TOKEN", "")
METRIKA_COUNTER = 112801816
METRIKA_GOAL    = "order_sent"      # та же цель, за которую платит Директ
METRIKA_API     = "https://api-metrika.yandex.net/management/v1/counter"

# Контакт админа показываем полным адресом, а не «@ником» и не ссылкой под ним:
# MAX сам перехватывает любой @ник, считает его своим упоминанием
# и выдаёт «Информация недоступна». Голый адрес кликабелен в обоих.
ADMIN_CONTACT = os.getenv("ADMIN_CONTACT_URL", "http://telegram.me/olegan7979")

# Не все админы равны. Есть команды, которыми можно одним движением
# лишить бизнес дохода или унести базу с телефонами клиентов —
# такие оставляем только владельцу.
# Без OWNER_ID владельцем считается первый из ADMIN_IDS.
OWNER_ID = int(os.getenv("OWNER_ID", "0")) or (ADMIN_IDS[0] if ADMIN_IDS else 0)


class IsOwner(BaseFilter):
    """Только владелец — для опасных команд."""
    async def __call__(self, event) -> bool:
        user = getattr(event, "from_user", None)
        return bool(user and OWNER_ID and user.id == OWNER_ID)


class IsAdmin(BaseFilter):
    """Пропускает событие только от пользователей из ADMIN_IDS (Message или CallbackQuery)."""
    async def __call__(self, event) -> bool:
        user = getattr(event, "from_user", None)
        return bool(user and user.id in ADMIN_IDS)

