# ══════════════ BOOTSTRAP ДЛЯ MAX ══════════════
# На хостинге образ может не пересобираться при обновлении файлов,
# поэтому две вещи готовим сами при старте:
#   1) CA-бандл с корневым сертификатом Минцифры — без него TLS
#      platform-api2.max.ru не проходит проверку на обычном образе;
#   2) SSL-контексты aiohttp, которые создаются при импорте и не видят наш бандл.
# Оба шага необязательные: если что-то не вышло, бот работает без MAX.
_RU_CERT_URLS = (
    "https://gu-st.ru/content/Other/doc/russian_trusted_root_ca.cer",
    "https://gu-st.ru/content/Other/doc/russian_trusted_sub_ca.cer",
)
_CA_BUNDLE = os.path.join(DATA_DIR, "ca-bundle-v2.pem")


def _der_to_pem(raw: bytes) -> str:
    """PEM отдаёт как есть, DER конвертирует в PEM."""
    import base64
    if raw.lstrip().startswith(b"-----BEGIN"):
        return raw.decode("ascii", "ignore")
    b64 = base64.b64encode(raw).decode("ascii")
    lines = "\n".join(b64[i:i + 64] for i in range(0, len(b64), 64))
    return f"-----BEGIN CERTIFICATE-----\n{lines}\n-----END CERTIFICATE-----\n"


def _pem_is_valid(pem: str) -> bool:
    """Проверяет, что OpenSSL действительно разбирает это как сертификат.
    Без этой проверки HTML-страница ошибки превратилась бы в «сертификат»
    и сломала весь бандл."""
    import ssl as _ssl
    try:
        ctx = _ssl.SSLContext(_ssl.PROTOCOL_TLS_CLIENT)
        ctx.load_verify_locations(cadata=pem)
        return True
    except Exception:
        return False


def _ensure_ru_cert() -> bool:
    """Собирает CA-бандл: стандартные сертификаты + корневой
    и промежуточный Минцифры."""
    if os.path.exists(_CA_BUNDLE) and os.path.getsize(_CA_BUNDLE) > 50_000:
        os.environ["SSL_CERT_FILE"] = _CA_BUNDLE
        os.environ["REQUESTS_CA_BUNDLE"] = _CA_BUNDLE
        log.info("  🔒 CA-бандл уже готов")
        return True

    base = ""
    try:
        import certifi
        base = open(certifi.where(), "r", encoding="utf-8").read()
    except Exception:
        for path in ("/etc/ssl/certs/ca-certificates.crt", "/etc/pki/tls/certs/ca-bundle.crt"):
            if os.path.exists(path):
                base = open(path, "r", encoding="utf-8").read()
                break
    if not base:
        log.error("  ❌ Не нашёл базовый набор сертификатов")
        return False

    import urllib.request
    added = []
    for url in _RU_CERT_URLS:
        name = url.rsplit("/", 1)[-1]
        try:
            # Если файл положен рядом с ботом — берём его и не скачиваем.
            # Это снимает «курицу и яйцо» на чистом сервере, не ослабляя
            # безопасность. Отключать проверку TLS при скачивании нельзя:
            # мы скачиваем корневые сертификаты, и перехвативший трафик подсунул бы
            # свой — и бот стал бы доверять чему угодно.
            local = os.path.join(os.path.dirname(os.path.abspath(__file__)), name)
            if os.path.exists(local):
                raw = open(local, "rb").read()
                log.info(f"  🔒 {name}: взят из локального файла")
            else:
                req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
                with urllib.request.urlopen(req, timeout=30) as r:
                    raw = r.read()
            pem = _der_to_pem(raw)
            if not _pem_is_valid(pem):
                log.error(f"  ❌ {name}: скачалось {len(raw)} байт, но это не сертификат")
                continue
            added.append(pem)
            log.info(f"  ✅ {name}: принят ({len(raw)} байт)")
        except Exception as e:
            log.error(f"  ❌ {name}: {e}")

    if not added:
        log.error("  ❌ Ни один сертификат Минцифры не получен")
        return False

    try:
        with open(_CA_BUNDLE, "w", encoding="utf-8") as f:
            f.write(base)
            if not base.endswith("\n"):
                f.write("\n")
            for pem in added:
                f.write(pem if pem.endswith("\n") else pem + "\n")
        os.environ["SSL_CERT_FILE"] = _CA_BUNDLE
        os.environ["REQUESTS_CA_BUNDLE"] = _CA_BUNDLE
        log.info(f"  🔒 Бандл собран: {_CA_BUNDLE} (+{len(added)} серт.)")
        return True
    except Exception as e:
        log.error(f"  ❌ Бандл не записан: {e}")
        return False


def _fix_aiohttp_ssl() -> bool:
    """aiohttp создаёт SSL-контекст при импорте и кэширует его, поэтому
    переменная SSL_CERT_FILE на него уже не влияет. Доливаем сертификаты
    в живые контексты, чистим кэш фабрики и подставляем свой контекст
    в новые коннекторы. Бандл содержит и обычные сертификаты, так что
    Telegram и остальные соединения от этого не страдают."""
    if not os.path.exists(_CA_BUNDLE):
        return False
    import ssl as _ssl
    try:
        import aiohttp
        import aiohttp.connector as _conn
        import aiohttp.client as _cli
    except Exception as e:
        log.error(f"  ❌ aiohttp не импортировался: {e}")
        return False

    done = []

    # 1. Доливаем сертификаты в уже созданные контексты
    for mod in (_conn, _cli, aiohttp):
        for name in dir(mod):
            try:
                obj = getattr(mod, name)
            except Exception:
                continue
            if isinstance(obj, _ssl.SSLContext):
                try:
                    obj.load_verify_locations(cafile=_CA_BUNDLE)
                    done.append(f"{mod.__name__}.{name}")
                except Exception:
                    pass

    # 2. Сбрасываем кэш фабрики контекстов
    for mod in (_conn, _cli):
        f = getattr(mod, "_make_ssl_context", None)
        if f is not None and hasattr(f, "cache_clear"):
            try:
                f.cache_clear()
                done.append(f"{mod.__name__}._make_ssl_context")
            except Exception:
                pass

    # 3. Новые коннекторы получают наш контекст по умолчанию
    if not getattr(aiohttp.TCPConnector, "_ru_ca_patched", False):
        try:
            ctx = _ssl.create_default_context(cafile=_CA_BUNDLE)
            _orig_init = aiohttp.TCPConnector.__init__

            def _patched_init(self, *a, **kw):
                if "ssl" not in kw and "ssl_context" not in kw:
                    kw["ssl"] = ctx
                return _orig_init(self, *a, **kw)

            aiohttp.TCPConnector.__init__ = _patched_init
            aiohttp.TCPConnector._ru_ca_patched = True
            done.append("TCPConnector")
        except Exception as e:
            log.warning(f"  TCPConnector не пропатчен: {e}")

    log.info(f"  🔧 aiohttp SSL подправлен: {', '.join(done) if done else 'нечего править'}")
    return True


def _tls_probe(host: str = "platform-api2.max.ru") -> bool:
    """Живая проверка TLS до MAX — чтобы сразу видеть в логе, работает ли бандл."""
    import socket, ssl as _ssl
    try:
        ctx = _ssl.create_default_context()
        with socket.create_connection((host, 443), timeout=20) as s:
            with ctx.wrap_socket(s, server_hostname=host) as ss:
                log.info(f"  🔒 TLS до {host}: OK ({ss.version()})")
        return True
    except Exception as e:
        log.error(f"  ❌ TLS до {host}: {e}")
        return False


if MAX_TOKEN:
    _ensure_ru_cert()
    _fix_aiohttp_ssl()
    _tls_probe()

