#  ГЕОГРАФИЯ ТАРИФНЫХ ЗОН — ЕДИНЫЙ ИСТОЧНИК ПРАВДЫ
# ══════════════════════════════════════════════════════════════════════
# Чтобы добавить город или страну — правь ТОЛЬКО этот список. Всё остальное
# (определение региона, выбор тарифа, разбиение маршрута по границе)
# считается из него автоматически.
#
# Поля зоны:
#   region    — "nt" (новые территории) или "cis" (Кавказ/СНГ/зарубежье)
#   cities    — названия в нижнем регистре; совпадение по целому слову
#   gateway   — ближайший российский город-ориентир на пути к границе,
#               либо None, если сухопутной границы нет (тогда весь маршрут
#               считается по одному тарифу, без разбиения)
#   buffer_km — сколько километров от ориентира до реальной границы:
#               они остаются российской частью маршрута
#   crossings — пункты пропуска (координаты): маршрут идёт через тот, где
#               быстрее, без крюка через ориентир; Россия считается до пункта.
#               Ориентир с буфером — запасной путь, если OSRM не ответил
#
# ⚠️ НЕЛЬЗЯ добавлять названия, которые есть и в России (Белогорск в Амурской
# обл., Советский в ХМАО, Кировск в Мурманской, Первомайск в Нижегородской).
# Для таких городов в автокомплите сайта указывается регион: «Кировск, ЛНР» —
# слово «лнр» в строке само включает нужный тариф.

