# Короткие заказы шли потоком из-за слова «трансфер», которое люди
# понимают как подачу в аэропорт. Отказывать не стали: короткая
# поездка тоже годится, если оплачена по минимуму. Цена просто
# поднимается до порога, а человеку это объясняется.
# По умолчанию порога нет: после его ввода заказы прекратились.
# Механизм оставлен — включается переменной MIN_ORDER_PRICE.
MIN_ORDER_PRICE = int(os.getenv("MIN_ORDER_PRICE", "0"))


def apply_min_price(price):
    """Возвращает (итоговая цена, поднята ли). Цена может быть None,
    если геокодер не справился — такую не трогаем."""
    if price is None or not MIN_ORDER_PRICE:
        return price, False
    if price < MIN_ORDER_PRICE:
        return MIN_ORDER_PRICE, True
    return price, False


