    async def passenger_save(uid: int, phone: str, name: str, username: str):
        async with _pg_pool.acquire() as c:
            await c.execute(
                "INSERT INTO passengers(user_id,phone,name,username,updated_at) "
                "VALUES($1,$2,$3,$4,$5) ON CONFLICT(user_id) DO UPDATE SET "
                "phone=EXCLUDED.phone, name=EXCLUDED.name, "
                "username=EXCLUDED.username, updated_at=EXCLUDED.updated_at",
                uid, phone, name, username, now_iso())

    @staticmethod
    async def passenger_touch(uid: int, name: str, username: str):
        """Обновляет имя и ник и сразу возвращает известный телефон —
        одним запросом: база в России, каждый лишний заход заметен."""
        async with _pg_pool.acquire() as c:
            return await c.fetchval(
                "WITH up AS ("
                " INSERT INTO passengers(user_id,name,username,updated_at) VALUES($1,$2,$3,$4)"
                " ON CONFLICT(user_id) DO UPDATE SET name=EXCLUDED.name,"
                " username=EXCLUDED.username, updated_at=EXCLUDED.updated_at"
                " RETURNING phone) "
                "SELECT COALESCE(NULLIF((SELECT phone FROM up), ''),"
                " NULLIF(NULLIF((SELECT phone FROM drivers WHERE user_id=$1), ''), '—'))",
                uid, name, username, now_iso())

    @staticmethod
    async def passenger_info(uid: int):
        """Анкета пассажира и, если он ещё и водитель, анкета водителя — одним запросом."""
        async with _pg_pool.acquire() as c:
            row = await c.fetchrow(
                "SELECT p.name AS p_name, p.username AS p_username, p.phone AS p_phone, "
                "d.first_name, d.last_name, d.username AS d_username, d.phone AS d_phone, "
                "d.profile_link "
                "FROM (SELECT $1::bigint AS uid) x "
                "LEFT JOIN passengers p ON p.user_id = x.uid "
                "LEFT JOIN drivers d ON d.user_id = x.uid", uid)
        return dict(row) if row else {}

    @staticmethod
    async def passenger_names(ids):
        async with _pg_pool.acquire() as c:
            rows = await c.fetch(
                "SELECT user_id, name FROM passengers WHERE user_id = ANY($1::bigint[])",
                list({int(i) for i in ids if i}))
        return {r["user_id"]: r["name"] for r in rows if r["name"]}

