def kb_car_class(region="rf", passengers=1):
    t = TARIFFS_NT if region == "nt" else (TARIFFS_CIS if region == "cis" else TARIFFS_RF)
    classes = ["minivan"] if passengers >= 5 else list(t.keys())
    rows = []
    for cc in classes:
        if cc in t:
            # Это выбор класса для заказа ВСЕЙ машины — цена всегда price
            # (за машину), а не price_seat (за место в рейсе), независимо от
            # региона. Раньше для region='cis' по ошибке показывалась price_seat,
            # хотя реальный расчёт всё равно шёл по price — цена на кнопке не
            # совпадала с тем, что пассажир платил по факту.
            txt = f"{t[cc]['label']} · {t[cc]['price']} ₽/км"
            if cc == "minivan" and passengers >= 5:
                txt += " ✅"
            rows.append([InlineKeyboardButton(text=txt, callback_data=f"car_{cc}")])
    rows.append([InlineKeyboardButton(text="❌ Отменить", callback_data="cancel_order")])
    return InlineKeyboardMarkup(inline_keyboard=rows)

