def fmt_trip(t, drv=None, avg=None, cnt=None):
    region_label = REGION_LABELS.get(t.get("region","rf"), "🇷🇺 Россия")
    seats_total = t.get("seats_total", 0)
    seats_free  = t.get("seats_free", 0)
    seats_taken = seats_total - seats_free
    dist = t.get("distance_km")
    dist_str = f"{int(dist)} км" if dist else "—"
    status_map = {"open":"🟢 Открыт","full":"🔵 Набран","cancelled":"❌ Отменён","done":"✅ Завершён"}
    lines = [
        f"🚐 <b>Рейс #{t['id']}</b> · {region_label}",
        f"📍 {esc(t.get('from_city'))} → {esc(t.get('to_city'))}",
        f"📅 {esc(fmt_date_ru(t.get('trip_date')))} · 🕐 {esc(t.get('trip_time'))}",
        f"📏 {dist_str}",
        f"🚘 {esc(t.get('car_class_label'))}",
        f"💺 Мест: {seats_taken}/{seats_total}",
        f"💰 <b>{fmt_price(t.get('price_per_seat',0))}/место</b>",
        f"📌 {status_map.get(t.get('status','open'), t.get('status',''))}",
    ]
    if drv:
        # cnt=None — рейтинг не запрашивали; писать «Новый водитель»
        # водителю с оценками было бы неправдой.
        if cnt:
            r_str = f" · ⭐ {avg}/5 ({cnt} оц.)"
        elif cnt is None:
            r_str = ""
        else:
            r_str = " · ⭐ Новый водитель"
        lines.append(f"👤 {drv_name(drv)}{r_str}")
    return "\n".join(lines)

def kb_trip_car_class(region: str, drv_cc: str = None):
    t = TARIFFS_CIS if region == "cis" else (TARIFFS_NT if region == "nt" else TARIFFS_RF)
    rows = []
    for cc, info in t.items():
        if drv_cc:
            if cc == "minivan" and drv_cc != "minivan":
                continue
            if cc != "minivan" and drv_cc != "minivan" and CAR_CLASS_TIER.get(cc, 0) > CAR_CLASS_TIER.get(drv_cc, 0):
                continue
        rows.append([InlineKeyboardButton(
            text=f"{info['label']} · {info['price_seat']} ₽/км/место",
            callback_data=f"trip_class_{cc}"
        )])
    rows.append([InlineKeyboardButton(text="❌ Отменить", callback_data="trip_cancel")])
    return InlineKeyboardMarkup(inline_keyboard=rows)

def kb_trip_seats():
    btns = [InlineKeyboardButton(text=str(i), callback_data=f"trip_seats_{i}") for i in range(1, 9)]
    rows = [btns[i:i+2] for i in range(0, len(btns), 2)]
    rows.append([InlineKeyboardButton(text="❌ Отменить", callback_data="trip_cancel")])
    return InlineKeyboardMarkup(inline_keyboard=rows)

def yandex_maps_url(from_city: str, to_city: str) -> str:
    import urllib.parse
    f = urllib.parse.quote(from_city)
    t = urllib.parse.quote(to_city)
    return f"https://yandex.ru/maps/?rtext={f}~{t}&rtt=auto"


# ══════════════ BOT / DISPATCHER ══════════════
bot = Bot(token=BOT_TOKEN, default=DefaultBotProperties(parse_mode=ParseMode.HTML))
storage = MemoryStorage()
dp  = Dispatcher(storage=storage)
router = Router()
dp.include_router(router)

# ══════════════ MAX ══════════════
# Работаем напрямую с MAX Bot API через aiohttp: сторонняя библиотека
# не нужна — апдейты приходят JSON-ом в наш же роут, а отправка
# укладывается в один POST. Меньше зависимостей — меньше сюрпризов.
MAX_ENABLED = bool(MAX_TOKEN)

# В Telegram для личной переписки user_id и chat_id совпадают, и весь код
# опирается на это. В MAX они разные. Чтобы не перекраивать всю базу,
# храним водителей MAX под смещённым id: так они гарантированно не
# столкнутся с телеграмными, а площадка определяется одним сравнением.
# 10^13 выше любого реального Telegram-id и ниже предела BIGINT.
MAX_ID_OFFSET = 10_000_000_000_000
# Третья площадка — ВК. Писать туда мы не умеем, поэтому сообщения
# для таких получателей уходят в общую очередь, откуда их забирает ВК-бот.
VK_ID_OFFSET  = 20_000_000_000_000


def max_uid(raw_user_id) -> int:
    """id пользователя MAX → внутренний id бота."""
    return MAX_ID_OFFSET + int(raw_user_id)


def is_vk_uid(uid) -> bool:
    try:
        return int(uid) >= VK_ID_OFFSET
    except (TypeError, ValueError):
        return False


def uid_platform(uid) -> str:
    """Какой площадке принадлежит id — одним сравнением, без базы."""
    try:
        n = int(uid)
    except (TypeError, ValueError):
        return "tg"
    if n >= VK_ID_OFFSET:
        return "vk"
    if n >= MAX_ID_OFFSET:
        return "max"
    return "tg"


def is_max_uid(uid) -> bool:
    # Верхняя граница обязательна: id ВК лежат выше, и без неё
    # пассажир из ВК помечался в карточках как «MAX».
    try:
        return MAX_ID_OFFSET <= int(uid) < VK_ID_OFFSET
    except (TypeError, ValueError):
        return False


def max_raw_uid(uid) -> int:
    """Внутренний id → настоящий id в MAX."""
    return int(uid) - MAX_ID_OFFSET


# chat_id в MAX приходит в каждом апдейте и не выводится из user_id,
# поэтому складываем его в базу и держим в памяти.
_MAX_CHATS: dict[int, int] = {}

# В Telegram message_id — число, в MAX — строка вида "mid.0000…".
# Код бота везде ждёт число, поэтому держим двусторонний реестр.
# Текст храним тоже: редактирование в MAX заменяет сообщение целиком,
# а вызовы вроде safe_edit_markup передают только клавиатуру.
_MAX_MSG: dict = {}          # число → {"mid", "chat_id", "text"}
_MAX_MID2INT: dict = {}      # mid → число
_MAX_UPD_SEQ = 0

# В Telegram нижнее меню висит всегда, поэтому хендлер вроде «Пропустить»
# может ничего не отправлять — человек всё равно не застрянет. В MAX это
# тупик. Отмечаем факт отправки и досылаем навигацию, если её не было.
# Храним не просто «была ли отправка», а кому именно: хендлер может
# написать пассажиру или админу, а нажавший останется без навигации.
_MAX_SENT = contextvars.ContextVar("max_sent", default=None)


def max_mid_register(mid: str, chat_id: int, text: str = "") -> int:
    i = _MAX_MID2INT.get(mid)
    if i is None:
        # Номер выводим из самого mid. Раньше это был счётчик с нуля: после
        # перезапуска старая карточка из базы указывала на новое, чужое
        # сообщение, и бот переписывал его (с телефоном пассажира).
        i = int(hashlib.sha256(mid.encode()).hexdigest()[:15], 16)
        _MAX_MID2INT[mid] = i
    _MAX_MSG[i] = {"mid": mid, "chat_id": chat_id, "text": text}
    if len(_MAX_MSG) > 20000:
        for k in list(_MAX_MSG)[:10000]:
            _MAX_MID2INT.pop(_MAX_MSG[k]["mid"], None)
            _MAX_MSG.pop(k, None)
    return i


# Одна сессия и один SSL-контекст на весь бот. Сборка контекста разбирает
# весь CA-бандл (сотни сертификатов), а новая сессия — это ещё и новое
# TLS-рукопожатие. На каждом запросе это давало секунду задержки на пустом месте.
_MAX_SESSION = None
_MAX_SSL_CTX = None
_MAX_SESSION_LOCK = asyncio.Lock()


async def _max_session() -> "aiohttp.ClientSession":
    global _MAX_SESSION, _MAX_SSL_CTX
    if _MAX_SESSION is not None and not _MAX_SESSION.closed:
        return _MAX_SESSION
    # Замок нужен потому, что ответ на кнопку и отправка сообщения
    # идут параллельно: без него создастся две сессии, и одна повиснет.
    async with _MAX_SESSION_LOCK:
        if _MAX_SESSION is not None and not _MAX_SESSION.closed:
            return _MAX_SESSION
        if _MAX_SSL_CTX is None and os.path.exists(_CA_BUNDLE):
            import ssl as _ssl
            _MAX_SSL_CTX = _ssl.create_default_context(cafile=_CA_BUNDLE)
        conn = aiohttp.TCPConnector(ssl=_MAX_SSL_CTX, limit=20,
                                    keepalive_timeout=120) if _MAX_SSL_CTX else None
        _MAX_SESSION = aiohttp.ClientSession(
            connector=conn,
            timeout=aiohttp.ClientTimeout(total=25),
            headers={"Content-Type": "application/json"},
        )
        return _MAX_SESSION


async def _max_close_session():
    global _MAX_SESSION
    if _MAX_SESSION is not None and not _MAX_SESSION.closed:
        await _MAX_SESSION.close()
    _MAX_SESSION = None


async def _max_request(method: str, path: str, payload=None):
    """Запрос к MAX Bot API. Токен передаётся заголовком: параметр
    access_token в адресе платформа больше не принимает.
    Проверено на живом API: ждёт голый токен, без префикса Bearer.
    Bearer оставлен запасным вариантом на случай смены правил."""
    url = f"https://platform-api2.max.ru{path}"
    last = None
    for scheme in (MAX_TOKEN, f"Bearer {MAX_TOKEN}"):
        try:
            s = await _max_session()
            async with s.request(method, url, json=payload,
                                 headers={"Authorization": scheme}) as r:
                body = await r.text()
                last = (r.status, body)
                if r.status != 401:
                    return last
                log.warning(f"MAX {path}: 401 с форматом "
                            f"{'Bearer' if scheme.startswith('Bearer') else 'голый токен'}, пробую другой")
        except Exception as e:
            # Сессию не закрываем: aiohttp сам переоткроет соединение,
            # а закрытие оборвало бы соседние запросы в тот же момент.
            log.error(f"MAX {path}: {e}")
            return None
    return last


async def _max_register_webhook():
    """Регистрирует webhook-подписку в MAX Bot API."""
    if not (MAX_TOKEN and MAX_WEBHOOK_URL):
        return
    payload = {
        "url": MAX_WEBHOOK_URL,
        "update_types": ["bot_started", "message_created", "message_callback"],
        "secret": MAX_WEBHOOK_SECRET,
    }
    res = await _max_request("POST", "/subscriptions", payload)
    if res is None:
        return
    status, body = res
    if status == 200:
        log.info(f"  ✅ MAX подписка оформлена на {MAX_WEBHOOK_URL}")
    else:
        log.error(f"  ❌ MAX подписка: HTTP {status} | {body[:500]}")

    # Диагностика: что платформа сейчас считает нашими подписками
    chk = await _max_request("GET", "/subscriptions")
    if chk:
        log.info(f"  ℹ️ MAX подписки сейчас: HTTP {chk[0]} | {chk[1][:500]}")


# MAX понимает HTML, но уже телеграмного: только b, i, del, ins, code, a.
# Подчёркивание и зачёркивание называются иначе, остальное сносим.
_MAX_TAG_MAP = {"u": "ins", "s": "del", "strike": "del", "em": "i", "strong": "b", "pre": "code"}
_MAX_TAGS_OK = {"b", "i", "del", "ins", "code", "a"}


def max_markup(text: str) -> str:
    """Приводит телеграмный HTML к набору тегов, который понимает MAX.
    Ссылки остаются ссылками — длинный адрес не вылезает в текст."""
    if not text:
        return text
    t = re.sub(r"<br\s*/?>", "\n", text, flags=re.I)
    # В коде встречаются и одинарные кавычки в href — приводим к одному виду,
    # иначе ссылка потеряется, а закрывающий тег останется.
    t = re.sub(r"href='([^']*)'", r'href="\1"', t, flags=re.I)
    # Якорь без href бесполезен — оставляем только его текст.
    t = re.sub(r"<a(?![^>]*href=)[^>]*>(.*?)</a>", r"\1", t, flags=re.S | re.I)

    def _tag(m):
        closing, name, rest = m.group(1), m.group(2).lower(), m.group(3)
        name = _MAX_TAG_MAP.get(name, name)
        if name not in _MAX_TAGS_OK:
            return ""
        if closing:
            return f"</{name}>"
        if name == "a":
            href = re.search(r'href="([^"]*)"', rest or "", re.I)
            return f'<a href="{href.group(1)}">' if href else ""
        return f"<{name}>"

    return re.sub(r"<(/?)([a-zA-Z][a-zA-Z0-9-]*)((?:\s[^>]*)?)/?>", _tag, t)


def max_plain(text: str) -> str:
    """Запасной вариант: совсем без разметки, если MAX отказался её принять."""
    if not text:
        return text
    t = re.sub(r'<a\s+href="([^"]+)"[^>]*>(.*?)</a>', r'\2 (\1)', text,
               flags=re.S | re.I)
    t = re.sub(r"<br\s*/?>", "\n", t, flags=re.I)
    t = re.sub(r"<[^>]+>", "", t)
    return html.unescape(t)


MAX_TXT_PREFIX = "txt:"   # метка кнопки-замены нижнего меню


def max_buttons_from_markup(markup):
    """Клавиатура aiogram → кнопки MAX.

    Inline-кнопки переносятся один в один. С нижним меню сложнее:
    в MAX его нет, а весь бот построен на нём (F.text == "🚕 Создать заказ").
    Поэтому каждая reply-кнопка становится inline-кнопкой с payload "txt:<текст>",
    а нажатие на неё превращается обратно в текстовое сообщение.
    Так существующие хендлеры меню работают без единой правки."""
    rows = getattr(markup, "inline_keyboard", None)
    if rows:
        out = []
        for row in rows:
            cur = []
            for b in row:
                if getattr(b, "callback_data", None):
                    cur.append({"type": "callback", "text": b.text, "payload": b.callback_data})
                elif getattr(b, "url", None):
                    cur.append({"type": "link", "text": b.text, "url": b.url})
            if cur:
                out.append(cur)
        return out or None

    rows = getattr(markup, "keyboard", None)
    if rows:
        out = []
        for row in rows:
            cur = []
            for b in row:
                t = getattr(b, "text", None)
                if not t:
                    continue
                if getattr(b, "request_contact", False):
                    cur.append({"type": "request_contact", "text": t})
                else:
                    cur.append({"type": "callback", "text": t,
                                "payload": MAX_TXT_PREFIX + t[:900]})
            if cur:
                out.append(cur)
        return out or None

    return None


async def max_send(chat_id: int, text: str, buttons=None):
    """Отправка сообщения в MAX.
    buttons — список рядов, каждый ряд список пар (текст, callback_data)."""
    if not MAX_ENABLED:
        return None
    payload = {"text": text}
    if "<" in (text or "") or "&" in (text or ""):
        payload["format"] = "html"
    if buttons:
        rows = [
            [b if isinstance(b, dict)
             else {"type": "callback", "text": b[0], "payload": b[1]}
             for b in row]
            for row in buttons
        ]
        payload["attachments"] = [{"type": "inline_keyboard",
                                   "payload": {"buttons": rows}}]
    res = await _max_request("POST", f"/messages?chat_id={chat_id}", payload)
    if res and res[0] == 400 and payload.get("format"):
        # Разметка не понравилась — лучше доставить без неё, чем потерять сообщение.
        log.warning(f"MAX отклонил HTML, повтор без разметки: {res[1][:200]}")
        payload.pop("format", None)
        payload["text"] = max_plain(text)
        res = await _max_request("POST", f"/messages?chat_id={chat_id}", payload)
    if not res:
        return None
    if res[0] != 200:
        log.error(f"MAX отправка {chat_id}: HTTP {res[0]} | {res[1][:300]}")
        return None
    # Возвращаем объект с message_id — код бота ожидает именно его.
    try:
        mid = json.loads(res[1]).get("message", {}).get("body", {}).get("mid")
    except Exception:
        mid = None
    if not mid:
        return None
    # Запоминаем то, что реально ушло: после отказа от HTML правка
    # кнопок отправляла бы отвергнутую разметку снова — и снова неудачно.
    num = max_mid_register(mid, chat_id, text if payload.get("format")
                           else html.escape(payload["text"] or "", quote=False))
    return SimpleNamespace(message_id=num, chat=SimpleNamespace(id=chat_id), mid=mid)


async def max_answer_callback(callback_id: str, text: str = None):
    """Гасит «часик» на кнопке. Всплывающих окон, как в Telegram, в MAX нет,
    поэтому текст уходит уведомлением."""
    payload = {"notification": max_plain(text)} if text else {}
    await _max_request("POST", f"/answers?callback_id={callback_id}", payload)


def _max_menu_button():
    """Кнопка «Меню» вместо снятых кнопок.
    При смене статуса бот убирает с карточки устаревшие кнопки — «Взять
    заказ» и тому подобные. В Telegram при этом остаётся нижнее меню, а в MAX
    кнопки живут только при сообщениях: человек оставался без
    навигации и должен был написать что-нибудь, чтобы вернуть меню."""
    return [[{"type": "callback", "text": "🏠 Меню",
              "payload": MAX_TXT_PREFIX + "🔙 Главное меню"}]]


def _max_fail(res):
    """Причина отказа MAX или None. Код 200 — ещё не успех: по документации
    итог правки лежит в поле success, а при отказе код всё равно 200."""
    if not res:
        return "запрос не ушёл"
    if res[0] != 200:
        return f"HTTP {res[0]} | {res[1][:300]}"
    try:
        body = json.loads(res[1])
    except Exception:
        return None
    if isinstance(body, dict) and body.get("success") is False:
        return body.get("message") or res[1][:300]
    return None


async def _max_put(rec, text, markup, menu=True):
    """Правка сообщения MAX: текст и кнопки целиком (по-другому MAX не умеет).
    Раньше отказ с кодом 200 считался успехом — карточка молча оставалась
    старой (после /recalc цена в MAX не менялась). Разметку не принял —
    повтор без неё, как при отправке."""
    payload = {"text": text or " "}
    if "<" in payload["text"] or "&" in payload["text"]:   # «&quot;» без html показался бы как есть
        payload["format"] = "html"
    # menu=False — пост в канале: там «Меню» не нужно, а пустой список снимает кнопки
    buttons = max_buttons_from_markup(markup) or (_max_menu_button() if menu else None)
    payload["attachments"] = ([{"type": "inline_keyboard", "payload": {"buttons": buttons}}]
                              if buttons else [])
    path = f"/messages?message_id={rec['mid']}"
    fail = _max_fail(await _max_request("PUT", path, payload))
    if fail and payload.get("format"):
        log.warning(f"MAX не принял правку с разметкой ({fail}), повтор без неё")
        payload.pop("format")
        payload["text"] = max_plain(payload["text"])
        fail = _max_fail(await _max_request("PUT", path, payload))
    if fail:
        log.error(f"MAX редактирование: {fail} | mid={rec['mid']}")
        return
    # Как при отправке: в реестре — то, что реально ушло, в виде HTML
    rec["text"] = (payload["text"] if payload.get("format")
                   else html.escape(payload["text"], quote=False))


async def max_edit_message(num_mid: int, text=None, markup=None):
    """Правка уже отправленного сообщения: текст и клавиатура.
    Если текст не передан — берём старый из реестра."""
    rec = _MAX_MSG.get(int(num_mid))
    if not rec:
        log.warning(f"MAX редактирование: нет mid для {num_mid} (сообщение до перезапуска?)")
        return
    await _max_put(rec, max_markup(text) if text is not None else rec.get("text"), markup)


async def max_edit_markup(num_mid: int, markup=None):
    """Замена клавиатуры у уже отправленного сообщения.
    MAX заменяет сообщение целиком, поэтому текст берём из реестра."""
    rec = _MAX_MSG.get(int(num_mid))
    if not rec:
        # Реестр живёт в памяти: после перезапуска старые сообщения уже не правятся.
        log.warning(f"MAX редактирование: нет mid для {num_mid} (сообщение до перезапуска?)")
        return
    await _max_put(rec, rec.get("text"), markup)


# ── Перехват методов aiogram для MAX-пользователей ──
# Хендлеры вызывают call.answer() и msg.reply() напрямую, минуя safe_send.
# Для MAX-id эти вызовы ушли бы в Telegram и упали, поэтому подменяем
# их на уровне класса — это надёжнее, чем подсовывать свои классы
# в pydantic-модели aiogram.
_orig_cb_answer = CallbackQuery.answer
_orig_msg_reply = Message.reply
_orig_msg_answer = Message.answer


async def _cb_answer_max(self, text=None, show_alert=False, **kw):
    if is_max_uid(self.from_user.id):
        if text and show_alert:
            # Окна, как в Telegram, в MAX нет: уведомление мелькало и пропадало,
            # а следом приходило «Готово ✅» — после «❌ Нет абонемента» это
            # сбивало с толку. Важное отправляем сообщением.
            bg(max_answer_callback(self.id), "ответ на кнопку MAX")
            await safe_send(self.from_user.id, html.escape(text))
            return True
        await max_answer_callback(self.id, text)
        return True
    return await _orig_cb_answer(self, text=text, show_alert=show_alert, **kw)


async def _msg_reply_max(self, text, **kw):
    if is_max_uid(self.chat.id):
        return await safe_send(self.chat.id, text, **kw)
    return await _orig_msg_reply(self, text, **kw)


async def _msg_answer_max(self, text, **kw):
    if is_max_uid(self.chat.id):
        return await safe_send(self.chat.id, text, **kw)
    return await _orig_msg_answer(self, text, **kw)


CallbackQuery.answer = _cb_answer_max
Message.reply = _msg_reply_max
Message.answer = _msg_answer_max


# ── Перевод событий MAX в апдейты Telegram ──
def _max_person(u: dict) -> dict:
    raw = (u or {}).get("user_id")
    if raw is None:
        raise ValueError("в событии нет user_id")
    # Отрицательный или огромный id превратился бы в чужой внутренний id —
    # например, в id админа из Telegram.
    if not 0 < int(raw) < MAX_ID_OFFSET:
        raise ValueError(f"недопустимый user_id MAX: {raw}")
    u = u or {}
    person = {"id": max_uid(raw), "is_bot": False,
              "first_name": u.get("first_name") or u.get("name") or "Друг",
              "last_name": u.get("last_name") or "",
              "language_code": "ru"}
    # Публичный ник MAX — единственное, из чего можно собрать ссылку на человека.
    if u.get("username"):
        person["username"] = u["username"]
    return person


def _max_tg_message(person: dict, text, mid_num: int, ts: int, contact=None) -> dict:
    m = {"message_id": mid_num, "date": ts,
         "chat": {"id": person["id"], "type": "private",
                  "first_name": person["first_name"]},
         "from": person}
    if text is not None:
        m["text"] = text
    if contact:
        m["contact"] = contact
    return m


# База не отвечает (сбой у хостинга): соединение отклонено, сервер недоступен, таймаут
DB_DOWN_ERRORS = (OSError, asyncio.TimeoutError, asyncpg.PostgresConnectionError,
                  asyncpg.CannotConnectNowError, asyncpg.InterfaceError)
DB_DOWN_TEXT = "⚠️ Сервис временно недоступен: сбой на сервере. Попробуйте через пару минут."


async def _max_feed(update: dict, chat_id=None, uid=None):
    global _MAX_UPD_SEQ
    _MAX_UPD_SEQ += 1
    update["update_id"] = _MAX_UPD_SEQ
    box = {"uid": uid, "sent": False}
    token = _MAX_SENT.set(box)
    try:
        await dp.feed_raw_update(bot, update)
        if chat_id and box.get("db_down"):
            await max_send(int(chat_id), DB_DOWN_TEXT)
        elif chat_id and uid and not box["sent"]:
            await max_send(int(chat_id), "Готово ✅",
                           buttons=[[{"type": "callback", "text": "🏠 Меню",
                                      "payload": MAX_TXT_PREFIX + "🔙 Главное меню"}]])
    finally:
        _MAX_SENT.reset(token)


def _max_contact(attachments) -> dict:
    """Достаёт телефон из вложения-контакта. Структура у MAX своя,
    поэтому ищем телефон и в полях, и в vCard."""
    for a in attachments or []:
        if a.get("type") != "contact":
            continue
        pl = a.get("payload") or {}
        phone = pl.get("phone") or (pl.get("max_info") or {}).get("phone")
        if not phone:
            vcf = pl.get("vcf_info") or ""
            m = re.search(r"TEL[^:]*:\+?([\d\-\s()]{5,})", vcf)
            if m:
                phone = m.group(1)
        if phone:
            return {"phone_number": str(phone).strip(), "first_name": "",
                    "user_id": None}
    return None


def _max_media(attachments) -> dict:
    """Фото или файл из MAX (нужны для чека об оплате) — в виде полей апдейта
    Telegram. Вместо file_id — ссылка с пометкой «max:», по ней чек потом
    скачивается для админов."""
    for a in attachments or []:
        pl = a.get("payload") or {}
        url = pl.get("url")
        if not url:
            continue
        uniq = str(pl.get("photo_id") or pl.get("token") or url)[:64]
        if a.get("type") == "image":
            return {"photo": [{"file_id": "max:" + url, "file_unique_id": uniq,
                               "width": 0, "height": 0}]}
        if a.get("type") == "file":
            return {"document": {"file_id": "max:" + url, "file_unique_id": uniq,
                                 "file_name": a.get("filename") or "chek"}}
    return {}


def _max_dialog(m: dict) -> bool:
    """Бот работает только в личке. Если его добавят в группу, сообщение
    оттуда переписало бы личный чат человека на группу — и заказы с
    телефонами пассажиров уходили бы всей группе."""
    ct = (m.get("recipient") or {}).get("chat_type")
    if ct in (None, "dialog"):
        return True
    log.info(f"MAX: событие из чата типа {ct} — пропускаю")
    return False


async def max_handle_update(upd: dict):
    """Переводит событие MAX в апдейт Telegram и отдаёт его диспетчеру aiogram.
    Вся бизнес-логика остаётся в существующих хендлерах в единственном экземпляре."""
    utype = upd.get("update_type")
    ts = int(upd.get("timestamp", 0)) // 1000 or int(time.time())
    chat_id = None

    try:
        # ── bot_started: старт и deep-ссылка ──
        if utype == "bot_started":
            person = _max_person(upd.get("user") or {"user_id": upd.get("user_id")})
            chat_id = upd.get("chat_id")
            if chat_id:
                await DB.max_chat_remember(person["id"], int(chat_id))
            payload = upd.get("payload")
            text = f"/start {payload}" if payload else "/start"
            mid_num = max_mid_register(f"synthetic.start.{ts}.{person['id']}",
                                       chat_id or 0, text)
            await _max_feed({"message": _max_tg_message(person, text, mid_num, ts)},
                            chat_id=chat_id, uid=person["id"])
            return

        # ── message_created: обычное сообщение или контакт ──
        if utype == "message_created":
            m = upd.get("message") or {}
            sender = m.get("sender") or {}
            if sender.get("is_bot"):
                return   # свои же сообщения — иначе получится эхо-цикл
            if not _max_dialog(m):
                return
            person = _max_person(sender)
            chat_id = (m.get("recipient") or {}).get("chat_id")
            if chat_id:
                await DB.max_chat_remember(person["id"], int(chat_id))
            body = m.get("body") or {}
            text = body.get("text")
            contact = _max_contact(body.get("attachments"))
            if contact and contact.get("user_id") is None:
                # Хендлер регистрации сверяет contact.user_id с отправителем,
                # чтобы нельзя было прислать чужой контакт.
                contact["user_id"] = person["id"]
                contact["first_name"] = person["first_name"]
            media = _max_media(body.get("attachments"))
            if text is None and not contact and not media:
                log.info("MAX: сообщение без текста, контакта и фото — пропускаю")
                return
            mid = body.get("mid") or f"synthetic.msg.{ts}.{person['id']}"
            mid_num = max_mid_register(mid, chat_id or 0, text or "")
            tg = _max_tg_message(person, None if media else text, mid_num, ts, contact=contact)
            if media:
                # Подпись к фото — как в Telegram, иначе её подхватил бы
                # хендлер текстового шага
                tg.update(media, **({"caption": text} if text else {}))
            await _max_feed({"message": tg}, chat_id=chat_id, uid=person["id"])
            return

        # ── message_callback: нажатие кнопки ──
        if utype == "message_callback" or upd.get("callback"):
            cb = upd.get("callback") or {}
            person = _max_person(cb.get("user") or {})
            m = upd.get("message") or {}
            if not _max_dialog(m):
                return
            chat_id = (m.get("recipient") or {}).get("chat_id")
            if chat_id:
                await DB.max_chat_remember(person["id"], int(chat_id))
            data = cb.get("payload") or ""
            body = m.get("body") or {}
            mid = body.get("mid") or f"synthetic.cb.{ts}.{person['id']}"
            mid_num = _MAX_MID2INT.get(mid)
            if mid_num is None:
                # Текст MAX отдаёт без разметки. Сохраняем экранированным: при
                # правке сообщения он уходит как HTML, и «<a …>» из пожеланий
                # пассажира стал бы живой ссылкой.
                mid_num = max_mid_register(mid, chat_id or 0, html.escape(body.get("text") or "", quote=False))

            # Кнопка-замена нижнего меню — отдаём как текстовое сообщение,
            # иначе хендлеры вида F.text == "🚕 Создать заказ" его не увидят.
            if data.startswith(MAX_TXT_PREFIX):
                # Ответ платформе не ждём: он только гасит «часик» на кнопке
                # и никак не влияет на обработку. Иначе каждое нажатие ждёт лишний круг.
                bg(max_answer_callback(cb.get("callback_id")), "ответ на кнопку MAX")
                text = data[len(MAX_TXT_PREFIX):]
                await _max_feed({"message": _max_tg_message(person, text, mid_num, ts)},
                                chat_id=chat_id, uid=person["id"])
                return

            await _max_feed({"callback_query": {
                "id": cb.get("callback_id") or str(ts),
                "from": person,
                "chat_instance": str(chat_id or person["id"]),
                "data": data,
                "message": _max_tg_message(person, body.get("text") or " ", mid_num, ts),
            }}, chat_id=chat_id, uid=person["id"])
            return

        log.info(f"MAX: необработанный тип апдейта {utype}")
    except DB_DOWN_ERRORS as e:
        log.warning(f"MAX ({utype}): база не отвечает ({e!r}) — ответили «сервис временно недоступен»")
        if chat_id:
            await max_send(int(chat_id), DB_DOWN_TEXT)
    except Exception as e:
        log.error(f"MAX адаптер ({utype}): {e}", exc_info=True)


async def outbox_put(user_id, platform, text):
    """Кладёт сообщение в очередь для чужой площадки."""
    try:
        async with _pg_pool.acquire() as c:
            await c.execute(
                "INSERT INTO outbox(user_id, platform, text) VALUES($1,$2,$3)",
                int(user_id), platform, text)
    except Exception as e:
        log.error(f"Очередь исходящих недоступна ({platform} {user_id}): {e}")


async def _outbox_worker():
    """Забирает из очереди то, что адресовано Telegram и MAX."""
    await asyncio.sleep(15)
    while True:
        try:
            async with _pg_pool.acquire() as c:
                rows = await c.fetch(
                    "SELECT id, user_id, platform, text FROM outbox "
                    "WHERE platform IN ('tg','max') AND delivered=FALSE AND attempts < 5 "
                    "ORDER BY id LIMIT 50")
            for r in rows:
                ok = False
                try:
                    res = await safe_send(r["user_id"], r["text"])
                    ok = res is not None
                except Exception as e:
                    log.error(f"Очередь: не доставлено {r['user_id']}: {e}")
                async with _pg_pool.acquire() as c:
                    if ok:
                        await c.execute("UPDATE outbox SET delivered=TRUE WHERE id=$1", r["id"])
                    else:
                        await c.execute("UPDATE outbox SET attempts=attempts+1 WHERE id=$1", r["id"])
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error(f"_outbox_worker: {e!r}")
        await asyncio.sleep(10)


@dp.errors(ExceptionTypeFilter(*DB_DOWN_ERRORS))
async def on_db_down(event: ErrorEvent):
    """База не отвечает — человеку ответ, а не тишина. Из MAX отвечает _max_feed:
    адрес чата MAX лежит в базе, а у него он уже на руках."""
    log.warning(f"База не отвечает ({event.exception!r}) — ответили «сервис временно недоступен»")
    box = _MAX_SENT.get()
    if box is not None:
        box["db_down"] = True
        return True
    u = event.update
    try:
        if u.callback_query:
            await u.callback_query.answer()
        who = (u.message and u.message.chat.id) or (u.callback_query and u.callback_query.from_user.id)
        if who:
            await bot.send_message(who, DB_DOWN_TEXT)
    except Exception as e:
        log.error(f"Не ответили о сбое базы: {e!r}")
    return True


_DB_DOWN = {"since": None, "told": False}


async def _db_admins(text):
    """Админам в Telegram напрямую: очередь исходящих живёт в той же базе."""
    for aid in ADMIN_IDS:
        if is_max_uid(aid):
            continue
        try:
            await bot.send_message(aid, text)
        except Exception as e:
            log.error(f"Сбой базы — админу {aid} не отправлено: {e!r}")


async def _db_watch():
    """Раз в минуту — SELECT 1. Пул переподключается сам; здесь — только чтобы
    админы узнали о сбое у хостинга: дольше 5 минут — «не отвечает», потом — «снова работает»."""
    await asyncio.sleep(60)
    while True:
        try:
            async with _pg_pool.acquire() as c:
                await c.fetchval("SELECT 1")
            if _DB_DOWN["told"]:
                m = int((now_dt() - _DB_DOWN["since"]).total_seconds() // 60)
                await _db_admins(f"✅ База снова работает. Не отвечала {m // 60} ч {m % 60} мин." if m >= 60
                                 else f"✅ База снова работает. Не отвечала {m} мин.")
                log.info("✅ База снова отвечает")
            _DB_DOWN.update(since=None, told=False)
        except asyncio.CancelledError:
            raise
        except DB_DOWN_ERRORS as e:
            if _DB_DOWN["since"] is None:
                _DB_DOWN["since"] = now_dt()
                log.error(f"База не отвечает: {e!r}")
            elif not _DB_DOWN["told"] and now_dt() - _DB_DOWN["since"] >= timedelta(minutes=5):
                _DB_DOWN["told"] = True
                await _db_admins(f"⚠️ База данных не отвечает с {_DB_DOWN['since']:%H:%M} МСК. Бот работает, "
                                 "но заказы, вход водителей и рассылки стоят. Это сбой у Bothost — "
                                 "напишите им в поддержку. Когда база поднимется, пришлю сообщение.")
        except Exception as e:
            log.error(f"_db_watch: {e!r}")
        await asyncio.sleep(60)


_POST_TRIES: dict = {}   # заказ → сколько раз фоновый обход пробовал пост в канал


async def _announce_worker():
    """Заказы создаются на любой площадке и ложатся в общую таблицу.
    Здесь находим те, о которых ещё не объявляли — и водителям, и в канал."""
    await asyncio.sleep(25)
    # Пост в канал, который не отправился (Telegram ответил ошибкой), тоже
    # повторяем: рассылка водителям к тому моменту уже отмечена, и раньше
    # такой заказ в канал не попадал никогда.
    no_post = "o.channel_msg_id IS NULL OR " if GROUP_CHAT_ID else ""
    seen: set = set()       # не разосланные на прошлом проходе
    await _resume_broadcasts()
    while True:
        try:
            async with _pg_pool.acquire() as c:
                rows = await c.fetch(f"""
                    SELECT o.id, o.channel_msg_id,
                           EXISTS (SELECT 1 FROM order_announced a
                                   WHERE a.order_id = o.id AND a.platform = 'tg') AS announced
                    FROM orders o
                    WHERE o.status = 'open'
                      AND ({no_post}NOT EXISTS (SELECT 1 FROM order_announced a
                                      WHERE a.order_id = o.id AND a.platform = 'tg'))
                    ORDER BY o.id DESC LIMIT 20
                """)
            fresh: set = set()
            for r in rows:
                oid = r["id"]
                # Не больше трёх попыток: если канал недоступен совсем,
                # не долбим Telegram каждую минуту до закрытия заказа.
                if r["channel_msg_id"] is None and _POST_TRIES.get(oid, 0) < 3:
                    _POST_TRIES[oid] = _POST_TRIES.get(oid, 0) + 1
                    await _post_to_channel(oid)
                # Отметку ставит сама рассылка, атомарно. Рассылаем со второго
                # прохода: без отметки заказ бывает и пару секунд, пока идёт
                # повторная рассылка (отказ, /resend). Попав в эти секунды,
                # обход рассылал по старому списку получивших — то есть никому, —
                # а повторная рассылка потом удаляла все карточки и пропускала
                # заказ как «уже разосланный».
                if not r["announced"]:
                    if oid in seen:
                        await _notify_drivers(oid)
                    else:
                        fresh.add(oid)
            seen = fresh
            if MAX_ENABLED and MAX_CHANNEL:
                # Пост в канал MAX, который не ушёл, — тоже не больше трёх попыток
                async with _pg_pool.acquire() as c:
                    miss = await c.fetch("SELECT id FROM orders WHERE status='open' "
                                         "AND max_post_mid IS NULL ORDER BY id DESC LIMIT 20")
                for r in reversed(miss):          # по порядку, как в Telegram
                    k = ("max", r["id"])
                    if _POST_TRIES.get(k, 0) < 3:
                        _POST_TRIES[k] = _POST_TRIES.get(k, 0) + 1
                        await _post_to_max_channel(r["id"])
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error(f"_announce_worker: {e!r}")
        await asyncio.sleep(60)


async def _resume_broadcasts():
    """После перезапуска: рассылки последних 10 минут, которые перезапуск
    оборвал. Отметка «разослан» ставится до рассылки, поэтому фоновый обход
    такой заказ не трогал, и остальные водители его не получали никогда.
    Досылаем тем, у кого карточки этого заказа нет."""
    try:
        async with _pg_pool.acquire() as c:
            rows = await c.fetch(
                "SELECT a.order_id, ARRAY(SELECT k.user_id FROM order_cards k "
                "WHERE k.order_id=a.order_id AND k.kind='notify') AS got "
                "FROM order_announced a JOIN orders o ON o.id=a.order_id "
                "WHERE a.platform='tg' AND o.status='open' "
                "AND a.at > NOW() - INTERVAL '10 minutes'")
    except Exception as e:
        log.error(f"Досылка рассылок после перезапуска: {e}")
        return
    for r in rows:
        oid, newly = r["order_id"], set()
        async with _NLOCK:
            _NOTIFIED.setdefault(oid, set()).update(int(u) for u in r["got"] or [])
        try:
            await _broadcast(oid, None, newly)
        except Exception as e:
            log.error(f"Досылка #{oid}: {e}")
        finally:
            if newly:
                async with _NLOCK:
                    _NOTIFIED[oid].update(newly)
                log.info(f"Заказ #{oid}: рассылку прервал перезапуск — дослано {len(newly)} водителям")


# ══════════════ ХЕЛПЕРЫ ОТПРАВКИ ══════════════
# Фоновые задачи. Ссылку держим в множестве: asyncio хранит лишь слабую
# ссылку, и без этого задача может быть собрана недоделанной.
_BG_TASKS: set = set()


def bg(coro, what: str = ""):
    """Запускает рассылку ДРУГИМ людям фоном, чтобы тот, кто нажал
    кнопку, не ждал, пока бот обновит канал и напишет всем остальным.

    Только для сообщений другим! Ответ самому нажавшему фоном слать
    нельзя: в MAX по окончании обработчика срабатывает страховка «Готово ✅»,
    и человек получил бы лишнее сообщение."""
    t = asyncio.create_task(coro)
    _BG_TASKS.add(t)

    def _done(task):
        _BG_TASKS.discard(task)
        if not task.cancelled() and task.exception():
            log.error(f"Фоновая задача {what}: {task.exception()}")
    t.add_done_callback(_done)
    return t


async def _pace(cid):
    """Пауза между сообщениями списка — только для Telegram, у него лимит
    частоты в один чат. В MAX каждое сообщение и так идёт отдельным
    запросом в Россию, пауза только удлиняла список рейсов на секунду."""
    if not is_max_uid(cid):
        await asyncio.sleep(0.05)


async def safe_send(cid, text, **kw):
    # Единственная точка отправки на весь бот, поэтому развилка по
    # площадке живёт здесь — остальные 245 вызовов менять не надо.
    if is_vk_uid(cid):
        # ВК-бот заберёт сам. Разметку снимаем: ВК её не понимает.
        await outbox_put(cid, "vk", max_plain(text))
        return None

    if is_max_uid(cid):
        chat_id = await DB.max_chat_get(int(cid))
        if not chat_id:
            log.error(f"MAX: нет chat_id для {cid}, сообщение не отправлено")
            return None
        body = max_markup(text)
        if body and len(body) > 4000:
            body = body[:3900] + "\n\n… (текст обрезан)"
        box = _MAX_SENT.get()
        if box is not None and box.get("uid") == int(cid):
            box["sent"] = True
        buttons = max_buttons_from_markup(kw.get("reply_markup"))
        if buttons is None:
            # В Telegram нижнее меню висит постоянно, в MAX кнопки живут только
            # при своём сообщении. Без этого после любого завершённого
            # действия человек остаётся без навигации вообще.
            buttons = [[{"type": "callback", "text": "🏠 Меню",
                         "payload": MAX_TXT_PREFIX + "🔙 Главное меню"}]]
        return await max_send(chat_id, body, buttons=buttons)

    # Telegram отклоняет сообщения длиннее 4096 символов. Лучше отправить
    # обрезанное, чем потерять его целиком (так, например, карточка заявки
    # с очень длинным комментарием всё равно дойдёт до админа).
    if text and len(text) > 4096:
        text = text[:4000] + "\n\n… <i>(текст обрезан)</i>"
    for attempt in range(3):
        try:
            return await bot.send_message(cid, text, **kw)
        except TelegramRetryAfter as e:
            log.warning(f"Flood control {cid}: ждём {e.retry_after} сек.")
            await asyncio.sleep(e.retry_after + 0.5)
        except Exception as e:
            log.error(f"Ошибка отправки {cid}: {e}")
            return None
    return None

async def safe_edit_markup(cid, mid, **kw):
    if is_max_uid(cid):
        await max_edit_markup(mid, kw.get("reply_markup"))
        return
    try:
        await bot.edit_message_reply_markup(chat_id=cid, message_id=mid, **kw)
    except Exception as e:
        log.error(f"Ошибка редактирования разметки: {e}")

# У водителя без юзернейма написать в Telegram напрямую нельзя.
# Поэтому бот работает посредником: после /msg его ответы в течение
# суток пересылаются админам. Ключ — id человека, значение — до когда ждём.
_RELAY: dict = {}
RELAY_HOURS = 24


def relay_open(uid):
    _RELAY[int(uid)] = now_dt() + timedelta(hours=RELAY_HOURS)


def relay_active(uid) -> bool:
    exp = _RELAY.get(int(uid))
    if not exp:
        return False
    if now_dt() > exp:
        _RELAY.pop(int(uid), None)
        return False
    return True


async def send_driver_card(to_uid, d, sub=None, rating=None):
    """Карточка водителя с кнопками действий.
    Раньше собиралась внутри списка водителей, из-за чего попасть в неё
    можно было только листанием страниц.
    sub и rating можно передать готовыми: список грузит их на всю
    страницу параллельно, иначе на каждого водителя шло бы два
    последовательных запроса в базу, а она в другой стране."""
    exp_str, dl, active = sub if sub is not None else await DB.sub_info(d["user_id"])
    avg, cnt = rating if rating is not None else await DB.avg_rating(d["user_id"])
    sub_txt = f"✅ до {fmt_date_ru(exp_str)} ({dl} дн.)" if active else "❌ нет подписки"
    rat_txt = f"⭐ {avg}/5 ({cnt} оц.)" if cnt else "⭐ нет оценок"
    info = (
        f"👤 <b>{drv_name(d)}</b> | ID: <code>{d['user_id']}</code>\n"
        f"🚘 {esc(d.get('car_model'))} ({esc(d.get('car_year'))})\n"
        f"🔢 {esc(d.get('car_number'))}\n"
        f"🏷 {esc(d.get('car_class_label'))}\n"
        f"📞 {esc(_fmt_phone(d.get('phone')))}\n"
        f"📄 {'✅ Верифицирован' if d.get('docs_verified') else '⏳ Ожидает'}\n"
        f"💳 {sub_txt}\n{rat_txt}\n"
        f"🗓 Рег.: {str(d.get('registered_at','—'))[:10]}"
    )
    # У водителя из MAX ник — это ник в MAX, а не в Telegram:
    # ссылка t.me/<ник> открывала чужой профиль.
    pl = profile_link(d)
    url = pl if pl.startswith("https://") else None
    rows = []
    # Пишем через бота — работает всегда, даже если у водителя нет
    # юзернейма в Telegram или он не прислал ссылку MAX.
    rows.append([InlineKeyboardButton(text="💬 Написать через бота",
                                      callback_data=f"admsg_{d['user_id']}")])
    if url:
        rows.append([InlineKeyboardButton(text="🔗 Открыть профиль", url=url)])
    rows.append([
        InlineKeyboardButton(text="✅ Верифицировать", callback_data=f"doc_ok_{d['user_id']}"),
        InlineKeyboardButton(text="❌ Снять вериф.",   callback_data=f"doc_rej_{d['user_id']}"),
    ])
    rows.append([InlineKeyboardButton(text="✏️ Редактировать", callback_data=f"adm_edit_{d['user_id']}")])
    rows.append([InlineKeyboardButton(text="🗑 Удалить",        callback_data=f"adm_del_{d['user_id']}")])
    await safe_send(to_uid, info, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))


async def admin_log(msg, action: str):
    """Пишет в журнал, кто из админов что сделал, и сообщает владельцу.
    Без этого разобраться постфактум, кто что натворил, невозможно."""
    try:
        u = getattr(msg, "from_user", None)
        who = f"{u.full_name} ({u.id})" if u else "?"
        log.info(f"🛠 АДМИН {who}: {action}")
        if OWNER_ID and u and u.id != OWNER_ID:
            await safe_send(OWNER_ID,
                            f"🛠 <b>Действие админа</b>\n{esc(who)}\n{esc(action)}")
    except Exception as e:
        log.error(f"Журнал админа: {e}")


async def remember_order_card(oid, uid, msg, kind=None):
    """Запоминает карточку, чтобы потом обновить её при смене статуса."""
    mid = getattr(msg, "message_id", None)
    if not mid:
        return
    # Для MAX сохраняем и настоящий идентификатор: номер из памяти
    # пропадает при перезапуске, а строка живёт вечно.
    max_mid = None
    if is_max_uid(uid):
        rec = _MAX_MSG.get(int(mid))
        max_mid = rec.get("mid") if rec else None
    try:
        async with _pg_pool.acquire() as c:
            await c.execute(
                "INSERT INTO order_cards(order_id, user_id, message_id, max_mid, kind) "
                "VALUES($1,$2,$3,$4,$5) ON CONFLICT DO NOTHING",
                int(oid), int(uid), int(mid), max_mid, kind)
    except Exception as e:
        log.error(f"Не запомнил карточку #{oid} для {uid}: {e}")


async def refresh_all_order_cards(oid, keep_take=False):
    """Обновляет карточки у всех, кому заказ рассылался: статус
    становится актуальным, кнопки исчезают. Водителю не приходится
    тыкать в мёртвую кнопку, чтобы узнать, что заказ уже занят."""
    try:
        async with _pg_pool.acquire() as c:
            rows = await c.fetch(
                "SELECT user_id, message_id, max_mid FROM order_cards WHERE order_id=$1 "
                "ORDER BY user_id", int(oid))
    except Exception as e:
        log.error(f"Карточки #{oid} не прочитаны: {e}")
        return
    prev = None
    for r in rows:
        # Несколько карточек в одном чате правим не чаще раза в секунду —
        # иначе Telegram отвечает «слишком много запросов».
        if r["user_id"] == prev:
            await asyncio.sleep(1)
        prev = r["user_id"]
        try:
            # Если бот перезапускался, реестр MAX пуст — восстанавливаем
            # запись из базы, иначе карточку нечем править.
            if r["max_mid"] and int(r["message_id"]) not in _MAX_MSG:
                chat_id = await DB.max_chat_get(int(r["user_id"]))
                _MAX_MSG[int(r["message_id"])] = {"mid": r["max_mid"],
                                                 "chat_id": chat_id, "text": ""}
            await refresh_order_card(r["user_id"], r["message_id"], oid, keep_take)
        except Exception as e:
            log.info(f"Карточка #{oid} у {r['user_id']}: {e}")
        # Правка десятков сообщений подряд упирается в ограничения Telegram.
        await asyncio.sleep(0.05)

    # Записи чистим только когда заказ закрыт окончательно.
    # Иначе при следующей смене статуса (принят → завершён)
    # обновлять было бы нечего, и у водителей навсегда осталось бы «Принят».
    od = await DB.order(oid)
    if rows and od and od.get("status") in ("completed", "cancelled"):
        try:
            async with _pg_pool.acquire() as c:
                await c.execute("DELETE FROM order_cards WHERE order_id=$1", int(oid))
        except Exception:
            pass


def kb_take(oid):
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="✅ Взять",       callback_data=f"take_{oid}")],
        [InlineKeyboardButton(text="➡️ Пропустить", callback_data=f"skip_{oid}")],
    ])


async def refresh_order_card(cid, mid, oid, keep_take=False):
    """Перерисовывает карточку заказа по текущему состоянию и убирает кнопки.
    Нужно, когда водитель жмёт «Взять» на старом сообщении: вместо
    всплывающего окна он видит актуальный статус — как в канале.
    keep_take — заказ открыт, а сменилась только цена (/recalc): кто может
    его взять, тот «Взять» не теряет."""
    od = await DB.order(oid)
    if not od:
        await safe_edit_markup(cid, mid, reply_markup=None)
        return
    is_admin = int(cid) in ADMIN_IDS
    if is_admin:
        # Админу — полная карточка: контакты, телефон с сайта, кнопки модерации.
        text, kb = await admin_order_view(od, cid)
    else:
        text, kb = fmt_order(od, redact_phone=True), None
    if keep_take and od["status"] == "open" and int(cid) not in _BL_CACHE:
        drv = await DB.driver(int(cid))
        if drv and can_take_order(drv, od)[0]:
            if is_admin:    # админ, который ещё и водитель: «Взять» к его кнопкам
                kb = InlineKeyboardMarkup(inline_keyboard=(kb.inline_keyboard if kb else [])
                                          + kb_take(oid).inline_keyboard[:1])
            else:
                text, kb = f"🔔 <b>Подходит вам!</b>\n\n{text}", kb_take(oid)
    if is_max_uid(cid):
        await max_edit_message(mid, text=text, markup=kb)
        return
    try:
        await bot.edit_message_text(chat_id=cid, message_id=mid, text=text,
                                    reply_markup=kb)
    except Exception as e:
        if "not modified" in str(e):
            return
        # Текст мог не измениться — тогда хотя бы меняем кнопки.
        log.info(f"Карточка #{oid} не перерисована: {e}")
        await safe_edit_markup(cid, mid, reply_markup=kb)


async def delete_card(cid, mid, max_mid=None) -> bool:
    """Удаляет сообщение бота у человека. False — не удалилось: Telegram
    не даёт удалять сообщения старше 48 часов."""
    if is_max_uid(cid):
        mm = max_mid or (_MAX_MSG.get(int(mid)) or {}).get("mid")
        fail = _max_fail(await _max_request("DELETE", f"/messages?message_id={mm}")) if mm else "нет mid"
        if fail:
            log.info(f"MAX: карточка у {cid} не удалена: {fail}")
        return not fail
    try:
        await bot.delete_message(cid, mid)
        return True
    except Exception as e:
        log.info(f"Карточка у {cid} не удалена: {e}")
        return False


async def reannounce(oid, exclude_uid=None, new_post=False):
    """Заказ снова в поиске (водитель отказался, /resend, водителя убрали):
    подходящим водителям — новая «Подходит вам!» с уведомлением, а прежние
    удаляются. Раньше прежние оставались без кнопки, и у водителя висело
    по две карточки одного заказа. Что удалить нельзя (в Telegram — старше
    48 часов), остаётся как раньше: без кнопки, под обновлением статуса."""
    # Из базы — до обновления статуса, чтобы оно эти карточки уже не правило
    try:
        async with _pg_pool.acquire() as c:
            old = await c.fetch(
                "DELETE FROM order_cards WHERE order_id=$1 AND kind='notify' "
                "RETURNING user_id, message_id, max_mid", int(oid))
    except Exception as e:
        log.error(f"Прежние карточки #{oid}: {e}")
        old = []
    if new_post:
        await _post_to_channel(oid)     # пост в канал тогда не отправился — публикуем
    else:
        await update_channel_post(oid)
        # В MAX поста может не быть: не ушёл или канал подключили позже
        bg(_post_to_max_channel(oid), f"пост MAX #{oid}")
    await _clear_notified(oid)

    async def _drop():
        for r in old:
            cid, mid = int(r["user_id"]), int(r["message_id"])
            if not await delete_card(cid, mid, r["max_mid"]):
                try:
                    async with _pg_pool.acquire() as c:
                        await c.execute(
                            "INSERT INTO order_cards(order_id, user_id, message_id, max_mid, kind) "
                            "VALUES($1,$2,$3,$4,'notify') ON CONFLICT DO NOTHING",
                            int(oid), cid, mid, r["max_mid"])
                    await refresh_order_card(cid, mid, oid)
                except Exception as e:
                    log.info(f"Карточка #{oid} у {cid}: {e}")
            await asyncio.sleep(0.05)
    bg(_drop(), f"прежние карточки #{oid}")
    await _notify_drivers(oid, exclude_uid=exclude_uid)


async def after_driver_removed(orders, bookings, note):
    """Водителя заблокировали или удалили: пассажирам — что его больше нет,
    заказы — снова в поиск, а отданные по ссылке с модерации — админу."""
    for oid, pid, st in orders:
        try:
            if pid and pid > 0:
                await safe_send(pid, f"⚠️ <b>{note}</b>\nЗаказ #{oid} снова открыт, ищем другого.")
            elif did := (await DB.order(oid) or {}).get("dispatcher_id"):
                await dsp_bids_clear(oid)
                await safe_send(did, f"⚠️ <b>{note}</b>\nЗаказ #{oid} снова в поиске — ждите откликов.")
            if st == "open":
                await reannounce(oid)
            else:
                await _clear_notified(oid)
                await update_channel_post(oid)
        except Exception as e:
            log.error(f"Повторная рассылка #{oid}: {e}")
    for tid, pid in bookings:
        await safe_send(pid, f"⚠️ <b>{note}</b>\nРейс #{tid} отменён, бронь аннулирована.")


def freed_note(orders) -> str:
    mod = [f"#{o[0]}" for o in orders if o[2] != "open"]
    return ((f", освобождено заказов: {len(orders)}" if orders else "")
            + (f" ({', '.join(mod)} — снова на модерации)" if mod else ""))


async def notify_driver_change(tgt, label, value):
    await safe_send(tgt, f"ℹ️ <b>Администратор изменил {label}:</b> {html.escape(str(value))}")

# ══════════════ MIDDLEWARE ЧЁРНОГО СПИСКА ══════════════
from aiogram import BaseMiddleware
from aiogram.exceptions import TelegramRetryAfter
class BlacklistMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        uid = event.from_user.id if hasattr(event, "from_user") else None
        if uid and uid in _BL_CACHE:
            if isinstance(event, CallbackQuery):
                await event.answer("⛔ Вы заблокированы.", show_alert=True)
            else:
                await safe_send(uid, "⛔ Вы заблокированы.")
            return
        return await handler(event, data)

_blacklist_mw = BlacklistMiddleware()
dp.message.outer_middleware(_blacklist_mw)
dp.callback_query.outer_middleware(_blacklist_mw)

# Кнопка меню прерывает незаконченный шаг. Хендлеры шагов объявлены раньше
# части кнопок, и в MAX, где старые кнопки живут под каждым сообщением,
# «📋 Мои заказы» на шаге «Пожелания» уходило в заказ как пожелание, а у
# админа «🗓 Мои рейсы» записывалось водителю в марку авто.
# «🚕 Создать заказ» здесь нет намеренно: он сам предупреждает о начатом заказе.
MENU_TEXTS = {
    "🔙 Главное меню", "📊 Тарифы", "🚗 Я водитель", "🚐 Поехать вместе",
    "🎫 Мои брони", "📋 Мои заказы", "📦 Доступные заказы", "🚐 Создать рейс",
    "🗓 Мои рейсы", "👤 Мой профиль", "💳 Абонемент", "✅ Подписка активна",
    "❌ Нет подписки", "📈 Мои поездки", "👤 Зарегистрироваться",
    "🏠 Главное меню", "🙋 Я пассажир", "🚕 Я водитель", "📞 Я диспетчер", "📝 Стать диспетчером",
    "📤 Выложить заказ", "📂 Открытые заказы", "📂 Закрытые заказы",
}


class MenuResetMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        st = data.get("state")
        if getattr(event, "text", None) in MENU_TEXTS and st and data.get("raw_state"):
            await st.clear()
            data["raw_state"] = None    # по нему фильтры выбирают хендлер шага
        return await handler(event, data)

dp.message.outer_middleware(MenuResetMiddleware())

# ══════════════ КЭШ УВЕДОМЛЕНИЙ ══════════════
_NOTIFIED: dict = {}
_NLOCK    = asyncio.Lock()
_BL_CACHE: set = set()

async def _notify_drivers(oid, exclude_uid=None):
    # Отметка и проверка — одной операцией. Раньше они были разнесены,
    # и фоновая задача успевала прочитать «не разослано» до того, как ляжет
    # отметка — водители получали заказ дважды. INSERT возвращает
    # строку только тому, кто вставил её первым; остальные выходят.
    try:
        async with _pg_pool.acquire() as c:
            first = await c.fetchval(
                "INSERT INTO order_announced(order_id, platform) VALUES($1,'tg') "
                "ON CONFLICT DO NOTHING RETURNING order_id", oid)
        if first is None:
            log.info(f"Заказ #{oid} уже разослан раньше — повтор пропущен")
            return
    except Exception as e:
        log.error(f"Отметка о рассылке #{oid}: {e}")
    newly_notified: set = set()
    try:
        await _broadcast(oid, exclude_uid, newly_notified)
    except Exception as e:
        # Сбой посреди рассылки (база не ответила): снимаем отметку — фоновый
        # обход через минуту дошлёт остальным. Раньше они заказ не получали никогда.
        log.error(f"Рассылка #{oid} прервалась: {e}")
        try:
            async with _pg_pool.acquire() as c:
                await c.execute("DELETE FROM order_announced WHERE order_id=$1", oid)
        except Exception as e2:
            log.error(f"Отметка о рассылке #{oid}: {e2}")
    finally:
        # Кому уже ушло — повтор не шлёт. Один захват лока на весь батч
        if newly_notified:
            async with _NLOCK:
                _NOTIFIED.setdefault(oid, set()).update(newly_notified)


async def _broadcast(oid, exclude_uid, newly_notified):
    order = await DB.order(oid)
    if not order or order["status"] != "open": return
    async with _NLOCK:
        notified = set(_NOTIFIED.get(oid, set()))
    drivers = [d for d in await DB.active_drivers()
               if not (exclude_uid and d["user_id"] == exclude_uid)
               and d["user_id"] != order["passenger_id"]
               and d["user_id"] != order.get("dispatcher_id")
               and d["user_id"] not in notified]
    sent = 0
    # Всем подходящим, без лимита: был лимит 50, а водителей больше 130 —
    # остальные (по порядку в базе) заказы в личку не получали никогда.
    for drv in drivers:
        ct, _ = can_take_order(drv, order)
        if not ct: continue
        # Рассылка на всех идёт секунды, и заказ могут взять (или отменить)
        # прямо во время неё — тогда остальным больше не шлём «Открыт».
        order = await DB.order(oid)
        if not order or order["status"] != "open":
            break
        try:
            msg = await safe_send(drv["user_id"], f"🔔 <b>Подходит вам!</b>\n\n{fmt_order(order, redact_phone=True)}",
                                  reply_markup=kb_take(oid))
        except Exception as e:
            # Сбой на одном водителе (например, база не отдала чат MAX) обрывал
            # рассылку целиком, а отметка «разослан» уже стоит — остальные
            # водители заказ так и не получали.
            log.error(f"Рассылка #{oid} водителю {drv['user_id']}: {e}")
            continue
        newly_notified.add(drv["user_id"])
        # Запоминаем карточку, чтобы потом обновить её при смене статуса.
        if msg:
            await remember_order_card(oid, drv["user_id"], msg, "notify")
        sent += 1
        if sent % NOTIFY_BATCH == 0:
            await asyncio.sleep(NOTIFY_DELAY)
    # Взяли во время рассылки: карточки, ушедшие уже после того, как бот
    # обновил остальные, так и показывали бы «Открыт» с «Взять».
    if newly_notified:
        od = await DB.order(oid)
        if not od or od["status"] != "open":
            await refresh_all_order_cards(oid)

async def _clear_notified(oid):
    async with _NLOCK:
        _NOTIFIED.pop(oid, None)

async def _trial_expiry_notifier():
    """Проверяет подписки и уведомляет водителей об окончании — раз в час
    (не раз в сутки), и сразу при старте, чтобы не пропустить уведомления
    из-за времени перезапуска бота. Каждый этап (warn3/warn1/today/expired)
    отправляется не более одного раза на конкретную дату истечения."""
    while True:
        try:
            today             = now_dt().date()
            warn3             = (today + timedelta(days=3)).strftime("%Y-%m-%d")
            warn1             = (today + timedelta(days=1)).strftime("%Y-%m-%d")
            expires_today     = today.strftime("%Y-%m-%d")
            expired_yesterday = (today - timedelta(days=1)).strftime("%Y-%m-%d")
            drivers    = await DB.all_drivers()
            for drv in drivers:
                uid = drv["user_id"]
                exp_str, dl, active = await DB.sub_info(uid)
                if not exp_str:
                    continue

                stage = None
                if exp_str == warn3: stage = "warn3"
                elif exp_str == warn1: stage = "warn1"
                elif exp_str == expires_today: stage = "today"
                elif exp_str == expired_yesterday and not active: stage = "expired"
                if not stage:
                    continue
                # Отметка в базе: из памяти она пропадала при каждом перезапуске,
                # и водитель получал одно и то же напоминание снова.
                if not await DB.flag_once(f"sub:{uid}:{exp_str}:{stage}"):
                    continue

                if stage == "warn3":
                    await safe_send(uid,
                        f"⚠️ <b>Подписка заканчивается через 3 дня</b> ({fmt_date_ru(exp_str)})!\n\n"
                        f"Продлите абонемент чтобы продолжать получать заказы.",
                        reply_markup=kb_subs())
                elif stage == "warn1":
                    await safe_send(uid,
                        f"🔔 <b>Подписка заканчивается завтра</b> ({fmt_date_ru(exp_str)})!\n\n"
                        f"Продлите абонемент чтобы не потерять доступ к заказам.",
                        reply_markup=kb_subs())
                elif stage == "today":
                    await safe_send(uid,
                        f"⚠️ <b>Подписка заканчивается сегодня</b> ({fmt_date_ru(exp_str)})!\n\n"
                        f"Продлите абонемент чтобы не потерять доступ к заказам.",
                        reply_markup=kb_subs())
                elif stage == "expired":
                    await safe_send(uid,
                        f"❌ <b>Ваша подписка истекла.</b>\n\n"
                        f"Оформите абонемент чтобы снова получать заказы.",
                        reply_markup=kb_subs())

        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error(f"_trial_expiry_notifier: {e!r}")
        await asyncio.sleep(3600)

async def _expired_orders_cleaner():
    """Заказы, у которых время выезда уже прошло, висели открытыми
    бесконечно и засоряли список. Закрываем через час после времени выезда:
    запас на случай, если водитель берёт заказ в последнюю минуту."""
    GRACE_HOURS = 1
    # Первая проверка — вскоре после старта, а не через полчаса: при частых
    # перезапусках бот до длинной паузы просто не доживал, и просроченные
    # заказы не закрывались никогда. Сон теперь в конце круга.
    await asyncio.sleep(60)
    while True:
        try:
            now = now_dt()
            closed = []
            # На модерации тоже: иначе пассажир двое суток видел бы «На проверке»
            # у поездки, время которой уже прошло.
            expired = await DB.open_orders() + [
                o for o in await DB.stale_orders() if o["status"] in ("moderation", "pending")]
            for od in expired:
                when = order_departure(od)
                if not when or now - when < timedelta(hours=GRACE_HOURS):
                    continue
                oid = od["id"]
                # Только если статус не сменился, пока мы шли по списку:
                # водитель мог взять заказ в эту самую секунду.
                if not await DB.order_status_cas(oid, od["status"], status="cancelled"):
                    continue
                await update_channel_post(oid)
                log.info(f"⏰ Заказ #{oid} отменён автоматически: выезд был "
                         f"{od['trip_date']} {od['trip_time']}, водителя не нашлось")
                pid = od.get("passenger_id")
                if pid and pid > 0:
                    await safe_send(pid,
                        f"⏰ <b>Заказ #{oid} закрыт</b>\n"
                        f"{esc(od.get('from_city'))} → {esc(od.get('to_city'))}, "
                        f"{fmt_date_ru(od.get('trip_date'))} {esc(od.get('trip_time'))}\n\n"
                        f"Время выезда прошло, водителя так и не нашлось.\n"
                        f"Создайте новый заказ, если поездка ещё актуальна.")
                elif od.get("dispatcher_id"):
                    await safe_send(od["dispatcher_id"],
                        f"⏰ <b>Заказ #{oid} закрыт</b> — время выезда прошло.")
                closed.append(oid)

            # Зависшие через два дня после выезда: взятые — завершаем (водители
            # часто не жмут «Завершить»), не прошедшие модерацию — отменяем.
            # Молча: запрос оценки через два дня сбил бы пассажира с толку.
            auto_done, auto_cancel = [], []
            for od in await DB.stale_orders():
                try:
                    day = datetime.strptime(str(od["trip_date"]).strip(), "%Y-%m-%d")
                except (ValueError, TypeError):
                    continue
                if now - day.replace(hour=23, minute=59, tzinfo=TZ) < timedelta(days=2):
                    continue
                oid = od["id"]
                if od["status"] == "taken":
                    if not await DB.order_status_cas(oid, "taken", status="completed",
                                                     completed_at=now_iso()):
                        continue
                    auto_done.append(oid)
                else:
                    if not await DB.order_status_cas(oid, od["status"], status="cancelled"):
                        continue
                    auto_cancel.append(oid)
                bg(update_channel_post(oid), f"канал #{oid}")
                log.info(f"⏰ Заказ #{oid} ({od['status']}) закрыт автоматически: выезд был {od['trip_date']}")
            if auto_done or auto_cancel:
                parts = []
                if auto_done:
                    parts.append("завершены: " + ", ".join(f"#{o}" for o in auto_done[:20]))
                if auto_cancel:
                    parts.append("отменены (не прошли модерацию): " + ", ".join(f"#{o}" for o in auto_cancel[:20]))
                for admin_id in ADMIN_IDS:
                    bg(safe_send(admin_id, "⏰ Закрыто через 2 дня после выезда — " + "; ".join(parts)),
                       "сводка автозакрытия")

            # Рейсы «Поехать вместе» — на следующий день после выезда в 23:00.
            # Раньше они висели «Открыт» в «Мои рейсы» и «Мои брони» бесконечно.
            # Без сообщений: поздний вечер, будить никого не надо.
            for t in await DB.trips_past(now.strftime("%Y-%m-%d")):
                try:
                    day = datetime.strptime(str(t["trip_date"]), "%Y-%m-%d").replace(tzinfo=TZ)
                except (ValueError, TypeError):
                    continue
                if now >= day + timedelta(days=1, hours=23) and await DB.trip_autoclose(t["id"]):
                    log.info(f"⏰ Рейс #{t['id']} закрыт автоматически: выезд был {t['trip_date']}")

            # Одна сводка за проход, а не письмо на каждый заказ: после долгого
            # простоя их может накопиться сразу много.
            if closed:
                lst = ", ".join(f"#{o}" for o in closed[:20])
                tail = f" и ещё {len(closed) - 20}" if len(closed) > 20 else ""
                for admin_id in ADMIN_IDS:
                    await safe_send(admin_id,
                        f"⏰ Закрыто по истечении времени: {lst}{tail}")
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error(f"Отмена просроченных заказов: {e!r}")
        await asyncio.sleep(1800)

async def _notified_cleaner():
    while True:
        try:
            await asyncio.sleep(600)
            async with _NLOCK:
                current_oids = list(_NOTIFIED.keys())
            if not current_oids: continue
            try:
                async with _pg_pool.acquire() as c:
                    rows = await c.fetch(
                        f"SELECT id, status FROM orders WHERE id = ANY($1::bigint[])",
                        current_oids)
                alive = {r["id"] for r in rows if r["status"] == "open"}
                dead  = [oid for oid in current_oids if oid not in alive]
            except Exception as e:
                log.error(f"_notified_cleaner (ошибка БД): {e}")
                await asyncio.sleep(5)
                continue
            if dead:
                async with _NLOCK:
                    for oid in dead:
                        _NOTIFIED.pop(oid, None)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error(f"_notified_cleaner упала: {e}", exc_info=True)
            await asyncio.sleep(5)

# ══════════════ КАНАЛ ══════════════
_POST_STATUS = {"taken": "🚗 <b>Водитель найден</b>",
                "completed": "✅ <b>Выполнен</b>",
                "cancelled": "❌ <b>Отменён</b>"}

def _post_status(o):
    if o.get("dispatcher_id") and o.get("status") == "cancelled":
        return "🔒 <b>Закрыт</b>"
    return _POST_STATUS.get(o.get("status"))

async def _post_to_channel(oid):
    bg(_post_to_max_channel(oid), f"пост MAX #{oid}")
    if not GROUP_CHAT_ID: return
    # Пост занимаем атомарно: публикация админом и фоновый обход открытых
    # заказов могли прийти сюда одновременно — и заказ выходил в канал дважды.
    # 0 — «пост отправляется», настоящий номер сообщения ляжет следом.
    async with _pg_pool.acquire() as c:
        if not await c.fetchval(
                "UPDATE orders SET channel_msg_id=0 WHERE id=$1 AND status='open' "
                "AND channel_msg_id IS NULL RETURNING id", oid):
            return
    msg = None
    try:
        order = await DB.order(oid)
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="✅ Взять заказ",
                                 url=f"https://t.me/{BOT_USERNAME}?start=order_{oid}")
        ]])
        msg = await safe_send(GROUP_CHAT_ID, fmt_order(order, redact_phone=True), reply_markup=kb)
    finally:
        # И при сбое: иначе «пост отправляется» оставался навсегда и не повторялся
        await DB.order_upd(oid, channel_msg_id=msg.message_id if msg else None)
    # Взяли или отменили, пока пост уходил: правка канала тогда ещё не знала
    # номера поста, и в канале заказ так и висел «Открыт» с «Взять»
    od = await DB.order(oid)
    if msg and od and od["status"] != "open":
        await update_channel_post(oid)

async def update_channel_post(oid, keep_take=False):
    # Статус сменился — правим не только пост в канале, но и личные
    # карточки у водителей. Отдельной задачей, чтобы не задерживать ответ.
    bg(refresh_all_order_cards(oid, keep_take), f"карточки #{oid}")
    if MAX_ENABLED and MAX_CHANNEL:
        bg(_max_channel_sync(oid), f"пост MAX #{oid}")
    order = await DB.order(oid)
    if not order or not order.get("channel_msg_id") or not GROUP_CHAT_ID: return
    status = order["status"]
    status_line = _post_status(order)

    if status_line:
        try:
            await bot.edit_message_text(
                text=fmt_order(order, redact_phone=True) + f"\n\n{status_line}",
                chat_id=GROUP_CHAT_ID,
                message_id=order["channel_msg_id"],
                reply_markup=None)
        except Exception as e:
            log.error(f"Ошибка обновления поста: {e}")
    elif status == "open":
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="✅ Взять заказ",
                                 url=f"https://t.me/{BOT_USERNAME}?start=order_{oid}")
        ]])
        try:
            await bot.edit_message_text(
                text=fmt_order(order, redact_phone=True),
                chat_id=GROUP_CHAT_ID,
                message_id=order["channel_msg_id"],
                reply_markup=kb)
        except Exception as e:
            log.error(f"Ошибка обновления поста: {e}")


# ── Канал в MAX ──
_MAX_POST_LOCK = asyncio.Lock()


def _max_take_kb(oid):
    # Ссылка в бот MAX: водитель откроет заказ у себя в личке, как из канала Telegram
    return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
        text="✅ Взять заказ", url=f"https://max.ru/{MAX_BOT_NICK}?start=order_{oid}")]])


async def _post_to_max_channel(oid):
    """Пост заказа в канал MAX. Занимаем, как в Telegram, атомарно:
    '' — «пост отправляется», номер поста ляжет следом."""
    if not (MAX_ENABLED and MAX_CHANNEL): return
    async with _pg_pool.acquire() as c:
        if not await c.fetchval(
                "UPDATE orders SET max_post_mid='' WHERE id=$1 AND status='open' "
                "AND max_post_mid IS NULL RETURNING id", oid):
            return
    mid = None
    try:
        order = await DB.order(oid)
        if order:
            msg = await max_send(MAX_CHANNEL, max_markup(fmt_order(order, redact_phone=True)),
                                 buttons=max_buttons_from_markup(_max_take_kb(oid)))
            mid = msg.mid if msg else None
    finally:
        # И при сбое: иначе «отправляется» осталось бы навсегда и не повторялось
        await DB.order_upd(oid, max_post_mid=mid)
    # Взяли или отменили, пока пост уходил
    od = await DB.order(oid)
    if mid and od and od["status"] != "open":
        await _max_channel_sync(oid)


async def _max_channel_sync(oid):
    """Пост в канале MAX — вслед за статусом заказа. По одной правке за раз
    и с заказом из базы: две быстрые смены статуса не лягут в обратном порядке."""
    async with _MAX_POST_LOCK:
        o = await DB.order(oid)
        line = _post_status(o) if o else None
        if not (o and o.get("max_post_mid") and (line or o["status"] == "open")):
            return
        text = fmt_order(o, redact_phone=True) + (f"\n\n{line}" if line else "")
        await _max_put({"mid": o["max_post_mid"]}, max_markup(text),
                       None if line else _max_take_kb(oid), menu=False)


# ══════════════ WEB API (форма заказа с сайта мтранс.рф) ══════════════
from fastapi import FastAPI, HTTPException, Request
from fastapi.middleware.cors import CORSMiddleware
from starlette.middleware.gzip import GZipMiddleware
from starlette.staticfiles import StaticFiles
from pydantic import BaseModel, Field
import time

api = FastAPI(title="МТранс Order API")

api.add_middleware(
    CORSMiddleware,
    allow_origins=[
        "https://мтранс.рф", "https://xn--80axekhc.xn--p1ai",
        "https://www.мтранс.рф", "https://www.xn--80axekhc.xn--p1ai",
    ],
    allow_methods=["POST", "GET"],
    allow_headers=["*"],
)
# Страницы сайта и ответы API — сжатыми: главная 64 КБ → ~20 КБ
api.add_middleware(GZipMiddleware, minimum_size=1000)

VALID_CAR_CLASSES = {"standard", "comfort", "comfort+", "minivan", "business"}

@api.get("/")
async def root(request: Request):
    if _SITE:                       # главная сайта
        return await _SITE.get_response(".", request.scope)
    return {"service": "МТранс Order API", "status": "ok"}

@api.get("/health")
async def health():
    ok_db = _pg_pool is not None
    return {"status": "ok" if ok_db else "no_db", "db_pool": ok_db}

# Строгая проверка включается, только когда MAX хоть раз прислал верный
# секрет. Иначе, если подписка с секретом по какой-то причине не обновилась,
# бот отбрасывал бы настоящие сообщения и MAX перестал бы работать совсем.
_MAX_SECRET_SEEN = False
_MAX_NOSECRET_WARNED = 0.0


async def _load_max_secret_flag():
    """Если MAX уже присылал секрет — строгая проверка сразу после старта."""
    global _MAX_SECRET_SEEN
    try:
        _MAX_SECRET_SEEN = await DB.flag_exists("max_secret_seen")
    except Exception as e:
        log.error(f"Отметка о секрете MAX: {e}")


@api.post("/max/webhook")
async def max_webhook(request: Request):
    global _MAX_SECRET_SEEN, _MAX_NOSECRET_WARNED
    got = request.headers.get("x-max-bot-api-secret", "")
    good = bool(got) and hmac.compare_digest(got, MAX_WEBHOOK_SECRET)
    if good and not _MAX_SECRET_SEEN:
        _MAX_SECRET_SEEN = True
        log.info("  🔒 MAX присылает секрет — строгая проверка вебхука включена")
        # Запоминаем в базе: иначе после каждого перезапуска бот снова
        # принимал бы запросы без секрета, пока MAX не пришлёт первое сообщение.
        bg(DB.flag_once("max_secret_seen"), "отметка о секрете MAX")
    if not good:
        if _MAX_SECRET_SEEN:
            # MAX уже шлёт секрет — запрос без него пришёл не от MAX
            log.warning("⛔ Вебхук MAX: запрос без верного секрета отклонён")
            raise HTTPException(403, "forbidden")
        now = time.time()
        if now - _MAX_NOSECRET_WARNED > 3600:
            _MAX_NOSECRET_WARNED = now
            log.warning("⚠️ Вебхук MAX: секрет ещё ни разу не приходил, принимаю без проверки")
    """Точка входа для апдейтов MAX.
    Всегда отвечает 200 и сразу: на ошибках и таймаутах MAX начинает
    ретраить, поэтому обработку вешаем отдельной задачей."""
    if not MAX_ENABLED:
        return {"ok": True}
    try:
        upd = await request.json()
        log.info(f"MAX webhook: {str(upd)[:600]}")
        bg(max_handle_update(upd), "событие MAX")
    except Exception as e:
        log.error(f"MAX webhook error: {e}")
    return {"ok": True}

class SiteOrderRequest(BaseModel):
    # Ограничения длины обязательны: без них длинный текст (например, спам в
    # комментарии) делает сообщение админу длиннее лимита Telegram в 4096
    # символов — оно не отправляется, и заявка молча зависает на модерации.
    from_city: str = Field(..., min_length=2, max_length=100)
    to_city: str = Field(..., min_length=2, max_length=100)
    trip_date: str            # "YYYY-MM-DD"
    trip_time: str = Field("", max_length=10)
    passengers: int = Field(1, ge=1, le=8)
    car_class: str = "standard"
    name: str = Field("", max_length=100)
    phone: str = Field(..., min_length=5, max_length=30)
    wishes: str = Field("", max_length=500)   # как в Telegram-боте
    client_id: str = ""      # номер посетителя в Метрике; чужое значение просто не сохраняется
    from_uri: str = Field("", max_length=300)    # подсказка, выбранная из списка, — точное место
    to_uri: str = Field("", max_length=300)


_METRIKA_OK = False      # токен принят и цель на месте — заявки засчитывает бот


def _metrika_call(path, data=None):
    """Запрос к API Метрики: (код ответа, тело). data — CSV для загрузки файлом."""
    req = urllib.request.Request(f"{METRIKA_API}/{METRIKA_COUNTER}/{path}",
                                 headers={"Authorization": f"OAuth {METRIKA_TOKEN}"})
    if data is not None:
        b = "mtrans" + secrets.token_hex(8)
        req.data = (f'--{b}\r\nContent-Disposition: form-data; name="file"; filename="orders.csv"\r\n'
                    f"Content-Type: text/csv\r\n\r\n{data}\r\n--{b}--\r\n").encode()
        req.add_header("Content-Type", f"multipart/form-data; boundary={b}")
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")
    except Exception as e:
        return 0, str(e)


async def _metrika(path, data=None):
    return await asyncio.get_event_loop().run_in_executor(None, _metrika_call, path, data)


async def metrika_check():
    """При старте: Метрика принимает токен и цель на месте. Иначе — как
    раньше: заявку засчитывает сам сайт, сразу после отправки."""
    global _METRIKA_OK
    if not METRIKA_TOKEN:
        return
    for attempt in range(3):
        status, body = await _metrika("goals")
        if status == 200 and f'"{METRIKA_GOAL}"' in body:
            _METRIKA_OK = True
            log.info("  📈 Метрика: заявки с сайта засчитываются после «Опубликовать»")
            return
        if status == 200:
            log.error(f"Метрика: в счётчике нет цели «{METRIKA_GOAL}» — заявки засчитывает сайт, как раньше")
            return
        if status in (401, 403):
            log.error(f"Метрика: токен не подошёл ({status}) — заявки засчитывает сайт, как раньше")
            return
        if attempt < 2:
            await asyncio.sleep(60)
    log.error(f"Метрика не ответила ({status} {body[:200]}) — заявки засчитывает сайт, как раньше")


async def metrika_confirm(o):
    """Админ подтвердил заявку с сайта — цель в Метрику задним числом:
    к тому визиту, с которого заявку отправили (офлайн-конверсия)."""
    cid = o.get("ym_client_id")
    if not (METRIKA_TOKEN and cid) or (o.get("price") or 0) < 10000:
        return      # дешёвые и без цены реклама не оплачивает — как и раньше
    # Одна заявка — одна цель: после отказа водителя заявку с модерации
    # публикуют или отдают по ссылке ещё раз, и Директ заплатил бы дважды
    if not await DB.flag_once(f"metrika:{o['id']}"):
        log.info(f"Метрика: заявка #{o['id']} уже засчитана раньше — повтор пропущен")
        return
    try:
        ts = int(datetime.fromisoformat(o["created_at"]).timestamp())
    except Exception:
        ts = int(time.time())
    status, body = await _metrika("offline_conversions/upload",
                                  f"ClientId,Target,DateTime\n{cid},{METRIKA_GOAL},{ts}\n")
    if status == 200:
        log.info(f"Метрика: заявка #{o['id']} засчитана")
    else:
        log.error(f"Метрика: заявка #{o['id']} не засчитана — {status} {body[:300]}")


# Общий потолок на весь сервис, без привязки к адресу клиента: за прокси
# хостинга адрес у всех одинаковый, и ограничение по нему блокировало бы всех.
# Реальный поток заявок далеко ниже потолка — он срабатывает только при атаке.
# Без него спам выжигает суточный лимит геокодера и заваливает админов
# карточками модерации быстрее, чем Telegram успевает их доставить.
SITE_ORDERS_PER_MIN    = int(os.getenv("SITE_ORDERS_PER_MIN", "20"))
SITE_ESTIMATES_PER_MIN = int(os.getenv("SITE_ESTIMATES_PER_MIN", "120"))
SITE_TRIPS_PER_MIN     = int(os.getenv("SITE_TRIPS_PER_MIN", "60"))
_FLOOD: dict = {"order": [], "estimate": [], "trips": []}
_FLOOD_ALERTED = {"order": 0.0, "estimate": 0.0, "trips": 0.0}
# Время каждого отказа — для /stats. Если там не ноль без атаки, значит
# потолок задевает живых людей и его пора поднимать.
_FLOOD_REJECTED = {"order": [], "estimate": [], "trips": []}


async def _flood_ok(kind: str, limit: int) -> bool:
    now = time.time()
    hits = [t for t in _FLOOD[kind] if now - t < 60]
    if len(hits) >= limit:
        _FLOOD[kind] = hits
        rej = [t for t in _FLOOD_REJECTED[kind] if now - t < 86400]
        rej.append(now)
        _FLOOD_REJECTED[kind] = rej[-100000:]
        # Предупреждаем владельца не чаще раза в 10 минут, иначе само
        # предупреждение станет спамом.
        if now - _FLOOD_ALERTED[kind] > 600:
            _FLOOD_ALERTED[kind] = now
            what = {"order": "заявок", "estimate": "расчётов цены"}.get(kind, "запросов рейсов")
            log.warning(f"Потолок {what} с сайта: {limit}/мин")
            await safe_send(OWNER_ID,
                f"⚠️ <b>Похоже на атаку на сайт.</b>\n"
                f"Больше {limit} {what} за минуту — лишние отклоняются.")
        return False
    hits.append(now)
    _FLOOD[kind] = hits
    return True


@api.post("/api/order")
async def create_site_order(req: SiteOrderRequest):
    if req.car_class not in VALID_CAR_CLASSES:
        raise HTTPException(400, "Некорректный класс авто")
    # Номер приводим к виду +7…: иначе «8.918…» или «т. 8918…» не скрывались
    # маской и уходили в публичный канал.
    if not _looks_like_phone(req.phone):
        raise HTTPException(400, "Проверьте номер телефона")
    if req.passengers >= 5 and req.car_class != "minivan":
        raise HTTPException(400, "Для 5 и более пассажиров — только минивэн")
    # Как в боте: пробелы вместо города проходили проверку длины
    if not req.from_city.strip() or not req.to_city.strip():
        raise HTTPException(400, "Укажите города")
    if req.from_city.strip().lower() == req.to_city.strip().lower():
        raise HTTPException(400, "Откуда и куда совпадают")

    try:
        trip_date_obj = datetime.strptime(req.trip_date, "%Y-%m-%d").date()
    except ValueError:
        raise HTTPException(400, "Некорректная дата (ожидается YYYY-MM-DD)")
    if trip_date_obj < now_dt().date():
        raise HTTPException(400, "Дата поездки не может быть в прошлом")

    if req.trip_time:
        try:
            h, m = map(int, req.trip_time.split(":"))
            if not (0 <= h <= 23 and 0 <= m <= 59):
                raise ValueError
        except ValueError:
            raise HTTPException(400, "Некорректное время (ожидается HH:MM)")
        if trip_date_obj == now_dt().date():
            trip_dt = datetime.combine(trip_date_obj, datetime.min.time()).replace(
                hour=h, minute=m, tzinfo=TZ)
            if trip_dt < now_dt():
                raise HTTPException(400, "Время поездки не может быть в прошлом")
    # Потолок — после проверок: неверные запросы ничего не стоят, а раньше
    # 20 таких в минуту закрывали приём заявок всем
    if not await _flood_ok("order", SITE_ORDERS_PER_MIN):
        raise HTTPException(429, "Сейчас очень много заявок. Попробуйте через минуту или позвоните нам.")

    # Область к сёлам новых территорий и зарубежья — иначе цена по тарифу РФ
    cf, ct = await asyncio.gather(site_place(req.from_city.strip(), req.from_uri.strip()),
                                  site_place(req.to_city.strip(), req.to_uri.strip()))
    dkm, price, region = await get_distance_and_price_async(cf, ct, req.car_class)
    cf, ct = _add_region(cf), _add_region(ct)     # область, с которой посчитана цена
    price, min_applied = apply_min_price(price)

    # Синтетический отрицательный id — заказ пришёл с сайта, не из Telegram
    # ВАЖНО: в Python оператор % всегда даёт результат со знаком делителя,
    # поэтому -int(...) % N был БАГОМ и давал положительное число.
    # Используем криптостойкий рандом и явно делаем отрицательным.
    site_passenger_id = -secrets.randbelow(9_000_000_000) - 1

    contact_note = f"📞 {_fmt_phone(req.phone)}" + (f", {req.name}" if req.name else "")
    full_wishes = (req.wishes + "\n" if req.wishes else "") + f"🌐 Заявка с сайта. {contact_note}"

    cid = req.client_id.strip()
    # Номер посетителя храним, только если цель засчитает бот. Иначе её уже
    # засчитал сайт, а бот после перезапуска выгрузил бы её второй раз
    cid = cid if _METRIKA_OK and re.fullmatch(r"\d{5,30}", cid) else None
    fields = {
        "passenger_id": site_passenger_id,
        "from_city": cf, "to_city": ct,
        "trip_date": req.trip_date, "trip_time": req.trip_time,
        "passengers": req.passengers, "car_class": req.car_class,
        "wishes": full_wishes, "distance_km": dkm, "price": price,
        "status": "moderation", "region": region, "ym_client_id": cid,
    }
    oid, cancel_token = await DB.order_create(fields)

    # Заявки с сайта не публикуются сразу — сначала их видит только админ.
    # Это защита от фейковых заявок: обычный клиент задержки не замечает,
    # а мусор просто не долетает до водителей.
    # Заявка уже записана. Если база тут же не ответила, карточку собираем из
    # того, что знаем: раньше клиент получал ошибку, а админы — ничего
    try:
        order = await DB.order(oid)
    except Exception as e:
        log.error(f"Заявка #{oid} с сайта не перечитана из базы: {e}")
        order = None
    order = order or dict(fields, id=oid, cancel_token=cancel_token, created_at=now_iso())
    note = namesake_note(cf, ct)
    warn_no_dist = "" if dkm else (
        (f"\n\n{note}\n" if note else "") +
        f"\n⚠️ <b>Расстояние не рассчитано</b> — перед публикацией задайте цену:\n"
        f"<code>/recalc {oid} КМ ЦЕНА</code>\n")
    mod_kb = InlineKeyboardMarkup(inline_keyboard=mod_rows(oid))
    # Карточки модерации — фоном: иначе человек на сайте ждал, пока бот
    # отправит их каждому админу, и только потом видел «Заявка принята».
    async def _to_admins():
        for aid in ADMIN_IDS:
            # redact_phone НЕ ставим — админу телефон нужен, чтобы оценить заявку
            m = await safe_send(aid,
                f"🌐 <b>Новая заявка с сайта — на модерации</b>\n\n{fmt_order(order)}{warn_no_dist}",
                reply_markup=mod_kb)
            # Запоминаем и эту карточку: иначе у админа она навсегда
            # остаётся «на модерации», даже когда заказ уже завершён.
            if m:
                await remember_order_card(oid, aid, m)
    bg(_to_admins(), f"модерация #{oid}")

    return {
        "order_id": oid,
        "distance_km": dkm,
        "price": price,
        "status": "moderation",
        "cancel_token": cancel_token,
        "min_applied": min_applied,
        "min_price": MIN_ORDER_PRICE,
        # Цель для Директа засчитает бот, когда админ опубликует заявку, — сайт её не шлёт
        "confirm_goal": bool(cid),
        "telegram_link": f"https://t.me/{BOT_USERNAME}?start=orderlink_{oid}_{order_link_key(order)}",
        # Ссылка для MAX. Ник бота выдаёт платформа и пока не меняется,
        # поэтому держим его в переменной MAX_BOT_NICK — сменится одной правкой.
        "max_link": (f"https://max.ru/{MAX_BOT_NICK}?start=orderlink_{oid}_{order_link_key(order)}"
                     if MAX_ENABLED else None),
        # ⚠️ Замени VK_GROUP на короткое имя вашего VK-сообщества (см. vk.com/[имя]),
        # и убедись, что VK-бот умеет обрабатывать payload orderlink_<id> так же, как здесь.
        "vk_link": f"https://vk.me/VK_GROUP?ref=orderlink_{oid}",
    }

class EstimateRequest(BaseModel):
    from_city: str = Field(..., min_length=2, max_length=100)
    to_city: str = Field(..., min_length=2, max_length=100)
    car_class: str = "standard"
    from_uri: str = Field("", max_length=300)
    to_uri: str = Field("", max_length=300)

@api.get("/api/trips")
async def site_trips(from_city: str = "", to_city: str = "", date: str = ""):
    """Открытые рейсы для сайта. Бронь — в боте, поэтому телефоны и id
    водителей наружу не отдаём."""
    # Каждый запрос — до 61 обращения к базе: без потолка им можно было её занять
    if not await _flood_ok("trips", SITE_TRIPS_PER_MIN):
        raise HTTPException(429, "Сейчас много запросов, попробуйте через минуту")
    f, t = from_city.strip().lower(), to_city.strip().lower()
    # С фильтром смотрим все открытые рейсы, а не 50 ближайших
    trips = await DB.trips_open(limit=500 if (f or t or date) else 50)

    def same(q, city):
        # «Ростов-на-Дону» находит рейс «Ростов» и наоборот, «Кировск, ЛНР» — «Кировск»
        q, c = q.split(",")[0].strip(), (city or "").lower().split(",")[0].strip()
        return bool(c) and (q in c or c in q)
    if f:
        trips = [x for x in trips if same(f, x.get("from_city"))]
    if t:
        trips = [x for x in trips if same(t, x.get("to_city"))]
    if date:
        trips = [x for x in trips if x.get("trip_date") == date]
    out = []
    for x in trips[:30]:
        drv = await DB.driver(x["driver_id"])
        avg, cnt = await DB.avg_rating(x["driver_id"])
        out.append({
            "id": x["id"], "from_city": x["from_city"], "to_city": x["to_city"],
            "trip_date": x["trip_date"], "trip_time": x.get("trip_time"),
            "seats_free": x["seats_free"], "seats_total": x["seats_total"],
            "price_per_seat": x["price_per_seat"],
            "car": (drv or {}).get("car_model") or "",
            "car_class": x.get("car_class_label") or "",
            "driver": ((drv or {}).get("first_name") or (drv or {}).get("name") or "").split(" ")[0],
            "rating": avg if cnt else None,
        })
    return {"trips": out}


@api.post("/api/estimate")
async def estimate_price(req: EstimateRequest):
    """Предварительный расчёт цены — БЕЗ создания заказа. Для показа пассажиру
    ориентировочной стоимости прямо в форме, до отправки заявки."""
    if req.car_class not in VALID_CAR_CLASSES:
        raise HTTPException(400, "Некорректный класс авто")
    if not req.from_city.strip() or not req.to_city.strip():
        raise HTTPException(400, "Укажите города")
    if not await _flood_ok("estimate", SITE_ESTIMATES_PER_MIN):
        raise HTTPException(429, "Сейчас много запросов, попробуйте через минуту")
    cf, ct = await asyncio.gather(site_place(req.from_city.strip(), req.from_uri.strip()),
                                  site_place(req.to_city.strip(), req.to_uri.strip()))
    dkm, price, _region = await get_distance_and_price_async(cf, ct, req.car_class)
    if not dkm:
        return {"distance_km": None, "price": None}
    # Сайт показывает цену ещё до заявки — предупреждаем сразу,
    # чтобы человек не заполнял форму впустую.
    price, raised = apply_min_price(price)
    # Точки, по которым посчитана цена (они уже в кэше): по ним сайт рисует
    # маршрут — карта больше не уходит в другой город, когда цена верная
    pts = await asyncio.gather(_geocode_async(_normalize_city(cf)), _geocode_async(_normalize_city(ct)))
    return {"distance_km": dkm, "price": price,
            "min_applied": raised,
            "min_price": MIN_ORDER_PRICE,
            "points": pts if all(pts) else None}

class CancelRequest(BaseModel):
    token: str

@api.post("/api/order/{oid}/cancel")
async def cancel_site_order(oid: int, req: CancelRequest):
    """Отмена заявки с сайта — по токену, который выдаётся один раз при создании.
    Не требует Telegram-аккаунта у пассажира."""
    # Номер больше, чем вмещает база, давал ошибку 500 вместо понятного отказа
    ok = 0 < oid < 2**31 and await DB.order_cancel_by_token(oid, req.token)
    if not ok:
        raise HTTPException(400, "Не удалось отменить: неверный токен или заказ уже закрыт")
    # Заявка уже отменена — сбой дальше не должен показывать на сайте ошибку
    try:
        order = await DB.order(oid)
        if order and order.get("driver_id"):
            await safe_send(order["driver_id"], f"❌ Заявка #{oid} отменена пассажиром (с сайта)")
        await update_channel_post(oid)
    except Exception as e:
        log.error(f"Отмена #{oid} с сайта: {e}")
    return {"status": "cancelled"}


