@router.message(CommandStart(), StateFilter("*"))
async def cmd_start(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    parts = (msg.text or msg.caption or "").strip().split()    # /start подписью к фото — без текста

    # Со страницы маршрута: сразу оформление заказа с заполненными городами
    if len(parts) > 1 and parts[1].startswith("route_"):
        bits = parts[1].split("_")
        cf = SITE_CITY_SLUGS.get(bits[1]) if len(bits) == 3 else None
        ct = SITE_CITY_SLUGS.get(bits[2]) if len(bits) == 3 else None
        if cf and ct:
            recent = await DB.passenger_orders(uid)
            if any(o["status"] in ACTIVE_ORDER_STATUSES for o in recent):
                await safe_send(uid, "⚠️ У вас уже есть активный заказ. Завершите или отмените его в «📋 Мои заказы».",
                                reply_markup=kb_passenger())
                return
            await state.clear()
            await state.update_data(from_city=cf, to_city=ct)
            await state.set_state(OrderForm.trip_date)
            await safe_send(uid,
                f"🚕 <b>Заказ: {esc(cf)} → {esc(ct)}</b>\n\n"
                f"🗺 <b>Шаг 3/7</b>\n📅 Дата (ДД.ММ.ГГГГ, точки можно не ставить)",
                reply_markup=kb_cancel())
            return

    # Со страницы «Водителям»
    if len(parts) > 1 and parts[1] == "driver":
        await state.clear()
        await driver_enter(msg, state)
        return

    # С сайта, «Заказ в боте»: сразу оформление, без выбора роли
    if len(parts) > 1 and parts[1] == "new":
        await state.clear()
        await order_start(msg, state)
        return

    # С сайта, из списка рейсов: показываем рейс с кнопкой брони
    if len(parts) > 1 and parts[1].startswith("trip_"):
        await state.clear()
        try:
            tid = int(parts[1].split("_")[1])
        except Exception:
            tid = 0
        t = await DB.trip_one(tid) if 0 < tid < 2**31 else None
        if not t or t.get("status") != "open" or t.get("seats_free", 0) <= 0:
            await safe_send(uid, "⚠️ Рейс уже недоступен — места закончились или он отменён.\n"
                                 "Смотрите другие: 🚐 Поехать вместе", reply_markup=kb_passenger())
            return
        drv = await DB.driver(t["driver_id"])
        avg, cnt = await DB.avg_rating(t["driver_id"])
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="📌 Забронировать место", callback_data=f"book_trip_{tid}")],
            [InlineKeyboardButton(text="🗺 Маршрут", url=yandex_maps_url(t["from_city"], t["to_city"]))],
        ])
        await safe_send(uid, fmt_trip(t, drv=drv, avg=avg, cnt=cnt), reply_markup=kb)
        return

    if len(parts) > 1 and parts[1].startswith("orderlink_"):
        try:
            bits  = parts[1].split("_", 2)
            oid   = int(bits[1])
            key   = bits[2] if len(bits) > 2 else ""
            order = await DB.order(oid)
            if not order:
                await safe_send(uid, "⚠️ Заявка не найдена — возможно, устарела ссылка.", reply_markup=kb_passenger())
                return
            # Привязываем только по ссылке с верным ключом: номер заявки
            # легко угадать, а привязавший получает телефон водителя.
            good = order_link_key(order)
            key_ok = bool(good) and key.isascii() and hmac.compare_digest(key, good)
            await state.clear()
            if not key_ok:
                # Без ключа не показываем ничего: номера идут подряд, и перебором
                # можно было читать маршруты и цены всех заявок.
                await safe_send(uid, "⚠️ Ссылка неверна или устарела.", reply_markup=kb_passenger())
                return
            relinked = await DB.order_relink_passenger(oid, uid)
            status_txt = {
                "moderation": "🔎 Обрабатываем заявку, скоро подберём водителя...",
                "pending":   "⏳ Рассчитываем стоимость, скоро сообщим...",
                "open": "🔎 Ищем свободного водителя...",
                "taken": "🚗 Водитель уже назначен, скоро свяжется с вами.",
                "completed": "✅ Поездка завершена.",
                "cancelled": "❌ Заявка отменена.",
            }.get(order["status"], "")
            price_txt = f"\n💰 Цена: {fmt_price(order['price'])}" if order.get("price") else ""
            if relinked:
                header = f"🔗 <b>Заявка №{oid} привязана к этому чату.</b>\n"
                footer = f"\n\nЯ пришлю сюда сообщение, как только водитель возьмёт заказ."
            else:
                header = f"ℹ️ <b>Заявка №{oid}</b> (статус на текущий момент):\n"
                footer = ""
            await safe_send(uid,
                f"{header}"
                f"{esc(order['from_city'])} → {esc(order['to_city'])}{price_txt}\n\n"
                f"{status_txt}{footer}",
                reply_markup=kb_passenger())
            return
        except Exception as e:
            log.error(f"orderlink deep-link: {e}")

    # Личная ссылка от админа (/give): заказ — одному водителю, хоть с модерации
    if len(parts) > 1 and parts[1].startswith("give_"):
        await state.clear()
        oid = give_oid(parts[1])
        order = await DB.order(oid) if oid else None
        if not order or order["status"] not in ("moderation", "open"):
            await safe_send(uid, "⚠️ Заказ уже взят, отменён или ссылка неверна.", reply_markup=kb_main())
            return
        if not await DB.driver(uid):
            await safe_send(uid, "❌ Сначала зарегистрируйтесь как водитель.", reply_markup=kb_main())
            return
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="✅ Взять заказ", callback_data=f"give_{oid}_{give_key(oid)}")]])
        m = await safe_send(uid, f"🔗 <b>Заказ для вас:</b>\n\n{fmt_order(order, redact_phone=True)}",
                            reply_markup=kb)
        if m:
            await remember_order_card(oid, uid, m)
        return

    if len(parts) > 1 and parts[1].startswith("order_"):
        try:
            oid   = int(parts[1].split("_")[1])
            order = await DB.order(oid)
            if not order or order["status"] != "open":
                await safe_send(uid, "⚠️ Заказ не найден или уже взят.", reply_markup=kb_main()); return
            drv = await DB.driver(uid)
            if not drv:
                await safe_send(uid, "❌ Сначала зарегистрируйтесь как водитель.", reply_markup=kb_main()); return
            _, _, active = await DB.sub_info(uid)
            if not active:
                await safe_send(uid, "🔒 Нет абонемента.", reply_markup=await kb_driver(uid)); return
            if not drv.get("docs_verified"):
                await safe_send(uid, "⏳ Профиль ещё не верифицирован.", reply_markup=await kb_driver(uid)); return
            if uid in (order["passenger_id"], order.get("dispatcher_id")):
                await safe_send(uid, "❌ Нельзя взять свой заказ.", reply_markup=await kb_driver(uid)); return
            ct, rsn = can_take_order(drv, order)
            kb = InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="✅ Взять заказ", callback_data=f"take_{oid}")
                if ct else InlineKeyboardButton(text=rsn, callback_data="cant_take")
            ]])
            await state.clear()
            m = await safe_send(uid, f"🔗 <b>Заказ из канала:</b>\n\n{fmt_order(order, redact_phone=True)}", reply_markup=kb)
            if m:
                await remember_order_card(oid, uid, m)
            return
        except Exception as e:
            log.error(f"Deep-link: {e}")
    await state.clear()
    await safe_send(uid,
        f"👋 <b>{html.escape(msg.from_user.first_name or 'друг')}</b>, "
        f"добро пожаловать в Межгород Трансфер!\n\n"
        "🔹 Пассажирам — оформить заказ\n"
        "🔹 Водителям — получать заказы\n"
        "🔹 Диспетчерам — выкладывать свои заказы\n"
        "📢 Канал: @intercitytrans",
        reply_markup=kb_main())

