@router.message(Command("ban"), StateFilter("*"), IsAdmin())
async def cmd_ban(msg: Message, state: FSMContext):
    # Разбор аргумента и сама работа — в разных перехватах.
    # Иначе ошибка после блокировки выглядит как неверный синтаксис,
    # и админ думает, что команда не сработала.
    try:
        t = int(msg.text.split()[1])
    except Exception:
        await msg.reply("⚠️ /ban ID, например: /ban 849235112")
        return
    # Админа и владельца заблокировать нельзя: иначе владелец не смог бы
    # даже выполнить /unban.
    if t in ADMIN_IDS or t == OWNER_ID:
        await msg.reply("⚠️ Админа заблокировать нельзя")
        return
    await admin_log(msg, f"блокировка {t}")
    await DB.bl_add(t)
    _BL_CACHE.add(t)
    await safe_send(t, "⛔ Вы заблокированы.")
    freed, trip_bookings = [], []
    try:
        # Заказы заблокированного возвращаем в поиск — иначе пассажир
        # будет ждать водителя, который уже не может приехать.
        freed, trip_bookings = await DB.driver_release_orders(t)
    except Exception as e:
        log.error(f"Освобождение заказов {t}: {e}")
        await msg.reply(f"⛔ {t} в ЧС, но заказы освободить не удалось: {e}")
        return
    await msg.reply(f"⛔ {t} в ЧС" + freed_note(freed))
    await after_driver_removed(freed, trip_bookings, "Водитель больше не работает в сервисе.")

@router.message(Command("unban"), StateFilter("*"), IsAdmin())
async def cmd_unban(msg: Message, state: FSMContext):
    try:
        t = int(msg.text.split()[1])
    except Exception:
        await msg.reply("⚠️ /unban ID, например: /unban 849235112")
        return
    await admin_log(msg, f"разблокировка {t}")
    try:
        await DB.bl_remove(t)
        _BL_CACHE.discard(t)
    except Exception as e:
        log.error(f"Разблокировка {t}: {e}")
        await msg.reply(f"❌ Не удалось разблокировать: {e}")
        return
    await msg.reply(f"✅ {t} разблокирован")

