@router.message(Command("extend"), StateFilter("*"), IsAdmin())
async def cmd_extend_one(msg: Message, state: FSMContext):
    await admin_log(msg, "продление подписки: " + (msg.text or ""))
    try:
        parts = msg.text.split()
        uid   = int(parts[1])
        days  = int(parts[2])
        if not 0 < days <= 3650:        # «/extend ID 99999999» ронял команду
            raise ValueError
    except:
        await msg.reply("⚠️ /extend ID ДНЕЙ, например: /extend 123456789 100")
        return

    drv = await DB.driver(uid)
    if not drv:
        await msg.reply("❌ Водитель не найден")
        return

    today = now_dt().date()
    exp_str, days_left, active = await DB.sub_info(uid)
    base = today
    if exp_str:
        try:
            cur_exp = datetime.strptime(exp_str, "%Y-%m-%d").date()
            if cur_exp > today:
                base = cur_exp
        except:
            pass
    new_exp = (base + timedelta(days=days)).strftime("%Y-%m-%d")
    await DB.sub_set(uid, new_exp, admin_id=msg.from_user.id, plan_key="manual_extend")

    await msg.reply(f"✅ {drv_name(drv)} ({uid}): подписка продлена до {fmt_date_ru(new_exp)}")
    await safe_send(uid, f"🎁 Ваш абонемент продлён на {days} дн. Действует до {fmt_date_ru(new_exp)}.")

@router.message(Command("order"), StateFilter("*"), IsAdmin())
async def cmd_order_info(msg: Message, state: FSMContext):
    try:
        oid = int(msg.text.split()[1])
        if not 0 < oid < 2**31:         # огромный номер ронял запрос к базе — без ответа
            raise ValueError
    except:
        await msg.reply("⚠️ /order ID_ЗАКАЗА, например: /order 6")
        return

    o = await DB.order(oid)
    if not o:
        await msg.reply("❌ Заказ не найден")
        return

    lines = [fmt_order(o), ""]
    if o.get("driver_id"):
        drv = await DB.driver(o["driver_id"])
        if drv:
            uname = f"@{drv['username'].lstrip('@')}" if drv.get("username") else "—"
            lines.append(
                f"🚗 <b>Водитель:</b> {drv_name(drv)} ({esc(uname)})\n"
                f"📞 {esc(_fmt_phone(drv.get('phone')))}\n"
                f"🚘 {esc(drv.get('car_model'))} {esc(drv.get('car_year'), '')}, № {esc(drv.get('car_number'))}\n"
                f"🆔 id: <code>{o['driver_id']}</code>"
            )
        else:
            lines.append(f"🚗 Водитель id <code>{o['driver_id']}</code> (профиль не найден в базе)")
    else:
        lines.append("🚗 Водитель пока не назначен")
    pid = o.get("passenger_id") or 0
    if pid > 0:
        lines += ["", await passenger_contact_lines(pid, tg_links=not is_max_uid(msg.chat.id), order=o)]
    if o.get("dispatcher_id"):
        d = await dsp_get(o["dispatcher_id"]) or {"user_id": o["dispatcher_id"]}
        lines += ["", f"💼 <b>Диспетчер:</b> {dsp_name(d)} · {_contact_html(d)}\n"
                      f"🆔 id: <code>{o['dispatcher_id']}</code>"]

    # Кнопка ведёт сразу к карточке водителя со всеми действиями,
    # чтобы не искать его листанием списка.
    rows = []
    if o.get("driver_id"):
        rows.append([InlineKeyboardButton(text="👤 Карточка водителя",
                                          callback_data=f"drvcard_{o['driver_id']}")])
    if pid > 0:
        rows.append([InlineKeyboardButton(text="✉️ Написать пассажиру через бота",
                                          callback_data=f"admsg_{pid}")])
    kb = InlineKeyboardMarkup(inline_keyboard=rows) if rows else None
    await msg.reply("\n".join(lines), reply_markup=kb)

@router.message(Command("extend_all", "extend_nosub"), StateFilter("*"), IsOwner())
async def cmd_extend_all(msg: Message, state: FSMContext):
    """/extend_all — всем водителям; /extend_nosub — только тем, у кого
    абонемента нет или он закончился (им дни считаются от сегодня)."""
    cmd = msg.text.split()[0].lstrip("/").split("@")[0]
    nosub = cmd == "extend_nosub"
    try:
        days = int(msg.text.split()[1])
        if not 0 < days <= 3650:
            raise ValueError
    except:
        await msg.reply(f"⚠️ /{cmd} КОЛ-ВО_ДНЕЙ, например: /{cmd} 7")
        return

    who = "водителям без абонемента" if nosub else "всем водителям"
    await admin_log(msg, f"массовое продление подписки на {days} дн. ({who})")
    await msg.reply(f"⏳ Продлеваю подписку на {days} дн. {who}...")
    updated = await DB.sub_extend_all(days, admin_id=msg.from_user.id, only_inactive=nosub)
    await msg.reply(f"✅ Готово: подписка продлена на {days} дн. для {len(updated)} водителей.")

    notify_text = (f"🎁 Вам начислен бесплатный абонемент на {days} дн.!" if nosub
                   else f"🎁 Ваш бесплатный абонемент продлён ещё на {days} дн.!")
    for uid in updated:
        await safe_send(uid, notify_text)

