@router.callback_query(F.data.startswith("admsg_"), IsAdmin())
async def cb_admin_msg(call: CallbackQuery, state: FSMContext):
    """Начало переписки: админ нажал «Написать» и просто набирает текст."""
    target = int(call.data.split("_")[1])
    drv = await DB.driver(target)
    if drv:
        who = drv_name(drv)
    else:
        try:
            pas = await DB.passenger(target)
        except Exception:
            pas = None
        who = esc((pas or {}).get("name") or "пассажира") if pas else str(target)
    await state.set_state(AdminMsgForm.text)
    await state.update_data(msg_target=target)
    await call.answer()
    await safe_send(call.from_user.id,
        f"✏️ <b>Сообщение для {who}</b>\n"
        f"Напишите текст одним сообщением.",
        reply_markup=kb_cancel())

# Важен порядок: этот хендлер объявлен раньше глобальной отмены,
# поэтому без явного исключения нажатие «Отменить» ушло бы
# водителю как текст сообщения. «🚕 Создать заказ» (в MAX — старая кнопка
# под сообщением) тоже уходил человеку текстом.
@router.message(AdminMsgForm.text, IsAdmin(), ~F.text.in_({"❌ Отменить", "🚕 Создать заказ"}),
                ~F.text.startswith("/"))
async def p_admin_msg(msg: Message, state: FSMContext):
    data = await state.get_data()
    target = data.get("msg_target")
    await state.clear()
    if not target:
        await safe_send(msg.chat.id, "❌ Получатель потерян, начните заново.", reply_markup=kb_main())
        return
    text = (msg.text or "").strip()
    if not text:
        await safe_send(msg.chat.id, "❌ Нужен текст.", reply_markup=kb_main())
        return
    await admin_log(msg, f"сообщение пользователю {target}")
    res = await safe_send(target,
        f"✉️ <b>Сообщение от администратора</b>\n\n{esc(text)}\n\n"
        f"<i>Ответьте на это сообщение — администратор его увидит.</i>")
    if res:
        relay_open(target)
    await safe_send(msg.chat.id,
        "✅ Отправлено. Ответы придут сюда." if res else
        "❌ Не доставлено — возможно, человек заблокировал бота.",
        reply_markup=kb_main())

