@router.message(Command("trips"), StateFilter("*"), IsAdmin())
async def cmd_trips(msg: Message, state: FSMContext):
    """Список рейсов с числом броней. Раньше админ вообще не видел,
    кто и куда возит попутчиков."""
    trips = await DB.trips_admin()
    if not trips:
        await msg.reply("🚌 Рейсов пока нет")
        return
    today = now_dt().date().strftime("%Y-%m-%d")
    lines = [f"🚌 <b>Рейсы</b> (последние {len(trips)})", ""]
    for t in trips:
        mark = {"open": "🟢", "full": "🔵", "cancelled": "🔴",
                "done": "✅"}.get(t.get("status"), "•")
        when = "прошёл" if t["trip_date"] < today else "будет"
        lines.append(
            f"{mark} <b>#{t['id']}</b> {esc(t['from_city'])} → {esc(t['to_city'])}\n"
            f"    {fmt_date_ru(t['trip_date'])} {esc(t.get('trip_time','—'))} · {when}\n"
            f"    мест: {t['seats_free']}/{t['seats_total']} · броней: {t['bookings']} · "
            f"{t['price_per_seat']} ₽/место")
    lines.append("\n<i>Подробно: /trip НОМЕР</i>")
    await safe_send(msg.chat.id, "\n".join(lines))

@router.message(Command("trip"), StateFilter("*"), IsAdmin())
async def cmd_trip_info(msg: Message, state: FSMContext):
    """Рейс подробно: водитель и все, кто забронировал места."""
    try:
        tid = int(msg.text.split()[1])
        if not 0 < tid < 2**31:
            raise ValueError
    except Exception:
        await msg.reply("⚠️ /trip НОМЕР, например: /trip 5")
        return
    t = await DB.trip_one(tid)
    if not t:
        await msg.reply("❌ Рейс не найден")
        return
    drv = await DB.driver(t["driver_id"])
    lines = [
        f"🚌 <b>Рейс #{tid}</b> · {esc(t.get('status','—'))}",
        f"📍 {esc(t['from_city'])} → {esc(t['to_city'])}",
        f"📅 {fmt_date_ru(t['trip_date'])} {esc(t.get('trip_time','—'))}",
        f"💺 {t['price_per_seat']} ₽/место · мест: {t['seats_free']}/{t['seats_total']}",
        "",
        f"🚗 <b>Водитель:</b> {drv_name(drv) if drv else '—'}",
    ]
    if drv:
        lines.append(f"📞 {esc(_fmt_phone(drv.get('phone','—')))} · id <code>{t['driver_id']}</code>")
    books = await DB.trip_bookings(tid)
    lines.append("")
    if not books:
        lines.append("🎫 <b>Броней нет</b>")
    else:
        lines.append(f"🎫 <b>Брони</b> ({len(books)}):")
        for b in books:
            # Раньше пассажира искали среди водителей — у обычного
            # пассажира там не было ни имени, ни телефона.
            info = await _passenger_info(b["passenger_id"])
            who = esc(info["name"]) if info["name"] else f"id {b['passenger_id']}"
            n = _norm_phone(info["phone"])
            phone = f" · +{n}" if n else ""
            mark = "✅" if b.get("status") == "confirmed" else "❌"
            lines.append(f"  {mark} {who} — мест: {b['seats']}{phone}\n"
                         f"      id <code>{b['passenger_id']}</code>")
    kb = None
    if t.get("driver_id"):
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="👤 Карточка водителя",
                                 callback_data=f"drvcard_{t['driver_id']}")
        ]])
    await safe_send(msg.chat.id, "\n".join(lines), reply_markup=kb)

@router.message(Command("ratings"), StateFilter("*"), IsAdmin())
async def cmd_ratings(msg: Message, state: FSMContext):
    """Все оценки водителя: кто, за что и когда."""
    try:
        did = int(msg.text.split()[1])
    except Exception:
        await msg.reply("⚠️ /ratings ID_ВОДИТЕЛЯ, например: /ratings 5480177996")
        return
    drv = await DB.driver(did)
    rows = await DB.driver_ratings(did)
    head = f"⭐ <b>Оценки: {drv_name(drv) if drv else did}</b>"
    if not rows:
        await safe_send(msg.chat.id, head + "\n\nОценок нет")
        return
    avg = sum(r["stars"] for r in rows) / len(rows)
    try:
        names = await DB.passenger_names([r["passenger_id"] for r in rows])
    except Exception as e:
        log.error(f"Имена оценивших: {e}")
        names = {}
    lines = [head, f"Средняя {avg:.1f} из {len(rows)}", ""]
    for r in rows:
        oid = r["order_id"]
        # Оценки за рейсы хранятся с отрицательным номером
        what = f"рейс #{-oid}" if oid and oid < 0 else f"заказ #{oid}"
        pid = r["passenger_id"]
        src = "MAX" if is_max_uid(pid) else ("ВК" if is_vk_uid(pid) else "TG")
        who = f"{esc(names[pid])} · " if names.get(pid) else ""
        lines.append(f"{'⭐' * r['stars']}  {what} · {who}{src} <code>{pid}</code> · "
                     f"{str(r.get('created_at') or '')[:10]}\n"
                     f"   удалить: <code>/delrating {r['id']}</code>")
    # Длинное сообщение Telegram обрежет посреди тега и не отправит — шлём частями.
    chunk = ""
    for line in lines:
        if chunk and len(chunk) + len(line) > 3500:
            await safe_send(msg.chat.id, chunk)
            chunk = ""
        chunk += line + "\n"
    if chunk.strip():
        await safe_send(msg.chat.id, chunk)

@router.message(Command("delrating"), StateFilter("*"), IsOwner())
async def cmd_delrating(msg: Message, state: FSMContext):
    """Удаляет оценку по номеру из /ratings. Номер именно оценки, а не
    заказа: за один рейс оценки ставят несколько пассажиров."""
    try:
        rid = int(msg.text.split()[1])
        if not 0 < rid < 2**31:
            raise ValueError
    except Exception:
        await msg.reply("⚠️ /delrating НОМЕР — номер возьмите из /ratings")
        return
    r = await DB.rating_delete(rid)
    if not r:
        await msg.reply("❌ Оценка не найдена")
        return
    await admin_log(msg, f"удалена оценка {r['stars']}★ водителю {r['driver_id']} за #{r['order_id']}")
    avg, cnt = await DB.avg_rating(r["driver_id"])
    await msg.reply(f"✅ Оценка {r['stars']}★ удалена. Теперь у водителя: "
                    + (f"{avg} из {cnt}" if cnt else "оценок нет"))

@router.message(Command("resend"), StateFilter("*"), IsAdmin())
async def cmd_resend(msg: Message, state: FSMContext):
    """Разослать открытый заказ водителям заново.
    Нужно, когда заказ вернулся в поиск, но рассылка не ушла."""
    try:
        oid = int(msg.text.split()[1])
        if not 0 < oid < 2**31:
            raise ValueError
    except Exception:
        await msg.reply("⚠️ /resend НОМЕР_ЗАКАЗА, например: /resend 18")
        return
    od = await DB.order(oid)
    if not od:
        await msg.reply("❌ Заказ не найден")
        return
    if od["status"] != "open":
        await msg.reply(f"ℹ️ Заказ #{oid}: {STATUS_ICON.get(od['status'], od['status'])}. "
                        f"Рассылаются только открытые.")
        return
    await admin_log(msg, f"повторная рассылка заказа #{oid}")
    try:
        async with _pg_pool.acquire() as c:
            await c.execute("DELETE FROM order_announced WHERE order_id=$1", oid)
            # Пост, застрявший на «отправляется» (0), публикуем заново
            await c.execute("UPDATE orders SET channel_msg_id=NULL WHERE id=$1 AND channel_msg_id=0", oid)
            await c.execute("UPDATE orders SET max_post_mid=NULL WHERE id=$1 AND max_post_mid=''", oid)
    except Exception as e:
        log.error(f"Сброс отметки #{oid}: {e}")
    # Кто уже получал — получит снова, а прежняя карточка удалится
    await reannounce(oid, new_post=not od.get("channel_msg_id"))
    await msg.reply(f"📤 Заказ #{oid} разослан заново")

@router.message(Command("recalc"), StateFilter("*"), IsAdmin())
async def cmd_recalc(msg: Message, state: FSMContext):
    await admin_log(msg, "пересчёт заказа: " + (msg.text or ""))
    try:
        _, oid, dkm, price = msg.text.split()
        oid, dkm, price = int(oid), float(dkm), int(price)
        # «/recalc 73 12000 300» (км и цена местами) уходило пассажиру как «300 ₽»
        if not 0 < dkm <= price:
            await safe_send(msg.chat.id, "❌ Проверьте числа: сначала километры, потом цена.\n"
                                         "Формат: /recalc НОМЕР КМ ЦЕНА"); return
        order = await DB.order(oid)
        if not order: await safe_send(msg.chat.id, "❌ Заказ не найден"); return
        if order["status"] in ("completed", "cancelled"):
            await safe_send(msg.chat.id, f"❌ Заказ #{oid} уже закрыт — цену не меняем"); return

        was_pending = order["status"] == "pending"
        had_price = bool(order.get("price"))
        update_fields = {"distance_km": dkm, "price": price}
        if was_pending:
            # Заказ ещё не публиковался — это первый расчёт, открываем его
            update_fields["status"] = "open"
        await DB.order_upd(oid, **update_fields)

        order = await DB.order(oid)
        hint = ("\n💡 Заявка на модерации — нажмите «✅ Опубликовать» в карточке, "
                "чтобы отправить её водителям, или «🔗 Ссылка для водителя» — отдать одному водителю."
                if order["status"] == "moderation" else "")
        await safe_send(msg.chat.id, f"✅ Заказ #{oid} пересчитан (статус: {order['status']}){hint}")
        pid = order.get("passenger_id")
        if pid and pid > 0:
            if order["status"] == "open":
                await safe_send(pid,
                    f"✅ <b>Заказ #{oid} рассчитан!</b>\n\n{fmt_order(order)}")
            else:
                what = "скорректирована администратором" if had_price else "рассчитана"
                await safe_send(pid,
                    f"ℹ️ Стоимость заказа #{oid} {what}.\n\n{fmt_order(order)}")

        if was_pending:
            await _post_to_channel(oid)
            await _notify_drivers(oid)
        elif order["status"] == "open":
            # Заказ уже был открыт — обновляем пост и карточки, не дублируем.
            # В карточках водителей новая цена, «Взять» остаётся: раньше
            # кнопка пропадала, а повторно заказ не рассылался.
            await update_channel_post(oid, keep_take=True)
            await _notify_drivers(oid)
        else:
            # Заказ уже взят/завершён/отменён — статус не трогаем, только синхронизируем текст поста
            await update_channel_post(oid)
            if order["status"] == "taken" and order.get("driver_id"):
                await safe_send(order["driver_id"],
                    f"ℹ️ Стоимость заказа #{oid} изменена администратором: <b>{fmt_price(price)}</b>")
    except Exception as e:
        await safe_send(msg.chat.id, f"❌ {e}\nФормат: /recalc order_id distance_km price")


@router.message(Command("give"), StateFilter("*"), IsAdmin())
async def cmd_give(msg: Message, state: FSMContext):
    """/give N — то же, что кнопка «🔗 Ссылка для водителя» в карточке."""
    await admin_log(msg, "ссылка на заказ: " + (msg.text or ""))
    try:
        oid = int(msg.text.split()[1])
        if not 0 < oid < 2**31:         # иначе база упадёт на «/give 99999999999»
            raise ValueError
    except Exception:
        await safe_send(msg.chat.id, "⚠️ /give N, например: /give 73"); return
    err = await send_give_links(msg.chat.id, oid)
    if err:
        await safe_send(msg.chat.id, err)


@router.message(Command("regive"), StateFilter("*"), IsAdmin())
async def cmd_regive(msg: Message, state: FSMContext):
    """/regive N — передать взятый заказ другому водителю: текущего снимаем,
    заказ никому не рассылается, админу — личная ссылка для нового."""
    await admin_log(msg, "передача заказа: " + (msg.text or ""))
    try:
        oid = int(msg.text.split()[1])
        if not 0 < oid < 2**31:
            raise ValueError
    except Exception:
        await safe_send(msg.chat.id, "⚠️ /regive N, например: /regive 73"); return
    old = await DB.order_unassign(oid)
    if not old:
        await safe_send(msg.chat.id, f"⚠️ Заказ #{oid} сейчас не взят — для открытого или на модерации есть /give {oid}")
        return
    await safe_send(old, f"ℹ️ Заказ #{oid} передан другому водителю. Спасибо!")
    od = await DB.order(oid)
    pid = (od or {}).get("passenger_id")
    if pid and pid > 0:
        await safe_send(pid, f"🔄 По заказу #{oid} будет другой водитель — пришлём его контакты.")
    err = await send_give_links(msg.chat.id, oid)
    await safe_send(msg.chat.id, err or f"✅ Водитель <code>{old}</code> снят с заказа #{oid}. "
                                       f"Перешлите ссылку выше новому водителю.")


@router.callback_query(F.data.startswith("mod_give_"), IsAdmin())
async def cb_mod_give(call: CallbackQuery):
    oid = int(call.data.split("_")[2])
    await admin_log(call, f"ссылка на заказ #{oid} (кнопкой)")
    err = await send_give_links(call.from_user.id, oid)
    await call.answer(err or "🔗 Ссылки отправлены", show_alert=bool(err))


async def send_give_links(chat_id, oid):
    """Личная ссылка на заказ для одного водителя: заказ остаётся на
    модерации и никому не рассылается — берёт тот, кому админ её переслал.
    Возвращает текст ошибки или None."""
    order = await DB.order(oid)
    if not order or order["status"] not in ("moderation", "open"):
        return f"⚠️ Заказ #{oid} не найден, уже взят или закрыт"
    if order.get("dispatcher_id"):
        return f"⚠️ У заказа #{oid} водителя выбирает диспетчер"
    if not order.get("distance_km"):
        return f"⚠️ Сначала задайте расстояние и цену: /recalc {oid} КМ ЦЕНА"
    p = f"give_{oid}_{give_key(oid)}"
    links = f"Telegram: https://t.me/{BOT_USERNAME}?start={p}"
    if MAX_ENABLED:
        # Ник MAX-бота некрасивый — текстом не печатаем, только ссылкой
        links += f"\nMAX: <a href='https://max.ru/{MAX_BOT_NICK}?start={p}'>ссылка для MAX</a>"
    note = ("Заказ остаётся на модерации — остальным водителям он не рассылается."
            if order["status"] == "moderation" else
            "Заказ уже опубликован — его могут взять и другие водители.")
    sent = await safe_send(chat_id,
        f"🔗 <b>Заказ #{oid} — ссылка для одного водителя</b>\n\n{links}\n\n"
        f"Перешлите её водителю. Кто первым откроет и нажмёт «Взять», тому и заказ. {note}")
    return None if sent else "⚠️ Не удалось отправить ссылки — попробуйте ещё раз"


# ══════════════ МЕНЮ (кнопки) ══════════════
# «🏠» — так кнопка называлась в v23.3
@router.message(F.text.in_({"🔙 Главное меню", "🏠 Главное меню"}), StateFilter("*"))
async def to_main(msg: Message, state: FSMContext):
    await state.clear()
    await safe_send(msg.chat.id, "🏠 Главное меню", reply_markup=kb_main())

@router.message(F.text == "🙋 Я пассажир", StateFilter("*"))
async def passenger_enter(msg: Message, state: FSMContext):
    await state.clear()
    await safe_send(msg.chat.id, "🙋 <b>Меню пассажира</b>", reply_markup=kb_passenger())

@router.message(F.text == "📊 Тарифы", StateFilter("*"))
async def show_tariffs(msg: Message, state: FSMContext):
    await state.clear()
    # Ровные столбцы бывают только в моноширинном шрифте. Строки — отдельными
    # <code>, а не блоком <pre>: у блока серая плашка и «Копировать код».
    # Значок класса — до <code>: у всех значков одна ширина, столбцы не сбиваются
    num = lambda v: f"{v:g}".replace(".", ",")
    def table(t):
        return "\n".join(f"{icon} <code>{name:<9}{num(v['price']):>4}</code>"
                         for v in t.values() for icon, name in [v["label"].split(" ", 1)])
    lines = ["💰 <b>Тарифы за всю машину</b>\nЦена в рублях за 1 км\n",
             "🇷🇺 <b>Россия</b>", table(TARIFFS_RF),
             "\n🌍 <b>Кавказ/СНГ</b>", table(TARIFFS_CIS),
             "\n🆕 <b>Новые Территории</b>", table(TARIFFS_NT),
             "\n⚠️ Платные дороги — отдельно"]
    lines.append("\n📞 <b>Заказ по телефону:</b>")
    for phone in DISPATCHER_PHONES:
        lines.append(f"  {phone}")
    await safe_send(msg.chat.id, "\n".join(lines))


# ══════════════ СОЗДАНИЕ ЗАКАЗА (FSM) ══════════════
@router.message(F.text == "🚕 Создать заказ", StateFilter("*"))
async def order_start(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    recent = await DB.passenger_orders(uid)
    if any(o["status"] in ACTIVE_ORDER_STATUSES for o in recent):
        await safe_send(uid, "⚠️ У вас уже есть активный заказ. Завершите или отмените его в «📋 Мои заказы».",
                        reply_markup=kb_passenger()); return
    cur = await state.get_state()
    if cur and str(cur).startswith("OrderForm:"):
        await safe_send(uid, "⚠️ У вас уже есть активное создание заказа. Завершите или нажмите «❌ Отменить»",
                        reply_markup=kb_cancel()); return
    await state.clear()     # другой незаконченный шаг (поиск рейса и т.п.) бросаем
    await state.set_state(OrderForm.from_city)
    await safe_send(uid, "🗺 <b>Шаг 1/7</b>\n📍 Введите город отправления\n<i>Например: Москва</i>",
                    reply_markup=kb_cancel())

@router.message(StateFilter("*"), F.text == "❌ Отменить")
async def cancel_all(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    if uid in _ORDER_BUSY:
        # Заказ уже считается и сохраняется: «Отменено» здесь было бы неправдой
        await safe_send(uid, "⏳ Заказ уже создаётся. Отменить его можно кнопкой "
                             "«❌ Отменить заказ» под ним через пару секунд.")
        return
    cur = await state.get_state()
    if cur is None:
        # Старая кнопка «Отменить» (в MAX кнопки остаются под сообщениями)
        # уже после того, как заказ создан: «Отменено» было неправдой —
        # заказ оставался, и к человеку ехал водитель.
        await safe_send(uid, "ℹ️ Сейчас нечего отменять. Созданный заказ отменяется кнопкой "
                             "«❌ Отменить» в «📋 Мои заказы», рейс — в «🗓 Мои рейсы».",
                        reply_markup=kb_main())
        return
    await state.clear()
    if cur.startswith("TripForm:"):
        kb = await kb_driver(uid)
    elif cur.startswith(("DispOrderForm:", "DispEditForm:")) and await dsp_get(uid):
        kb = kb_dispatcher()
    elif cur.startswith(("OrderForm:", "SearchTripForm:", "BookForm:")):
        kb = kb_passenger()
    else:
        kb = kb_main()
    await safe_send(uid, "❌ Отменено.", reply_markup=kb)

# Шаг 1
@router.message(OrderForm.from_city)
async def step_from(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    city = await ask_city_step(uid, msg.text, "❌ Некорректное название", region=True)
    if not city: return
    await state.update_data(from_city=city)
    await state.set_state(OrderForm.to_city)
    await safe_send(uid, f"✅ Откуда: <b>{esc(city)}</b>\n\n🗺 <b>Шаг 2/7</b>\n🏁 Введите город назначения")

# Шаг 2
@router.message(OrderForm.to_city)
async def step_to(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    city = await ask_city_step(uid, msg.text, "❌ Некорректное название", region=True)
    if not city: return
    data = await state.get_data()
    from_city = data.get("from_city")
    if not from_city:
        await state.clear()
        await safe_send(uid, "⚠️ Данные устарели. Начните заново.", reply_markup=kb_passenger()); return
    if from_city.lower() == city.lower():
        await safe_send(uid, "❌ Города не должны совпадать"); return
    await state.update_data(to_city=city)
    await state.set_state(OrderForm.trip_date)
    await safe_send(uid, f"✅ Куда: <b>{esc(city)}</b>\n\n🗺 <b>Шаг 3/7</b>\n📅 Дата (ДД.ММ.ГГГГ, точки можно не ставить)")

# Шаг 3
@router.message(OrderForm.trip_date)
async def step_date(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    d = parse_ru_date(msg.text)
    if d is None:
        await safe_send(uid, "❌ Формат ДД.ММ.ГГГГ (точки не обязательны, например 30062026)"); return
    if d < now_dt().date():
        await safe_send(uid, "❌ Дата не может быть в прошлом"); return
    await state.update_data(trip_date=d.strftime("%Y-%m-%d"))
    await state.set_state(OrderForm.trip_time)
    await safe_send(uid, f"✅ Дата: <b>{d.strftime('%d.%m.%Y')}</b>\n\n🗺 <b>Шаг 4/7</b>\n🕐 Время (ЧЧ:ММ, например 1430)")

# Шаг 4
@router.message(OrderForm.trip_time)
async def step_time(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    parsed = parse_ru_time(msg.text)
    if parsed is None:
        await safe_send(uid, "❌ Формат ЧЧ:ММ (двоеточие не обязательно, например 1430)"); return
    h, m = parsed
    if not (0 <= h <= 23 and 0 <= m <= 59):
        await safe_send(uid, "❌ Некорректное время"); return
    nice_time = f"{h:02d}:{m:02d}"
    data = await state.get_data()
    if ds := data.get("trip_date"):
        trip_dt = datetime.strptime(f"{ds} {nice_time}", "%Y-%m-%d %H:%M").replace(tzinfo=TZ)
        if trip_dt < now_dt():
            await safe_send(uid, "❌ Поездка не может быть в прошлом"); return
    await state.update_data(trip_time=nice_time)
    await state.set_state(OrderForm.passengers)
    await safe_send(uid, f"✅ Время: <b>{nice_time}</b>\n\n🗺 <b>Шаг 5/7</b>\n👥 Пассажиры:",
                    reply_markup=kb_passengers())

# Шаг 5 (колбэк)
@router.callback_query(StateFilter(OrderForm.passengers), F.data.startswith("pax_"))
async def cb_pax_fsm(call: CallbackQuery, state: FSMContext):
    uid = call.from_user.id
    try:
        passengers = int(call.data.split("_", 1)[1])
    except Exception:
        await call.answer("❌ Ошибка кнопки", show_alert=True); return
    if not (1 <= passengers <= 8):
        await call.answer("❌ Недопустимое количество пассажиров", show_alert=True); return
    await call.answer()
    await state.update_data(passengers=passengers)
    data = await state.get_data()
    region = route_region(_normalize_city(data.get("from_city","")), _normalize_city(data.get("to_city","")))
    await state.update_data(region=region)
    await state.set_state(OrderForm.car_class)
    hint = "\n\n⚠️ <b>Для 5 и более пассажиров доступен только минивэн!</b>" if passengers >= 5 else ""
    region_hint = f"\n🌍 Тариф: {REGION_LABELS.get(region,'')}" if region != "rf" else ""
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    await safe_send(uid, f"✅ Пассажиров: <b>{passengers}</b>")
    await safe_send(uid,
        f"🗺 <b>Шаг 6/7</b>{region_hint}\n👥 Пассажиров: {passengers}{hint}",
        reply_markup=kb_car_class(region, passengers))

# Шаг 6 (колбэк)
@router.callback_query(StateFilter(OrderForm.car_class), F.data.startswith("car_"))
async def cb_car_fsm(call: CallbackQuery, state: FSMContext):
    uid = call.from_user.id
    cc = call.data.split("_", 1)[1]
    data = await state.get_data()
    region = data.get("region", "rf")
    t = TARIFFS_NT if region == "nt" else (TARIFFS_CIS if region == "cis" else TARIFFS_RF)
    if cc not in t:
        await call.answer("❌ Неверный класс", show_alert=True); return
    # Старая кнопка класса (в MAX они остаются под сообщениями) пропускала
    # 5+ пассажиров в легковой — сайт такое не принимает, бот принимал
    if data.get("passengers", 1) >= 5 and cc != "minivan":
        await call.answer("❌ Для 5 и более пассажиров — только минивэн", show_alert=True); return
    await call.answer()
    await state.update_data(car_class=cc, car_class_label=t[cc]["label"])
    await state.set_state(OrderForm.wishes)
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    await safe_send(uid, f"✅ Класс: <b>{t[cc]['label']}</b>")
    kb = ReplyKeyboardMarkup(
        keyboard=[[KeyboardButton(text="Нет"), KeyboardButton(text="❌ Отменить")]],
        resize_keyboard=True,
    )
    await safe_send(uid, "🗺 <b>Шаг 7/7</b>\n💬 Пожелания? Нет — нажмите кнопку", reply_markup=kb)

# Шаг 7
@router.message(OrderForm.wishes)
async def step_wishes(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    if not msg.text:
        await safe_send(uid, "❌ Пожалуйста, отправьте текстом (или «нет»)."); return
    wish = msg.text.strip()
    if len(wish) > 500:
        await safe_send(uid, "❌ Слишком длинный текст (макс. 500 символов)"); return
    wish = "" if wish.lower() in ["нет","—","-","no"] else wish
    try:
        phone = await DB.passenger_touch(
            uid, f"{msg.from_user.first_name or ''} {msg.from_user.last_name or ''}".strip(),
            msg.from_user.username or "")
    except Exception as e:
        log.error(f"Пассажир {uid}: {e}")
        phone = None
    if not phone:
        # Телефон спрашиваем один раз — дальше он берётся из базы.
        await state.update_data(wish=wish)
        await state.set_state(OrderForm.contact)
        await safe_send(uid,
            "📱 <b>Последний шаг — ваш номер телефона</b>\n\n"
            "Он нужен водителю, чтобы связаться с вами. Водитель увидит его "
            "только после того, как возьмёт заказ.\n\n"
            "Нажмите кнопку ниже или напишите номер.",
            reply_markup=kb_share_contact())
        return
    if uid in _ORDER_BUSY:
        return      # второе нажатие, пока первый заказ ещё создаётся
    _ORDER_BUSY.add(uid)
    data = await state.get_data()
    # Не очищаем стейт здесь — очистка будет внутри таски после успешного сохранения в БД.
    # Если таска упадёт до order_create, пользователь останется в состоянии OrderForm.wishes
    # и сможет повторить попытку без потери данных.
    await safe_send(uid, "⏳ Рассчитываю...", reply_markup=ReplyKeyboardRemove())
    bg(_finalize_order_task(uid, data, wish, state), f"заказ {uid}")

def kb_share_contact():
    return ReplyKeyboardMarkup(
        keyboard=[[KeyboardButton(text="📱 Поделиться контактом", request_contact=True)],
                  [KeyboardButton(text="❌ Отменить")]],
        resize_keyboard=True, one_time_keyboard=True)


async def _passenger_info(pid):
    """Имя, ник, ссылка и телефон пассажира: из анкеты заказа, а чего там
    нет — из анкеты водителя, если человек ещё и водитель."""
    r = {}
    try:
        r = await DB.passenger_info(pid)
    except Exception as e:
        log.error(f"Пассажир {pid}: {e}")
    dphone = r.get("d_phone") if r.get("d_phone") not in (None, "", "—") else None
    link = r.get("profile_link") or ""
    return {
        "name": r.get("p_name") or f"{r.get('first_name') or ''} {r.get('last_name') or ''}".strip(),
        "username": (r.get("p_username") or r.get("d_username") or "").lstrip("@"),
        "phone": r.get("p_phone") or dphone,
        # Ссылку водитель вводит сам: кавычка или «<» в ней сломали бы всю карточку.
        "link": link if re.fullmatch(r"https://max\.ru/[\w\-/]+", link) else "",
    }


async def _passenger_phone(uid):
    return (await _passenger_info(uid))["phone"]


def _norm_phone(phone):
    """79604660969 / 89604660969 / +7 960… → 79604660969 (цифры, пригодные для ссылок)."""
    d = re.sub(r"\D", "", phone or "")
    if len(d) == 11 and d[0] == "8":
        d = "7" + d[1:]
    if len(d) == 10 and d[0] == "9":
        d = "7" + d
    return d


def _fmt_phone(raw):
    """Храним в одном виде, +7…: такой номер в Telegram нажимается.
    Местный номер с нуля (071…) — как написан: «+071…» не набрать."""
    n = _norm_phone(raw)
    return f"+{n}" if 10 <= len(n) <= 15 and n[0] != "0" else (raw or "").strip()


async def passenger_contact_lines(pid, tg_links=True, order=None):
    """Кто создал заказ — с кликабельными ссылками для быстрой связи.
    tg_links=False — для просмотра из MAX: ссылка tg:// там не откроется.
    order — для заявки с сайта, которую пассажир привязал к боту кнопкой
    «Следить в MAX/Telegram»: имя и телефон он оставил в форме, а в боте
    их может не быть."""
    info = await _passenger_info(pid)
    w = (order or {}).get("wishes") or ""
    name = esc(info["name"] or extract_site_name(w) or "Пассажир")
    un = info["username"]
    if is_max_uid(pid):
        url = f"https://max.ru/{un}" if un else (info["link"] or None)
        plat = "MAX"
    elif is_vk_uid(pid):
        url = f"https://vk.com/id{pid - VK_ID_OFFSET}"
        plat = "ВК"
    else:
        # Пассажир уже писал боту, поэтому ссылка по id у админа откроется.
        url = f"https://t.me/{un}" if un else (f"tg://user?id={pid}" if tg_links else None)
        plat = "Telegram"
    href = esc(url) if url else None
    # Заявка с сайта попадает к человеку в бот, только если он нажал
    # «Следить в …» — пишем это прямо, иначе непонятно, откуда тут MAX.
    tag = f"следит в {plat}" if "🌐 Заявка с сайта" in w else plat
    who = f"<a href='{href}'>{name}</a> ({tag})" if url else f"{name} ({tag})"
    lines = [f"👤 {who}"]
    if url:
        lines.append(f"💬 <a href='{href}'>Написать в {plat}</a>")
    sp = extract_site_phone(w)
    n = _norm_phone(info["phone"] or (sp if sp != "—" else ""))
    if n:
        lines.append(f"📞 +{n}")
        lines.append(f"✈️ <a href='https://t.me/+{n}'>Telegram по номеру</a>")
    else:
        lines.append("📞 не указан")
    return "\n".join(lines)


def mod_rows(oid):
    """Кнопки карточки на модерации: опубликовать всем, удалить
    или отдать одному водителю по личной ссылке."""
    return [[InlineKeyboardButton(text="✅ Опубликовать", callback_data=f"mod_ok_{oid}"),
             InlineKeyboardButton(text="🗑 Удалить",      callback_data=f"mod_del_{oid}")],
            [InlineKeyboardButton(text="🔗 Ссылка для водителя", callback_data=f"mod_give_{oid}")]]


def order_owner(o):
    """Кому сообщать о заказе: пассажиру из бота или диспетчеру."""
    pid = o.get("passenger_id") or 0
    return pid if pid > 0 else o.get("dispatcher_id")


async def admin_order_view(o, viewer=None):
    """Карточка заказа для админа — одна и та же при первой отправке и при
    каждом обновлении статуса. Раньше обновление превращало её в водительскую:
    без контактов пассажира, без кнопок модерации и со скрытым телефоном."""
    if o.get("dispatcher_id"):
        return await dsp_admin_view(o)
    oid, st = o["id"], o.get("status")
    pid = o.get("passenger_id") or 0
    if pid > 0 and "🌐 Заявка с сайта" not in (o.get("wishes") or ""):
        src = "MAX" if is_max_uid(pid) else ("ВК" if is_vk_uid(pid) else "Telegram")
        head = f"🆕 <b>Заказ #{oid} из бота {src}</b>"
    else:
        head = f"🌐 <b>Заявка #{oid} с сайта</b>"
    if st == "moderation":
        head += " — на модерации"
    lines = [head, "", fmt_order(o)]
    if o.get("driver_id") and st in ("taken", "completed"):
        drv = await DB.driver(o["driver_id"])
        lines.append(f"🚗 Водитель: {drv_name(drv)} · 📞 {esc(_fmt_phone(drv.get('phone') or '—'))}"
                     if drv else f"🚗 Водитель id <code>{o['driver_id']}</code>")
    if pid > 0:
        lines += ["", await passenger_contact_lines(pid, tg_links=not is_max_uid(viewer or 0), order=o)]
    if st == "moderation" and not o.get("distance_km"):
        if note := namesake_note(o.get("from_city"), o.get("to_city")):
            lines += ["", note]
        lines += ["", "⚠️ <b>Расстояние не рассчитано</b> — перед публикацией задайте цену:\n"
                      f"<code>/recalc {oid} КМ ЦЕНА</code>"]
    rows = mod_rows(oid) if st == "moderation" else []
    if pid > 0:
        rows.append([InlineKeyboardButton(text="✉️ Написать через бота",
                                          callback_data=f"admsg_{pid}")])
    return "\n".join(lines), (InlineKeyboardMarkup(inline_keyboard=rows) if rows else None)


@router.message(OrderForm.contact, F.contact)
async def step_contact(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    c = msg.contact
    if c.user_id and c.user_id != uid:
        await safe_send(uid, "❌ Отправьте свой контакт кнопкой ниже.", reply_markup=kb_share_contact()); return
    await _save_passenger_and_finish(msg, state, c.phone_number or "")


def _looks_like_phone(raw: str) -> bool:
    return 10 <= len(re.sub(r"\D", "", raw or "")) <= 15


PHONE_RETRY = ("❌ Не похоже на номер. Нажмите «📱 Поделиться контактом» "
               "или напишите номер, например +7 900 123-45-67.")


@router.message(OrderForm.contact)
async def step_contact_text(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    raw = (msg.text or "").strip()
    if not _looks_like_phone(raw):
        await safe_send(uid, PHONE_RETRY, reply_markup=kb_share_contact()); return
    await _save_passenger_and_finish(msg, state, raw)


async def _save_passenger_and_finish(msg, state, phone):
    uid = msg.from_user.id
    fn = f"{msg.from_user.first_name or ''} {msg.from_user.last_name or ''}".strip()
    try:
        await DB.passenger_save(uid, _fmt_phone(phone), fn, msg.from_user.username or "")
    except Exception as e:
        log.error(f"Сохранение пассажира {uid}: {e}")
        await safe_send(uid, "❌ Не удалось сохранить номер. Попробуйте ещё раз."); return
    if uid in _ORDER_BUSY:
        return
    _ORDER_BUSY.add(uid)
    data = await state.get_data()
    await safe_send(uid, "⏳ Рассчитываю...", reply_markup=ReplyKeyboardRemove())
    bg(_finalize_order_task(uid, data, data.get("wish", ""), state), f"заказ {uid}")


# Кто сейчас оформляет заказ. Состояние чистится только после записи в базу,
# и двойное нажатие успевало создать второй заказ.
_ORDER_BUSY: set = set()


async def _finalize_order_task(uid, data, wish, state: FSMContext):
    try:
        await _finalize_order(uid, data, wish, state)
    finally:
        _ORDER_BUSY.discard(uid)


async def _finalize_order(uid, data, wish, state: FSMContext):
    try:
        dkm, price, region = await get_distance_and_price_async(
            data["from_city"], data["to_city"], data["car_class"])
        price, raised = apply_min_price(price)
        if raised:
            await safe_send(uid,
                f"ℹ️ Минимальная стоимость поездки — {MIN_ORDER_PRICE} ₽.")
        row = {**data, "passenger_id": uid, "wishes": wish,
               "from_city": _add_region(data["from_city"]),      # область, с которой
               "to_city": _add_region(data["to_city"]),          # посчитана цена
               "distance_km": dkm, "price": price,
               "status": "moderation", "region": region}
        oid, _cancel_token = await DB.order_create(row)
    except Exception as e:
        log.error(f"Ошибка создания заказа: {e}")
        await safe_send(uid, "❌ Ошибка при создании заказа. Попробуйте ещё раз — данные сохранены.",
                        reply_markup=kb_passenger())
        return
    # Заказ уже в базе. Карточку собираем из тех же данных, без повторного
    # чтения: раньше сбой этого чтения прятал заказ от админов, а пассажиру
    # писалось «ошибка, попробуйте ещё раз» — и новый заказ уже не создавался.
    order = {**row, "id": oid}
    # Пока шёл расчёт, человек мог нажать кнопку меню и начать другое
    # (поиск рейса) — его не трогаем.
    if str(await state.get_state() or "").startswith("OrderForm:"):
        await state.clear()
    # Как и заявки с сайта: сначала модерация, водителям — только после «Опубликовать».
    async def _to_admins():
        for aid in ADMIN_IDS:
            text, kb = await admin_order_view(order, aid)
            m = await safe_send(aid, text, reply_markup=kb)
            if m:
                await remember_order_card(oid, aid, m)
    bg(_to_admins(), f"модерация #{oid}")
    cancel_kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="❌ Отменить заказ", callback_data=f"cancel_{oid}")
    ]])
    warn = (
        f"✅ <b>Заказ создан!</b>\n\n{fmt_order(order)}\n\n"
        + ("" if dkm else "💬 <b>Цену пока не посчитали автоматически</b> — уточним "
                          "её для вас в ближайшее время и сообщим здесь.\n\n")
        + "🟡 <b>Заказ на проверке</b> — после проверки он уйдёт водителям, "
          "мы сообщим вам здесь.\n\n"
        + "🚫 <b>Не переводите предоплату!</b>\n"
        + "Оплата — только водителю после поездки.\n"
        + f"<i>Если водитель просит предоплату — сообщите {ADMIN_CONTACT}</i>"
    )
    await safe_send(uid, warn, reply_markup=cancel_kb)
    await safe_send(uid, "✅ Заказ создан! Возвращаемся в меню.", reply_markup=kb_passenger())


# ══════════════ МОИ ЗАКАЗЫ ══════════════
@router.message(F.text == "📋 Мои заказы", StateFilter("*"))
async def my_orders(msg: Message, state: FSMContext):
    """Главное меню — только то, где человек пассажир.
    Поездки в роли водителя живут в меню водителя, в «Мои поездки»."""
    await state.clear()
    uid = msg.from_user.id
    result = await DB.passenger_orders(uid)
    if not result:
        await safe_send(uid, "📋 Нет пассажирских заказов.")
        return
    await safe_send(uid, f"📋 <b>Ваши заказы как пассажир</b> ({len(result)}):")
    for o in result:
        if o["status"] in ACTIVE_ORDER_STATUSES:
            # У взятого — и «Завершить»: водитель часто не нажимает его сам,
            # и прошедшая поездка не давала оформить новый заказ
            done = ([[InlineKeyboardButton(text="✅ Завершить поездку", callback_data=f"done_{o['id']}")]]
                    if o["status"] == "taken" else [])
            kb = InlineKeyboardMarkup(inline_keyboard=done + [[
                InlineKeyboardButton(text="❌ Отменить", callback_data=f"cancel_{o['id']}")
            ]])
            await safe_send(uid, fmt_order(o), reply_markup=kb)
        elif o["status"] == "completed" and o.get("driver_id") and not await DB.has_rating(o["id"], uid):
            await safe_send(uid, fmt_order(o) + "\n\n⭐ <b>Оцените поездку:</b>",
                            reply_markup=kb_stars(o["id"]))
        else:
            await safe_send(uid, fmt_order(o))


@router.message(F.text == "📈 Мои поездки", StateFilter("*"))
async def my_driver_trips(msg: Message, state: FSMContext):
    """Меню водителя — только взятые им заказы."""
    await state.clear()
    uid = msg.from_user.id
    drv = await DB.driver(uid)
    if not drv:
        await safe_send(uid, "❌ Вы ещё не зарегистрированы как водитель.", reply_markup=kb_main())
        return
    trips = [o for o in await DB.driver_orders(uid) if o["status"] in ("taken", "completed")]
    if not trips:
        await safe_send(uid, "📈 Вы ещё не брали заказов.", reply_markup=await kb_driver(uid))
        return
    active = sum(1 for o in trips if o["status"] == "taken")
    head = f"🚗 <b>Мои поездки</b> ({len(trips)})"
    if active:
        head += f"\n🟢 В работе: {active}"
    await safe_send(uid, head)
    for o in trips:
        kb = None
        if o["status"] == "taken":
            kb = InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="✅ Завершить поездку", callback_data=f"done_{o['id']}")],
                [InlineKeyboardButton(text="❌ Отказаться", callback_data=f"driver_cancel_{o['id']}")],
            ])
        await safe_send(uid, fmt_order(o), reply_markup=kb)


# ══════════════ ВОДИТЕЛЬ ══════════════
@router.message(F.text.in_({"🚕 Я водитель", "🚗 Я водитель"}), StateFilter("*"))
async def driver_enter(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    await state.clear()
    drv = await DB.driver(uid)
    if not drv:
        reg_kb = ReplyKeyboardMarkup(
            keyboard=[[KeyboardButton(text="👤 Зарегистрироваться")], [KeyboardButton(text="🔙 Главное меню")]],
            resize_keyboard=True,
        )
        await safe_send(uid,
            "🚗 <b>Режим водителя</b>\n\nДля регистрации нажмите кнопку ниже.\n\n"
            "<b>Что потребуется:</b>\n1️⃣ Поделиться контактом\n2️⃣ Марка и модель авто\n"
            "3️⃣ Год выпуска\n4️⃣ Гос. номер\n5️⃣ Класс авто\n\n"
            "После регистрации администратор верифицирует профиль.",
            reply_markup=reg_kb)
        return
    exp, dl, active = await DB.sub_info(uid)
    avg, cnt = await DB.avg_rating(uid)
    await safe_send(uid,
        f"🚗 <b>{drv_name(drv)}</b>\n"
        f"🚘 {esc(drv.get('car_model'))} {drv.get('car_year','—')} г.\n"
        f"🔢 {esc(drv.get('car_number'))}\n"
        f"🏷 {esc(drv.get('car_class_label'))}\n"
        f"📞 {esc(_fmt_phone(drv.get('phone')))}\n"
        f"📄 {'✅ Верифицирован' if drv.get('docs_verified') else '⏳ Ожидает верификации'}\n"
        f"💳 {'✅ Подписка до '+fmt_date_ru(exp)+' ('+str(dl)+' дн.)' if active else '❌ Нет подписки'}\n"
        f"{'⭐ Рейтинг: '+str(avg)+' ('+str(cnt)+' оценок)' if cnt else '⭐ Нет оценок'}",
        reply_markup=await kb_driver(uid))

@router.message(F.text == "📦 Доступные заказы", StateFilter("*"))
async def avail_orders(msg: Message, state: FSMContext):
    await state.clear()
    uid = msg.from_user.id
    drv = await DB.driver(uid)
    if not drv: await safe_send(uid, "❌ Сначала зарегистрируйтесь."); return
    _, _, active = await DB.sub_info(uid)
    if not active: await safe_send(uid, "🔒 Нет абонемента."); return
    if not drv.get("docs_verified"): await safe_send(uid, "⏳ Профиль ещё не верифицирован администратором."); return
    all_open = [o for o in await DB.open_orders() if uid not in (o["passenger_id"], o.get("dispatcher_id"))]
    if not all_open: await safe_send(uid, "📭 Нет доступных заказов."); return
    can = sum(1 for o in all_open if can_take_order(drv, o)[0])
    # Показываем десять — пусть это будут доступные, а не чужие по классу.
    all_open.sort(key=lambda o: not can_take_order(drv, o)[0])
    await safe_send(uid, f"📦 <b>Открыто: {len(all_open)}</b> | ✅ Доступно: <b>{can}</b>\n"
                    f"🏷 {esc(drv.get('car_class_label'))}")
    for o in all_open[:10]:
        ct, rsn = can_take_order(drv, o)
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="✅ Взять" if ct else rsn,
                                 callback_data=f"take_{o['id']}" if ct else "cant_take")
        ]])
        msg_card = await safe_send(uid, fmt_order(o, redact_phone=True), reply_markup=kb)
        # Запоминаем и эти карточки, в том числе закрытые замком: иначе после
        # отмены или взятия заказа они так и показывают «Открыт».
        if msg_card:
            await remember_order_card(o["id"], uid, msg_card)

@router.message(F.text.in_({"✅ Подписка активна","❌ Нет подписки"}), StateFilter("*"))
async def sub_btn(msg: Message, state: FSMContext):
    await state.clear()
    await subscription_menu(msg)


