@router.message(DriverRegForm.car_number)
async def p_number(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    if not msg.text:
        await safe_send(uid, "❌ Пожалуйста, отправьте текстом."); return
    number = msg.text.strip().upper().replace(" ","")
