@router.callback_query(F.data.startswith("rate_"))
async def cb_rate(call: CallbackQuery):
    uid = call.from_user.id
    _, oid_str, stars_str = call.data.split("_")
    oid, stars = int(oid_str), int(stars_str)
    order = await DB.order(oid)
    if not order:
        await call.answer("❌ Заказ не найден"); return
    if order["passenger_id"] != uid:
        await call.answer("❌ Не ваш заказ", show_alert=True); return
    if order["status"] != "completed":
        await call.answer("❌ Заказ не завершён"); return
    drv_id = order.get("driver_id")
    if not drv_id:
        await call.answer("❌ Нет водителя"); return
    if await DB.has_rating(oid, uid):
        await call.answer("Вы уже оценили эту поездку")
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    if not 1 <= stars <= 5 or not await DB.add_rating(oid, drv_id, uid, stars):
        await call.answer("Вы уже оценили эту поездку")
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    await call.answer("✅ Спасибо за оценку!")
    avg, cnt = await DB.avg_rating(drv_id)
    try:
        await bot.edit_message_text(
            text=f"✅ <b>Поездка #{oid} завершена!</b>\n⭐ Ваша оценка: <b>{stars}</b>\nСпасибо!",
            chat_id=call.message.chat.id,
            message_id=call.message.message_id)
    except:
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        await safe_send(uid, f"⭐ Оценка {stars} сохранена!")
    await safe_send(drv_id,
        f"⭐ <b>Новая оценка за поездку #{oid}!</b>\n"
        f"Пассажир поставил: <b>{stars}⭐</b>\nВаш средний рейтинг: <b>{avg}/5</b> ({cnt} оценок)")

@router.callback_query(F.data.startswith("take_"))
async def cb_take(call: CallbackQuery):
    uid = call.from_user.id
    oid = int(call.data.split("_")[1])
    drv = await DB.driver(uid)
    if not drv or not drv.get("docs_verified"):
        await call.answer("❌ Профиль не верифицирован", show_alert=True); return
    _, _, active = await DB.sub_info(uid)
    if not active:
        await call.answer("❌ Нет абонемента", show_alert=True); return
    od = await DB.order(oid)
    if not od:
        await call.answer("❌ Заказ не найден")
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    if od["status"] != "open":
        # Заказ уже разобран, отменён или завершён — кнопка больше ни к чему.
        # Гасим её, чтобы водитель не тыкал в мёртвые сообщения.
        await call.answer(STATUS_ICON.get(od["status"], od["status"]))
        await refresh_order_card(call.message.chat.id, call.message.message_id, oid)
        return
    if uid in (od["passenger_id"], od.get("dispatcher_id")):
        await call.answer("❌ Нельзя взять свой заказ", show_alert=True); return
    ct, rsn = can_take_order(drv, od)
    if not ct:
        await call.answer(rsn, show_alert=True); return
    if od.get("dispatcher_id"):
        await dsp_take(call, uid, od, drv)
        return
    # Отвечаем Telegram сразу — до тяжёлых операций
    await call.answer("⏳ Принимаем заказ...")
    if not await DB.order_take_atomic(oid, uid):
        od = await DB.order(oid)
        if od and od.get("driver_id") == uid:
            return      # двойное нажатие: заказ уже его, «взял другой» не пишем
        await safe_send(uid, "⚠️ Заказ уже недоступен — его взял другой водитель.")
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    await _order_taken(call, uid, oid, drv)


@router.callback_query(F.data.startswith("give_"))
async def cb_give(call: CallbackQuery):
    """«Взять» по личной ссылке админа: и с модерации, без проверки
    абонемента и класса — кому отдать заказ, решил админ."""
    uid = call.from_user.id
    oid = give_oid(call.data)
    if not oid:
        await call.answer("❌ Ссылка неверна", show_alert=True); return
    drv = await DB.driver(uid)
    if not drv:
        await call.answer("❌ Сначала зарегистрируйтесь как водитель", show_alert=True); return
    od = await DB.order(oid)
    if od and od["passenger_id"] == uid:
        await call.answer("❌ Нельзя взять свой заказ", show_alert=True); return
    await call.answer("⏳ Принимаем заказ...")
    if not await DB.order_take_atomic(oid, uid, ("moderation", "open")):
        od = await DB.order(oid)
        if od and od.get("driver_id") == uid:
            return      # двойное нажатие: заказ уже его, «взял другой» не пишем
        await safe_send(uid, "⚠️ Заказ уже недоступен — его взял другой водитель или он отменён.")
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    for aid in ADMIN_IDS:
        bg(safe_send(aid, f"✅ Заказ #{oid} по ссылке взял {drv_name(drv)}"), f"админу #{oid}")
    if od and od["status"] == "moderation":     # админ отдал заявку водителю — она настоящая
        bg(metrika_confirm(od), f"Метрика #{oid}")
    await _order_taken(call, uid, oid, drv)


async def _order_taken(call, uid, oid, drv):
    """Заказ взят: водителю — контакты пассажира, пассажиру — водитель.
    Общее для «Взять» из рассылки и по личной ссылке админа."""
    bg(update_channel_post(oid), f"канал #{oid}")
    od = await DB.order(oid)
    if not od: return
    pid = od.get("passenger_id")
    if not pid: return

    is_site_order = pid <= 0  # заявка с сайта, ещё не привязана к реальному Telegram-чату
    if is_site_order:
        pn, pu = "Пассажир с сайта", None
        site_phone = extract_site_phone(od.get("wishes", ""))
    else:
        # Имя и ник — из анкеты заказа: так быстрее, чем спрашивать Telegram,
        # и работает для MAX, где Telegram этого человека не знает.
        pinfo = await _passenger_info(pid)
        pn = esc(pinfo["name"]) if pinfo["name"] else ""
        pu = None if is_vk_uid(pid) else (pinfo["username"] or None)
        if not pn and not (is_max_uid(pid) or is_vk_uid(pid)):
            try:
                pc = await bot.get_chat(pid)
                pn, pu = esc(pc.first_name or ""), pc.username
            except Exception:
                pass
        pn = pn or esc(extract_site_name(od.get("wishes")), "") or "Пассажир"
        site_phone = None

    purl = None if is_site_order else dm_url(pid, pu)
    avg, cnt = await DB.avg_rating(uid)
    r_text   = f"\n⭐ Рейтинг: <b>{avg}/5</b> ({cnt} оценок)" if cnt else "\n⭐ Новый водитель"
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)

    drv_kb_rows = []
    if purl:
        drv_kb_rows.append([InlineKeyboardButton(text="💬 Написать пассажиру", url=purl)])
    drv_kb_rows.append([InlineKeyboardButton(text="✅ Завершить поездку", callback_data=f"done_{oid}")])
    drv_kb_rows.append([InlineKeyboardButton(text="❌ Отказаться", callback_data=f"driver_cancel_{oid}")])
    drv_kb = InlineKeyboardMarkup(inline_keyboard=drv_kb_rows)

    if not purl and not is_site_order and not (is_max_uid(pid) or is_vk_uid(pid) or is_max_uid(uid)):
        # Пассажир писал боту — упоминание по id у водителя откроется.
        purl_text = f"tg://user?id={pid}"
    else:
        purl_text = purl
    passenger_line = f"👤 <a href='{purl_text}'>{pn}</a>" if purl_text else f"👤 {pn}"
    if is_site_order:
        site_phone_line = f"\n📞 <b>Телефон пассажира:</b> {esc(site_phone)}"
    else:
        site_ph = extract_site_phone(od.get("wishes", ""))
        _n = _norm_phone(pinfo["phone"] or (site_ph if site_ph != "—" else ""))
        site_phone_line = (f"\n📞 <b>Телефон пассажира:</b> +{_n}"
                           f"\n✈️ <a href='https://t.me/+{_n}'>Telegram по номеру</a>") if _n else ""
    await safe_send(uid,
        f"✅ <b>Заказ #{oid} принят!</b>\n{passenger_line}{site_phone_line}\n"
        f"📍 {esc(od.get('from_city'))} → {esc(od.get('to_city'))}\n"
        f"📅 {esc(fmt_date_ru(od.get('trip_date')))} 🕐 {esc(od.get('trip_time'))}", reply_markup=drv_kb)
    if is_site_order:
        await safe_send(uid, "ℹ️ Это заявка с сайта. Пассажир пока не открывал Telegram-бота — "
                              "свяжитесь с ним напрямую по указанному телефону.")

    du = (drv.get("username","") or "").lstrip("@")
    durl = dm_url(uid, du)
    pass_kb = InlineKeyboardMarkup(inline_keyboard=[
        *([[InlineKeyboardButton(text="📞 Написать водителю", url=durl)]] if durl else []),
        [InlineKeyboardButton(text="✅ Завершить поездку",  callback_data=f"done_{oid}")],
        [InlineKeyboardButton(text="❌ Отменить",           callback_data=f"cancel_{oid}")],
    ])
    car_note = (f"\n⚠️ <i>Водитель приедет на {esc(drv.get('car_class_label',drv.get('car_class','')))}</i>"
                if drv.get("car_class") != od.get("car_class") else "")
    if pid > 0:
        await safe_send(pid,
            f"🎉 <b>Водитель найден!</b>\n"
            f"👤 {drv_name(drv)}{r_text}\n"
            f"🚘 {esc(drv.get('car_model'))} ({drv.get('car_year','—')})\n"
            f"🔢 {esc(drv.get('car_number'))}\n"
            f"📞 {esc(_fmt_phone(drv.get('phone')))}{car_note}\n\n"
            f"⏳ <i>Ожидайте — с вами свяжется водитель.</i>\n\n"
            f"🚫 <b>Не переводите предоплату!</b>\n"
            f"Оплата — только водителю после поездки.\n"
            f"<i>Если водитель просит предоплату — сообщите {ADMIN_CONTACT}</i>",
            reply_markup=pass_kb)
    # если pid <= 0 (заявка с сайта, ещё не привязана) — пассажиру в Telegram
    # отправлять некому; он либо получит звонок от водителя, либо позже
    # перейдёт по ссылке orderlink_ и увидит статус там.

@router.callback_query(F.data.regexp(r"^cancel_\d+$"))
async def cb_cancel(call: CallbackQuery):
    uid = call.from_user.id
    oid = int(call.data.split("_")[1])
    if await DB.order_cancel_atomic(oid, uid, "passenger"):
        await call.answer("✅ Отменено")
        await _clear_notified(oid)
        await update_channel_post(oid)
        order = await DB.order(oid)
        if order and order.get("driver_id"):
            await safe_send(order["driver_id"], f"❌ Пассажир отменил заказ #{oid}")
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        await safe_send(uid, f"✅ Заказ #{oid} отменён.", reply_markup=kb_passenger())
    else:
        await call.answer("❌ Заказ уже нельзя отменить", show_alert=True)

@router.callback_query(F.data.startswith("driver_cancel_"))
async def cb_driver_cancel(call: CallbackQuery):
    uid = call.from_user.id
    oid = int(call.data.split("_")[2])
    if await DB.order_cancel_atomic(oid, uid, "driver"):
        await call.answer("✅")
        await dsp_bids_clear(oid)       # заказ диспетчера: отклики собираются заново
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        await safe_send(uid, f"✅ Вы отказались от заказа #{oid}")

        # Канал, пассажир и повторная рассылка водителям — фоном: рассылка
        # идёт по всем водителям, и отказавшийся ждал бы её целиком.
        async def _after_cancel():
            order = await DB.order(oid)
            st = order["status"] if order else None
            if st == "open":
                # Только открытый: рассылка ставит отметку «разослан» ещё до
                # проверки статуса, и заказ, который успели снова взять по
                # ссылке, при следующем отказе ушёл бы всем вместо модерации.
                # Сразу, до сообщений: прежние карточки уходят из базы раньше,
                # чем фоновый обход успеет разослать заказ сам.
                bg(reannounce(oid, exclude_uid=uid), f"повторная рассылка #{oid}")
            else:
                # Отдан по ссылке с модерации — дальше решает админ, а не рассылка
                await update_channel_post(oid)
                await _clear_notified(oid)
            pid = order.get("passenger_id") if order else None
            if pid and pid > 0:
                await safe_send(pid, f"❌ Водитель отказался от заказа #{oid}")
            elif did := (order or {}).get("dispatcher_id"):
                await safe_send(did, f"↩️ {drv_name(await DB.driver(uid))} отказался от заказа #{oid} — "
                                     f"заказ снова в поиске, ждите новых откликов.")
            # Админам — кто взял и отказался: взять и отказаться можно и ради
            # телефона пассажира, а без имени админ этого не видел.
            if st in ("open", "moderation"):
                drv = await DB.driver(uid)
                who = (f"{drv_name(drv)} · 📞 {esc(_fmt_phone(drv.get('phone') or '—'))}" if drv
                       else "Водитель") + f" (id <code>{uid}</code>)"
                what = "рассылаю водителям заново" if st == "open" else "заявка снова на модерации"
                for aid in ADMIN_IDS:
                    await safe_send(aid, f"↩️ {who} взял заказ #{oid} и отказался — {what}.")
        bg(_after_cancel(), f"отказ от #{oid}")
    else:
        await call.answer("❌ Заказ уже нельзя отменить", show_alert=True)

@router.callback_query(F.data.startswith("done_"))
async def cb_done(call: CallbackQuery):
    uid = call.from_user.id
    oid = int(call.data.split("_")[1])
    o = await DB.order(oid)
    if not o:
        await call.answer("❌ Заказ не найден"); return
    is_passenger = o["passenger_id"] == uid
    is_driver = o.get("driver_id") == uid
    is_disp = bool(o.get("dispatcher_id")) and o["dispatcher_id"] == uid
    if not (is_passenger or is_driver or is_disp):
        await call.answer("❌ Не ваш заказ", show_alert=True); return
    if o["status"] != "taken":
        await call.answer("❌ Заказ не в работе", show_alert=True); return
    if not await DB.order_status_cas(oid, "taken", status="completed", completed_at=now_iso()):
        await call.answer("❌ Заказ уже не в работе", show_alert=True); return
    await call.answer("✅ Завершено")
    await _clear_notified(oid)
    bg(update_channel_post(oid), f"канал #{oid}")
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    if is_passenger:
        await safe_send(uid, "✅ <b>Поездка завершена!</b>\n⭐ Пожалуйста, оцените водителя:",
                        reply_markup=kb_stars(oid))
        if o.get("driver_id"):
            bg(safe_send(o["driver_id"], f"✅ Поездка #{oid} завершена пассажиром!"),
               f"водителю #{oid}")
    elif is_disp and not is_driver:
        await safe_send(uid, f"✅ Заказ #{oid} отмечен выполненным.")
        if o.get("driver_id"):
            bg(safe_send(o["driver_id"], f"✅ Диспетчер отметил заказ #{oid} выполненным."),
               f"водителю #{oid}")
    else:  # завершил водитель
        await safe_send(uid, f"✅ Поездка #{oid} отмечена завершённой.")
        if o.get("dispatcher_id"):
            bg(safe_send(o["dispatcher_id"], f"✅ Водитель отметил заказ #{oid} выполненным."),
               f"диспетчеру #{oid}")
        if o.get("passenger_id") and o["passenger_id"] > 0:
            bg(safe_send(o["passenger_id"], f"✅ Водитель отметил поездку #{oid} завершённой.\n"
                            f"⭐ Пожалуйста, оцените водителя:", reply_markup=kb_stars(oid)),
               f"пассажиру #{oid}")

@router.callback_query(F.data.startswith("sub_"))
async def cb_sub(call: CallbackQuery):
    uid = call.from_user.id
    if not await DB.driver(uid):
        await call.answer("❌ Заполните профиль", show_alert=True); return
    pk = call.data.split("_")[1]
    plan = SUBS.get(pk)
    if not plan:
        await call.answer("❌"); return
    await call.answer()
    await DB.pending_set(uid, pk)
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    await safe_send(uid,
        f"💳 <b>{plan['label']}</b>\n\n"
        f"Переведите <b>{fmt_price(plan['price'])}</b>\n{PAYMENT_DETAILS}\n\n"
        f"📸 После оплаты пришлите сюда <b>фото или скриншот чека</b> — "
        f"абонемент включится после проверки.")

@router.callback_query(F.data.startswith("paid_"))
async def cb_paid(call: CallbackQuery):
    # «Я оплатил» на сообщениях до v20.7: теперь оплату подтверждает чек
    await call.answer("📸 Пришлите сюда фото или скриншот чека", show_alert=True)


async def _sub_pending(msg: Message) -> bool:
    """Фото и файлы считаем чеком, только пока водитель ждёт оплату тарифа.
    Остальные идут дальше, как раньше."""
    return bool(msg.from_user and await DB.pending_get(msg.from_user.id))


async def _receipt_to(aid, fid, is_doc, fname, caption, kb):
    """Чек одному админу. Из MAX вместо file_id приходит ссылка («max:…»):
    Telegram по ней файл сам не возьмёт, поэтому скачиваем. Админу в MAX —
    карточка со ссылкой: загружать файлы в MAX бот не умеет."""
    url = fid[4:] if fid.startswith("max:") else None
    link = f'\n📎 <a href="{html.escape(url)}">Открыть чек</a>' if url else ""
    if is_max_uid(aid):
        return await safe_send(aid, caption + (link or "\n📎 Чек — в карточке в Telegram"), reply_markup=kb)
    media = fid
    try:
        if url:
            s = await _max_session()
            async with s.get(url) as r:
                if r.status != 200:
                    raise RuntimeError(f"HTTP {r.status}")
                # Больше 20 МБ не качаем: Telegram такой от бота всё равно не
                # примет, а память у бота одна на всё — админу уйдёт ссылка
                data = bytearray()
                async for chunk in r.content.iter_chunked(1 << 16):
                    data += chunk
                    if len(data) > 20 * 1024 * 1024:
                        raise RuntimeError("чек больше 20 МБ")
                media = BufferedInputFile(bytes(data), fname or "chek.jpg")
        send = bot.send_document if is_doc else bot.send_photo
        return await send(aid, media, caption=caption, reply_markup=kb)
    except Exception as e:
        log.error(f"Чек админу {aid} не отправился: {e}")
        return await safe_send(aid, caption + (link or "\n⚠️ Фото чека не дошло — попросите водителя прислать ещё раз"),
                               reply_markup=kb)


def _sub_caption(drv, uid, plan, title="💳 <b>Оплата абонемента — проверьте чек</b>"):
    return (f"{title}\n\n"
            f"👤 {drv_name(drv)}\n📞 {esc(_fmt_phone(drv.get('phone')))}\n"
            f"🚘 {esc(drv.get('car_model'))} ({drv.get('car_year','—')})\n"
            f"🔢 {esc(drv.get('car_number'))}\n🏷 {esc(drv.get('car_class_label'))}\n"
            f"📄 {'✅ Верифицирован' if drv.get('docs_verified') else '⏳ Не верифицирован'}\n"
            f"💬 {profile_link_html(drv)}\n\n"
            f"Тариф: <b>{plan.get('label', '—')}</b>\nID: <code>{uid}</code>")


def _sub_stamp(receipt) -> str:
    """Метка чека в кнопках карточки. Карточка срабатывает только на свою
    заявку: раньше старая карточка того же тарифа (у второго админа) давала
    водителю ещё срок без оплаты, если он снова открыл тариф, а «Отклонить»
    на ней отклоняло новую оплаченную заявку."""
    return hashlib.md5((receipt or "").encode()).hexdigest()[:8]


def _sub_kb(uid, pk, receipt=None):
    st = _sub_stamp(receipt)
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="✅ Активировать", callback_data=f"conf_sub_{uid}_{pk}_{st}"),
        InlineKeyboardButton(text="❌ Отклонить",    callback_data=f"rej_sub_{uid}_{pk}_{st}"),
    ]])


@router.message(F.photo | F.document, _sub_pending)
async def sub_receipt(msg: Message):
    uid = msg.from_user.id
    pk = await DB.pending_get(uid)
    plan, drv = SUBS.get(pk or ""), await DB.driver(uid)
    if not plan or not drv:
        await safe_send(uid, "Выберите тариф в «💳 Абонемент» и пришлите чек ещё раз.")
        return
    doc = msg.document
    fid, fname = (doc.file_id, doc.file_name) if doc else (msg.photo[-1].file_id, None)
    # Сначала сохраняем: кнопки карточки сверяются с чеком в базе
    rec = json.dumps({"f": fid, "d": bool(doc), "n": fname})
    try:
        await DB.pending_receipt(uid, rec)
    except Exception as e:
        log.error(f"Чек {uid} не сохранён для «💳 Оплаты»: {e}")
    caption, kb = _sub_caption(drv, uid, plan), _sub_kb(uid, pk, rec)
    log.info(f"Чек об оплате от {uid}: {plan['label']}")
    for aid in ADMIN_IDS:
        await _receipt_to(aid, fid, bool(doc), fname, caption, kb)
    await safe_send(uid, "⏳ Чек отправлен на проверку. Абонемент включится после подтверждения, "
                         "обычно в течение 1–2 ч.", reply_markup=await kb_driver(uid))

@router.callback_query(F.data == "back_driver")
async def cb_back_driver(call: CallbackQuery):
    uid = call.from_user.id
    await call.answer()
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    await safe_send(uid, "🚗 Меню водителя", reply_markup=await kb_driver(uid))


# ══════════════ АДМИН-КОЛБЭКИ ══════════════
@router.callback_query(F.data.startswith("conf_sub_"))
async def cb_conf_sub(call: CallbackQuery):
    uid = call.from_user.id
    if uid not in ADMIN_IDS:
        await call.answer("❌"); return
    parts = call.data.split("_")
    tgt, pk = int(parts[2]), parts[3]
    plan = SUBS.get(pk)
    if not plan:
        await call.answer("❌"); return
    if len(parts) < 5:          # карточка до v21.6 — без метки чека
        await call.answer("⚠️ Карточка устарела — откройте «💳 Оплаты»", show_alert=True)
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    # Карточка оплаты приходит всем админам. Без атомарного «забрать заявку»
    # два нажатия продлевали абонемент дважды. Забираем, только если тариф
    # тот же, что на карточке: раньше активировался выбранный последним —
    # заплатил за 60 дней, нажал «1 год» — получил год.
    try:
        new_exp = await DB.sub_activate(tgt, pk, parts[4], plan["days"], uid)
    except Exception as e:
        log.error(f"Активация абонемента {tgt}: {e}")
        await call.answer("⚠️ База не ответила — ничего не изменилось. Нажмите ещё раз через минуту",
                          show_alert=True)
        return
    if not new_exp:
        cur = await DB.pending_get(tgt)
        if cur and cur != pk:
            await call.answer("⚠️ Водитель сменил тариф — ничего не активировано", show_alert=True)
            await safe_send(uid,
                f"⚠️ <b>Абонемент не активирован</b>\n"
                f"На карточке — «{plan['label']}», а водитель после этого выбрал "
                f"«{esc(SUBS.get(cur, {}).get('label', cur))}».\n"
                f"Сверьте сумму. Если оплачено по карточке — продлите вручную:\n"
                f"<code>/extend {tgt} {plan['days']}</code>")
            return
        if cur:                 # тот же тариф, но заявка уже другая (новый чек или снова открыл тариф)
            await call.answer("⚠️ Карточка устарела — у водителя новая заявка. Откройте «💳 Оплаты»", show_alert=True)
            await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
            return
        await call.answer("Уже обработано", show_alert=True)
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    await call.answer("✅")
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    await safe_send(uid, f"✅ Подписка активирована до {fmt_date_ru(new_exp)}")
    await safe_send(tgt,
        f"🎉 <b>Абонемент активирован!</b>\n{plan['label']}\n"
        f"До: {datetime.strptime(new_exp,'%Y-%m-%d').strftime('%d.%m.%Y')}",
        reply_markup=await kb_driver(tgt))

@router.callback_query(F.data.startswith("rej_sub_"))
async def cb_rej_sub(call: CallbackQuery):
    uid = call.from_user.id
    if uid not in ADMIN_IDS:
        await call.answer("❌"); return
    # Тариф с карточки: «Отклонить» на старой карточке (водитель потом выбрал
    # другой тариф и оплатил) отклонял уже новую заявку. Старые карточки — без тарифа
    parts = call.data.split("_")
    tgt, card_pk = int(parts[2]), (parts[3] if len(parts) > 3 else None)
    if len(parts) < 5:          # карточка до v21.6 — без метки чека
        await call.answer("⚠️ Карточка устарела — откройте «💳 Оплаты»", show_alert=True)
        await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        return
    pk = await DB.pending_take(tgt, card_pk, parts[4])
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    if not pk:
        stale = card_pk and await DB.pending_get(tgt)
        await call.answer("⚠️ Карточка устарела — у водителя новая заявка, она не тронута"
                          if stale else "Уже обработано", show_alert=True)
        return
    await call.answer("❌")
    await DB.pending_del(tgt, uid, pk)   # запись в журнал отказов
    await safe_send(tgt,
        f"❌ <b>Оплата не подтверждена.</b>\n"
        f"Если перевод был — выберите тариф ещё раз и пришлите чек.\n"
        f"Вопросы — администратору {ADMIN_CONTACT}", reply_markup=kb_subs())

@router.callback_query(F.data.regexp(r"^doc_(ok|rej)_\d+(_\d+)?$"))
async def cb_doc_verify(call: CallbackQuery):
    uid = call.from_user.id
    if uid not in ADMIN_IDS:
        await call.answer("❌")
        return
    ok  = call.data.startswith("doc_ok_")
    parts = call.data.split("_")
    tgt = int(parts[2])

    # Админов несколько, и карточка приходит каждому. Если кто-то уже
    # нажал кнопку, второй тык прислал бы водителю повторное
    # уведомление. Сравниваем с текущим состоянием и молча гасим кнопки.
    drv_now = await DB.driver(tgt)
    if not drv_now:
        await call.answer("❌ Водитель не найден", show_alert=True)
        await safe_edit_markup(call.message.chat.id, call.message.message_id,
                               reply_markup=None)
        return
    # Повтор гасим только для «Верифицировать»: у нового водителя отметки
    # и так нет, и «Отказать» раньше принималось за уже сделанное.
    if ok and drv_now.get("docs_verified"):
        await call.answer("Уже сделано другим админом")
        await safe_edit_markup(call.message.chat.id, call.message.message_id,
                               reply_markup=None)
        return
    # Карточка новой регистрации: решает первый нажавший админ. Иначе второй
    # старой кнопкой «Отказать» снимал уже выданную верификацию, а «✅»
    # верифицировал того, кому первый отказал.
    flag = f"docreg:{tgt}:{parts[3]}" if len(parts) > 3 else None
    if flag and not await DB.flag_once(flag):
        await call.answer("Уже решено другим админом", show_alert=True)
        await safe_edit_markup(call.message.chat.id, call.message.message_id,
                               reply_markup=None)
        return

    await call.answer("✅" if ok else "❌")
    try:
        await DB.driver_verify(tgt, ok)
    except Exception as e:
        log.error(f"cb_doc_verify: {e}")
        if flag:            # решение не записалось — карточка должна остаться рабочей
            try:
                async with _pg_pool.acquire() as c:
                    await c.execute("DELETE FROM bot_flags WHERE key=$1", flag)
            except Exception:
                pass
        await safe_send(uid, f"❌ Ошибка при верификации: {e}")
        return
    await safe_edit_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    if ok:
        await safe_send(uid, f"✅ Профиль водителя {tgt} верифицирован")
        # Заказы берут только с абонементом — без него «можете принимать» неправда
        if (await DB.sub_info(tgt))[2]:
            await safe_send(tgt, "✅ <b>Ваш профиль верифицирован!</b>\nТеперь вы можете принимать заказы.",
                            reply_markup=await kb_driver(tgt))
        elif await DB.pending_get(tgt):
            await safe_send(tgt, "✅ <b>Ваш профиль верифицирован!</b>\nЗаказы откроются, как только администратор "
                                 "подтвердит оплату абонемента. Если чек ещё не прислали — пришлите его сюда.",
                            reply_markup=await kb_driver(tgt))
        else:
            await safe_send(tgt, "✅ <b>Ваш профиль верифицирован!</b>", reply_markup=await kb_driver(tgt))
            await safe_send(tgt, "💳 <b>Чтобы получать заказы, оформите абонемент:</b>", reply_markup=kb_subs())
    else:
        await safe_send(uid, f"❌ Профиль {tgt} отклонён")
        await safe_send(tgt, f"❌ <b>Верификация отклонена.</b>\nОбратитесь к администратору {ADMIN_CONTACT}.")

