@router.callback_query(F.data == "all_trips")
async def open_trips_list(call: CallbackQuery, state: FSMContext):
    """Показывает ближайшие рейсы сразу, без вопросов о городах и дате."""
    await call.answer()
    await state.clear()
    uid = call.from_user.id
    if await DB.bl_check(uid):
        await safe_send(uid, "⛔ Вы заблокированы.")
        return
    trips = await DB.trips_open()
    if not trips:
        await safe_send(uid,
            "🚌 <b>Сейчас открытых рейсов нет.</b>\n\n"
            "Создайте обычный заказ — водитель откликнется.",
            reply_markup=kb_passenger())
        return
    await safe_send(uid, f"🚌 <b>Ближайшие рейсы</b> ({len(trips)})")
    # Водителей и рейтинги грузим одним заходом: база в другой стране,
    # последовательные запросы заметно тормозят.
    drivers = await asyncio.gather(*(DB.driver(t["driver_id"]) for t in trips))
    ratings = await asyncio.gather(*(DB.avg_rating(t["driver_id"]) for t in trips))
    for t, drv, (avg, cnt) in zip(trips, drivers, ratings):
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="📌 Забронировать место",
                                  callback_data=f"book_trip_{t['id']}")],
            [InlineKeyboardButton(text="🗺 Маршрут",
                                  url=yandex_maps_url(t["from_city"], t["to_city"]))],
        ])
        await safe_send(uid, fmt_trip(t, drv=drv, avg=avg, cnt=cnt), reply_markup=kb)
        await _pace(uid)
    await safe_send(uid,
        "⬆️ Выберите рейс и нажмите «Забронировать».\n"
        "Нужно что-то конкретное — нажмите «Поехать вместе» и задайте города и дату.",
        reply_markup=kb_passenger())

@router.message(F.text == "🚐 Поехать вместе", StateFilter("*"))
async def search_trip_start(msg: Message, state: FSMContext):
    # ✅ ГАРАНТИРОВАННЫЙ СБРОС ПЕРЕД СТАРТОМ
    await state.clear()
    
    uid = msg.from_user.id
    if await DB.bl_check(uid):
        await safe_send(uid, "⛔ Вы заблокированы.")
