    await state.set_state(SearchTripForm.from_city)
    # Кнопка рядом с первым шагом: кто не знает точной даты, раньше
    # просто ничего не видел — поиск требовал все три параметра.
    await safe_send(uid,
        "🚐 <b>Поиск рейса</b>\n\n🏙 <b>Шаг 1/3</b> — Откуда едете?",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="🚌 Показать все рейсы", callback_data="all_trips")
        ]]))
