@router.message(DispEditForm.value)
async def dsp_edit_value(msg: Message, state: FSMContext):
    uid = msg.from_user.id
    data = await state.get_data()
    oid, field = data["oid"], data["field"]
    od = await DB.order(oid)
    if not _dsp_owner(od, uid) or od["status"] not in ACTIVE_ORDER_STATUSES:
        await state.clear()
        await safe_send(uid, "Заказ уже нельзя изменить.", reply_markup=kb_main()); return
    raw = (msg.text or "").strip()
    upd, err = {}, None
    if field == "price":
        parts = [p for p in re.split(r"[/\\|;\n]", raw) if p.strip()]
        total = _dsp_num(parts[0], 100, 10_000_000) if len(parts) == 2 else None
        hand = _dsp_num(parts[1], 0, total) if total else None
        if hand is None:
            err = "❌ Две суммы через «/»: стоимость и на руки, например 22500/20000"
        else:
            upd = {"price": total, "pay_driver": hand}
    elif field == "km":
        n = _dsp_num(raw, 1, 10000)
        upd, err = ({"distance_km": float(n)}, None) if n else ({}, "❌ Расстояние числом")
    elif field in ("from", "to"):
        t = _dsp_text(raw)
        upd, err = ({"from_city" if field == "from" else "to_city": t}, None) if t else ({}, "❌ Слишком коротко")
    elif field == "when":
        if raw.lower().startswith("срочно"):
            upd = _dsp_urgent_when()
        else:
            bits = raw.split()
            d = _dsp_date(" ".join(bits[:-1])) if len(bits) >= 2 else None
            p = parse_ru_time(bits[-1]) if d else None
            if not (d and p and 0 <= p[0] <= 23 and 0 <= p[1] <= 59):
                err = "❌ Например: 29.10 15:00 — или «срочно»"
            else:
                t = f"{p[0]:02d}:{p[1]:02d}"
                when = datetime.strptime(f"{d:%Y-%m-%d} {t}", "%Y-%m-%d %H:%M").replace(tzinfo=TZ)
                if when < now_dt():
                    err = "❌ Это время уже прошло"
                else:
                    upd = {"urgent": False, "trip_date": f"{d:%Y-%m-%d}", "trip_time": t}
    elif field == "comment":
        if raw == "-":
            upd = {"wishes": None}
        elif 0 < len(raw) <= 500:
            upd = {"wishes": raw}
        else:
            err = "❌ До 500 знаков или «-»"
    if err:
        await safe_send(uid, err); return
    await DB.order_upd(oid, **upd)
    await state.clear()
    od = await DB.order(oid)
    bg(update_channel_post(oid, keep_take=True), f"канал #{oid}")
    is_disp = od["dispatcher_id"] == uid
    await safe_send(uid, f"✅ Заказ #{oid} обновлён\n\n{fmt_order(od)}",
                    reply_markup=kb_dispatcher() if is_disp else kb_main())
    if od.get("driver_id") and od["status"] == "taken":
        bg(safe_send(od["driver_id"], f"ℹ️ <b>Заказ #{oid} изменён</b>\n\n{fmt_order(od)}"), f"водителю #{oid}")
    if not is_disp:
        bg(safe_send(od["dispatcher_id"], f"ℹ️ <b>Администратор поправил ваш заказ #{oid}</b>\n\n{fmt_order(od)}"),
           f"диспетчеру #{oid}")


@router.message(StateFilter("*"))
async def unknown_state_after_restart(msg: Message, state: FSMContext):
    """
    Обработчик для случаев, когда FSM-состояние сброшено (например, после перезапуска бота).
    Автоматически восстанавливает работу FSM-функций.
    """
    uid = msg.from_user.id
    cur = await state.get_state()
    
    # Случай 1: пользователь в активном FSM-шаге, но прислал текст вместо кнопки
    if cur is not None:
        await safe_send(
            uid,
            "ℹ️ Пожалуйста, используйте кнопки выше, чтобы продолжить."
        )
        return
    
    # Случай 1а: человек отвечает на сообщение администратора — пересылаем
    if relay_active(uid) and (msg.text or "").strip():
        drv = await DB.driver(uid)
        if drv:
            who = f"водителя {drv_name(drv)} "
        else:
            try:
                pas = await DB.passenger(uid)
            except Exception:
                pas = None
            who = f"пассажира {esc(pas.get('name'))} " if pas and pas.get("name") else "пассажира "
        reply_kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="💬 Ответить", callback_data=f"admsg_{uid}")
        ]])
        for admin_id in ADMIN_IDS:
            await safe_send(admin_id,
                f"💬 <b>Ответ {who}</b>\nID: <code>{uid}</code>\n\n{esc(msg.text)}",
                reply_markup=reply_kb)
        await safe_send(uid, "✅ Сообщение передано администратору.")
        return

    # Случай 2: неизвестный текст или левая команда — сбрасываем состояние
    # (все известные кнопки уже перехвачены своими хендлерами выше по файлу —
    #  сюда мы попадаем, только если ни один из них не подошёл)
    await state.clear()
    await safe_send(
        uid,
        "🔄 Состояние сброшено. Нажмите нужную кнопку снова.",
        reply_markup=kb_main()
    )

@router.callback_query()
async def cb_fallback(call: CallbackQuery):
    await call.answer("⚠️ Неизвестная команда")

# ══════════════ ЗАПУСК ══════════════
RUN_POLLING = os.environ.get("RUN_POLLING", "true").lower() != "false"

# ══════════════ САЙТ мтранс.рф ══════════════
# Сайт отдаёт сам бот: site.zip из репозитория распаковывается при запуске.
# Нет архива — бот работает как раньше, только API.
class SiteFiles(StaticFiles):
    """Страницы браузер сверяет при каждом открытии, остальное (CSS и JS
    с ?v=, шрифты, картинки) держит неделю."""
    async def get_response(self, path, scope):
        r = await super().get_response(path, scope)
        if r.status_code == 200:
            r.headers["Cache-Control"] = ("no-cache" if r.headers.get("content-type", "").startswith("text/html")
                                          else "public, max-age=604800")
        return r


def _site_files():
    here = os.path.dirname(os.path.abspath(__file__))
    src, dst = os.path.join(here, "site.zip"), os.path.join(here, "site")
    if not os.path.isfile(src):
        log.warning("site.zip нет — сайт не отдаём, только API")
        return None
    import shutil, zipfile
    shutil.rmtree(dst, ignore_errors=True)
    with zipfile.ZipFile(src) as z:
        z.extractall(dst)
    return SiteFiles(directory=dst, html=True)


_SITE = _site_files()
if _SITE:
    api.mount("/", _SITE, name="site")      # последним: маршруты API выше него


async def main():
    log.info("=" * 50)
    log.info("  🚕 МЕЖГОРОД ТРАНСФЕР v23.14 (aiogram 3 + FSM + MAX)")
    log.info(f"  Режим: {'ПОЛНЫЙ (бот + API)' if RUN_POLLING else 'ТОЛЬКО WEB API (домен)'}")
    log.info("=" * 50)
    await _init_pool()
    await DB.init()
    _BL_CACHE.update(await DB.bl_all())
    await _load_max_secret_flag()
    bg(metrika_check(), "проверка Метрики")

    import uvicorn
    api_port = int(os.environ.get("PORT", 8080))

    async def _run_api_safely():
        """Веб-API не должен ронять весь процесс (включая Telegram-бота),
        если порт занят или сервер по другой причине не поднялся.
        Несколько попыток — вдруг порт освобождается с задержкой после передеплоя."""
        for attempt in range(1, 6):
            try:
                api_config = uvicorn.Config(api, host="0.0.0.0", port=api_port, log_level="warning",
                                            forwarded_allow_ips="*")   # https за прокси Bothost
                api_server = uvicorn.Server(api_config)
                await api_server.serve()
                return
            except SystemExit as e:
                log.error(f"⚠️ Попытка {attempt}/5: Web API не поднялся (SystemExit {e.code}), "
                          f"порт {api_port} занят.")
            except Exception as e:
                log.error(f"⚠️ Попытка {attempt}/5: Web API упал: {e}")
            if attempt < 5:
                await asyncio.sleep(3)
        log.error("❌ Web API так и не запустился за 5 попыток. Бот продолжает работать без API.")

    api_task = asyncio.create_task(_run_api_safely())
    log.info(f"  🌐 Web API запущен на http://0.0.0.0:{api_port} (/api/order)")

    async def _max_delayed_register():
        # Ждём, пока uvicorn точно примет соединения, иначе MAX
        # может проверить адрес раньше, чем он отвечает.
        await asyncio.sleep(5)
        await _max_register_webhook()

    if MAX_ENABLED and MAX_WEBHOOK_URL:
        bg(_max_delayed_register(), "подписка MAX")

    if not RUN_POLLING:
        # Этот инстанс существует только ради веб-API с доменом.
        # Telegram-опрос (getUpdates) НЕ запускаем, чтобы не конфликтовать
        # с основным ботом intercity_bot1, который делает polling.
        try:
            await api_task
        finally:
            await bot.session.close()
            if _pg_pool:
                await _pg_pool.close()
        return

    _BL_CACHE.update(await DB.bl_all())
    cleaner_task = asyncio.create_task(_notified_cleaner())
    trial_task   = asyncio.create_task(_trial_expiry_notifier())
    expired_task = asyncio.create_task(_expired_orders_cleaner())
    outbox_task  = asyncio.create_task(_outbox_worker())
    announce_task = asyncio.create_task(_announce_worker())
    db_task = asyncio.create_task(_db_watch())
    try:
        await dp.start_polling(bot, allowed_updates=["message", "callback_query"])
    finally:
        cleaner_task.cancel()
        trial_task.cancel()
        expired_task.cancel()
        outbox_task.cancel()
        announce_task.cancel()
        db_task.cancel()
        await _max_close_session()
        api_task.cancel()
        # Дожидаемся всех отменённых задач, иначе при остановке в лог
        # сыплются жалобы на незавершённые задачи.
        for t in (cleaner_task, trial_task, expired_task,
                  outbox_task, announce_task, db_task, api_task):
            try:
                await t
            except asyncio.CancelledError:
                pass
        await bot.session.close()
        if _pg_pool:
            await _pg_pool.close()

if __name__ == "__main__":
    asyncio.run(main())